window.__CHRONICLE_CHUNK["cn-14"] = [
  {id:"cn--1998--p01",track:"cn",year:1998,yearApprox:false,dim:"politics",weight:3,title:"九届全国人大一次会议组成国家机构",summary:"会议选举决定新一届国家机构领导人员，朱镕基任总理。",detail:{background:"1998年3月，政协九届全国委员会一次会议与九届全国人大一次会议先后在北京召开，后者议程包括审议国务院机构改革方案。",process:"3月5日至19日，九届全国人大一次会议在北京举行，选举江泽民为中华人民共和国主席、胡锦涛为副主席，决定朱镕基为国务院总理，并听取审议《关于国务院机构改革方案的说明》、批准该改革方案。",impact:"按宪法程序完成国家机构换届，新组建的国务院组成部门据此进入运作。",figures:["江泽民","朱镕基","胡锦涛"],place:"北京（人民大会堂）",state:"中华人民共和国",sources:["新华社1998年3月19日报道","《九届全国人大一次会议文件汇编》（中国民主法制出版社1998年）"],"tags":["全国人大","国家机构换届","国务院"]},related:["cn--1998--i02", "cn--1993--p01"]},
  {id:"cn--1998--i01",track:"cn",year:1998,yearApprox:false,dim:"institution",weight:3,title:"村民委员会组织法颁布施行",summary:"1998年11月4日通过并公布施行，取代1987年试行法。",detail:{background:"1987年试行法施行后，村民直接选举在全国推开，试行中暴露的选举程序、村务公开与民主监督等问题需要以正式法律规范。",process:"1998年11月4日，九届全国人大常委会第五次会议通过《中华人民共和国村民委员会组织法》，自公布之日起施行；法律规定村民委员会由主任、副主任和委员共三至七人组成，由村民直接选举产生，任何组织或者个人不得指定、委派或者撤换，村民会议可以讨论决定本村公共事务和公益事业，村委会实行村务公开、接受民主评议。",impact:"把村委会选举与村务监督纳入正式法律程序；2010年10月28日该法再次修订，细化竞选、投票与委托投票等组织程序。",figures:["李鹏"],place:"北京",state:"中华人民共和国",sources:["《中华人民共和国村民委员会组织法》（1998年11月4日第九届全国人民代表大会常务委员会第五次会议通过）","新华社1998年11月5日报道"],"tags":["基层群众自治","村委会选举","村务公开"]},related:["cn--1987--i01", "cn--1983--i01"]},
  {id:"cn--1998--i02",track:"cn",year:1998,yearApprox:false,dim:"institution",weight:3,title:"国务院机构改革方案获批实施",summary:"1998年3月10日批准方案，组成部门由40个减为29个。",detail:{background:"1993年改革后国务院仍设多个专业经济管理部门，政企不分、机构重叠与财政供养人员过多的问题持续受到讨论。",process:"1998年3月10日，九届全国人大一次会议第二次会议通过国务院机构改革方案；据该方案说明，国务院组成部门由40个减少到29个，多个专业经济部门被撤销或改为行业协会，各部门行政编制总数大幅缩减。",impact:"这是1949年后第七次大规模政府机构改革，此后2003年、2008年、2013年、2018年、2023年又分批推进机构改革，职能转变成为主线。",figures:["朱镕基"],place:"北京",state:"中华人民共和国",sources:["《关于国务院机构改革方案的说明》（1998年3月6日九届全国人大一次会议）","新华社1998年3月11日报道"],"tags":["行政体制改革","政企分开","国务院"]},related:["cn--1998--p01", "cn--1982--i02", "cn--1988--i01"]},
  {id:"cn--1998--e01",track:"cn",year:1998,yearApprox:false,dim:"economy",weight:4,title:"停止住房实物分配启动住房商品化",summary:"1998年7月国务院通知要求停止住房实物分配，实行货币化。",detail:{background:"1980年代起住房制度改革以提租补贴、出售公房与建经济适用住房为试点内容，单位实物分房仍占主导，1997年住房滞销与内需不足促使政策提速。",process:"1998年7月3日，《国务院关于进一步深化城镇住房制度改革加快住房建设的通知》发布，要求自1998年下半年起停止住房实物分配、逐步实行住房分配货币化，同时完善住房公积金制度、建立以经济适用住房为主的多层次城镇住房供应体系，并允许符合条件的商业性个人住房贷款。",impact:"城镇住房供应由此转向以商品住宅为主体。据国家统计局年度数据，全国商品住宅销售面积由1998年的不足1亿平方米增长至2021年的15亿余平方米；据第七次全国人口普查（2020年），全国人均住房建筑面积41.76平方米。2003年8月《国务院关于促进房地产市场持续健康发展的通知》进一步确认房地产业为国民经济支柱产业。",figures:["朱镕基"],place:"北京",state:"中华人民共和国",sources:["国发〔1998〕23号文件（1998年7月3日）","国家统计局编《中国统计年鉴》各卷","国家统计局《第七次全国人口普查公报》（2021年5月）"],"tags":["住房制度改革","住房商品化","住房公积金"]},related:["cn--1987--e01", "cn--1998--e03"]},
  {id:"cn--1998--e02",track:"cn",year:1998,yearApprox:false,dim:"economy",weight:3,title:"纺织工业压锭被列为国企改革突破口",summary:"1998年起以压缩落后棉纺锭推进国有大中型企业三年脱困。",detail:{background:"1990年代末纺织行业产能过剩、产品积压，国有企业亏损面较大；1997年国务院提出用三年左右时间使大多数国有大中型亏损企业摆脱困境的目标。",process:"1998年，国家把纺织工业作为国有企业改革与结构调整的突破口，压缩落后棉纺锭、分流安置下岗职工，并配套中央补助资金与银行核销坏账政策；据国家经贸委当年公布的口径，压锭与重组同步推进，纺织行业盈利状况在1999年后改善。",impact:"到2000年，官方宣布国有大中型企业亏损面明显收窄、改革脱困目标初步实现；同期形成的再就业服务中心与下岗职工基本生活保障制度，成为2000年后城市社会保障体系建设的组成部分。",figures:["朱镕基"],place:"北京及上海、辽宁等老工业基地",state:"中华人民共和国",sources:["国家经济贸易委员会1998年至2000年发布的纺织工业压锭调整与国有大中型企业脱困相关文件","《中国共产党的九十年》（中共党史出版社2016年）"],"tags":["国有企业改革","纺织压锭","再就业"]},related:["cn--1993--e01", "cn--1992--i01"]},
  {id:"cn--1998--e03",track:"cn",year:1998,yearApprox:false,dim:"economy",weight:4,title:"积极财政政策起步与长期建设国债",summary:"1998年发行1000亿元长期建设国债，扩大内需成为立足点。",detail:{background:"亚洲金融危机冲击出口、国内需求偏弱且物价低位运行，1998年3月《政府工作报告》提出扩大国内需求、实施积极的财政政策和稳健的货币政策。",process:"1998年8月，九届全国人大常委会第四次会议批准国务院提出的方案，向国有商业银行发行1000亿元一年期以上长期建设国债，用于农林水利、交通通信、城市基础设施与赈灾造林等建设；同年中国人民银行三次下调金融机构存贷款基准利率，并增加对基础设施建设的信贷投入。",impact:"据财政部公布的预算执行数据，1998年中央财政赤字由年初预算的460亿元增加到960亿元；1998年至2004年连续发行长期建设国债，投资拉动使1998年国内生产总值增长7.8%（国家统计局口径），此后扩大内需成为宏观调控的基本立足点。",figures:["朱镕基","戴相龙"],place:"北京",state:"中华人民共和国",sources:["1998年《政府工作报告》（1998年3月5日）","全国人民代表大会常务委员会关于批准发行长期建设国债的决定（1998年8月）","国家统计局编《中国统计年鉴（1999）》"],"tags":["积极财政政策","长期建设国债","扩大内需"]},related:["cn--1997--e01", "cn--1998--e01"]},
  {id:"cn--1998--d01",track:"cn",year:1998,yearApprox:false,dim:"disaster",weight:4,title:"长江嫩江松花江发生特大洪水",summary:"1998年夏秋多个流域发生洪涝，解放军与武警部队参加抢险。",detail:{background:"1998年6月中旬起长江流域持续强降雨，鄱阳湖、洞庭湖水位超历史纪录，7月下旬至8月嫩江、松花江与西江亦出现超保证水位洪水。",process:"据民政部公布的1998年灾情统计口径，全国有29个省（自治区、直辖市）遭受洪涝灾害，受灾人口约1.86亿人，倒塌房屋约690万间，直接经济损失约1660亿元；解放军和武警部队累计投入约36万人次参加抢险，沿江军民加固大堤、分洪蓄洪。1998年9月28日中共中央、国务院、中央军委召开全国抗洪抢险总结表彰大会，把此次抗灾概括为“万众一心、众志成城，不怕困难、顽强拼搏，坚韧不拔、敢于胜利”的抗洪精神。",impact:"灾后国务院作出加强水利建设的部署，1998年起推行长江中上游防护林建设、退田还湖、平垸行洪与移民建镇，1999年起实施天然林保护工程并停止长江上游天然林商业性采伐；同年发行的长期建设国债大量投向灾后基础设施重建。",figures:["江泽民","朱镕基"],place:"长江中下游、嫩江松花江流域及西江流域",state:"中华人民共和国",sources:["民政部1998年度全国自然灾害灾情统计口径","新华社1998年9月29日关于全国抗洪抢险总结表彰大会的报道","国务院1998年后关于灾后重建与水利建设的公开部署及新华社相关报道"],"tags":["特大洪水","抗洪抢险","退田还湖"]},related:["cn--1991--d01", "cn--1998--e03"]},
  {id:"cn--1998--m01",track:"cn",year:1998,yearApprox:false,dim:"military",weight:3,title:"军队武警部队和政法机关停止经商",summary:"1998年中央决定军队、武警和政法机关一律不再从事经商。",detail:{background:"1980年代中期起允许部队从事生产经营以弥补经费不足，1990年代后期经商活动引发的违规与腐败问题被集中查处，走私案件牵涉部分单位和人员。",process:"1998年，中共中央、国务院、中央军事委员会作出军队、武警部队和政法机关一律不再从事经商活动的决定，明确所办经营性企业一律移交地方管理，同年7月起先后召开专题工作会议部署清查与移交；同期全国开展打击走私违法犯罪活动。",impact:"据中央相关工作会议通报口径，军队和武警部队所属企业于1999年底前基本完成移交与撤销，国防费由此成为部队供给的主要来源，1998年后中央财政对国防支出的拨款规模逐年增长。",figures:["江泽民","张震"],place:"北京",state:"中华人民共和国",sources:["新华社1998年关于军队和武警部队不再从事经商活动的报道","《中国共产党的九十年》（中共党史出版社2016年）"],"tags":["军队停止经商","政企分开","国防费"]},related:["cn--1993--i01", "cn--1998--e03"]},
  {id:"cn--1999--p01",track:"cn",year:1999,yearApprox:false,dim:"politics",weight:4,title:"中国政府对澳门恢复行使主权",summary:"1999年12月20日中葡政权交接，澳门特别行政区成立。",detail:{background:"1987年4月13日中葡两国政府签署联合声明，确认中国政府于1999年12月20日对澳门恢复行使主权；1993年3月31日八届全国人大一次会议通过《中华人民共和国澳门特别行政区基本法》，规定1999年12月20日起施行。",process:"1999年12月19日夜至20日凌晨，中葡两国政府澳门政权交接仪式在澳门文化中心花园馆举行；12月20日澳门特别行政区政府和澳门特别行政区法院成立，何厚铧就任第一任行政长官，中国人民解放军驻澳门部队同时进驻。",impact:"澳门由此进入特别行政区制度运作阶段，行政与立法机关按基本法和全国人大常委会关于产生办法的决定产生；2003年10月签署《内地与港澳关于建立更紧密经贸关系的安排》、2003年起实施内地居民个人赴港澳旅游，2009年1月国务院通过《珠江三角洲地区改革发展规划纲要》并部署横琴开发；据澳门统计暨普查局公布的年度数据，2019年澳门本地生产总值按可比口径明显高于1999年，2020年起受疫情冲击回落。",figures:["江泽民","何厚铧","韦奇立"],place:"澳门",state:"中华人民共和国",sources:["《中葡联合声明》（1987年4月13日签署）、《中华人民共和国澳门特别行政区基本法》（1993年通过）","新华社1999年12月21日报道"],"tags":["澳门回归","一国两制","基本法"]},related:["cn--1987--p02", "cn--1997--p01"]},
  {id:"cn--1999--p02",track:"cn",year:1999,yearApprox:false,dim:"politics",weight:4,title:"北约导弹击中中国驻南联盟大使馆",summary:"5月8日使馆遭轰炸，3名中国记者遇难，中美关系严重受挫。",detail:{background:"1999年3月24日起，北约对南斯拉夫联盟共和国实施空袭，中国政府反对未经联合国安理会授权的军事行动并多次表态呼吁政治解决。",process:"贝尔格莱德时间1999年5月7日深夜（北京时间5月8日凌晨），北约B-2型轰炸机发射的导弹击中中国驻南斯拉夫联盟大使馆，新华社记者邵云环、《光明日报》记者许杏虎与朱颖遇难，数十人受伤，馆舍严重毁坏；5月9日中国政府发表声明并提出最强烈抗议，北京等地出现民众示威活动；美方称系“误炸”，中方要求全面、严格调查。",impact:"这一事件使1999年至2000年的中美关系陷入严重困难，两国元首于1999年9月在新西兰奥克兰亚太经合组织领导人非正式会议期间会晤后关系逐步修复；据外交部公布的信息，中方就死伤赔偿与馆舍损失与美方进行交涉，美方于1999年12月支付赔偿金。",figures:["江泽民","朱镕基"],place:"贝尔格莱德（今塞尔维亚共和国首都）",state:"中华人民共和国",sources:["中国政府1999年5月9日声明（新华社受权发布）","新华社1999年5月关于驻南联盟大使馆被炸事件的系列报道"],"tags":["中美关系","使馆被炸","外交抗议"]},related:["cn--1999--e01", "cn--1997--p01"]},
  {id:"cn--1999--e01",track:"cn",year:1999,yearApprox:false,dim:"economy",weight:3,title:"中美就中国入世达成双边协议",summary:"1999年11月15日双方签署协议，扫清入世主要障碍。",detail:{background:"1986年7月申请恢复关贸总协定缔约国地位后，复关及加入世界贸易组织谈判长期进行，美国是关键双边谈判对手，1999年谈判曾一度中断。",process:"1999年11月15日，对外贸易经济合作部部长石广生与美国贸易代表巴尔舍夫斯基在北京签署《关于中国加入世界贸易组织的双边协议》，就市场开放、关税减让、农业与服务业准入、非市场经济地位与特保条款等作出安排；同年12月中国与欧盟结束双边谈判。",impact:"该协议使中国加入世界贸易组织的多边谈判进入最后阶段，2001年11月10日第四届部长级会议通过中国加入决定；据海关总署统计，中国货物进出口总额由1999年的3606亿美元增至2013年的4.16万亿美元。",figures:["石广生","巴尔舍夫斯基","龙永图"],place:"北京",state:"中华人民共和国",sources:["新华社1999年11月16日报道","外经贸部1999年11月15日关于中美达成中国入世双边协议的新闻公报","海关总署历年《中国海关统计》"],"tags":["世界贸易组织","入世谈判","中美经贸"]},related:["cn--1986--e01", "cn--2001--e01"]},
  {id:"cn--1999--i01",track:"cn",year:1999,yearApprox:false,dim:"institution",weight:4,title:"1999年宪法修正案通过",summary:"把邓小平理论、依法治国与基本经济制度写入宪法。",detail:{background:"1997年中共十五大把邓小平理论确立为党的指导思想，1998年宪法实施与修改问题由中共中央1999年1月向全国人大提出建议。",process:"1999年3月15日，九届全国人大二次会议通过宪法修正案，把邓小平理论、发展社会主义市场经济与依法治国、建设社会主义法治国家写入宪法；明确公有制为主体、多种所有制经济共同发展是基本经济制度，个体经济、私营经济等非公有制经济是社会主义市场经济的重要组成部分；把“反革命活动”改为“危害国家安全的犯罪行为”。",impact:"1982年现行宪法至此经过1988年、1993年、1999年三次修正；2004年、2018年又两次修正，其中国家尊重和保障人权、私有财产保护与监察委员会等条款分别在后续修正案中加入。",figures:["李鹏"],place:"北京",state:"中华人民共和国",sources:["《中华人民共和国宪法修正案（1999年）》","新华社1999年3月16日报道"],"tags":["宪法修正","依法治国","非公有制经济"]},related:["cn--1993--i01", "cn--1988--i01"]},
  {id:"cn--1999--s01",track:"cn",year:1999,yearApprox:false,dim:"science",weight:3,title:"神舟一号完成首次无人飞行试验",summary:"1999年11月20日发射，中国载人航天工程首飞成功。",detail:{background:"1992年9月中国载人航天工程确立“三步走”发展蓝图，第一步为发射无人试验飞船验证系统；1990年代后期长征二号F运载火箭与飞船配套系统陆续完成研制和地面试验。",process:"1999年11月20日，第一艘无人试验飞船神舟一号在酒泉卫星发射中心由长征二号F运载火箭发射升空，按预定轨道飞行后返回舱在内蒙古中部预定区域成功着陆，考核了火箭、飞船回收与测控等关键技术。",impact:"据中国载人航天工程办公室公布的任务序列，此后神舟二号（2001年1月）、神舟三号（2002年3月）、神舟四号（2002年12月）接续完成无人飞行试验，2003年10月神舟五号实现首次载人飞行。",figures:["任新民","王永志"],place:"酒泉卫星发射中心（内蒙古中部着陆）",state:"中华人民共和国",sources:["中国载人航天工程办公室发布的神舟飞船任务信息","新华社1999年11月22日报道"],"tags":["载人航天","神舟一号","酒泉"]},related:["cn--1992--s01", "cn--2003--s01"]},
  {id:"cn--1999--m01",track:"cn",year:1999,yearApprox:false,dim:"military",weight:3,title:"国庆五十周年举行庆祝大会与阅兵",summary:"1999年10月1日北京举行阅兵，为改革开放后第二次国庆阅兵。",detail:{background:"1999年10月1日为中华人民共和国成立五十周年纪念日，中央决定举行庆祝大会、阅兵和群众游行；1984年国庆三十五周年阅兵是此前改革开放时期唯一一次国庆阅兵。",process:"1999年10月1日，庆祝大会在天安门广场举行，江泽民检阅三军部队并发表讲话，李鹏主持大会；受阅部队由陆海空三军、武警和民兵预备役组成，装备方队展示的主战装备多为国产现役型号，空中梯队首次展示第二代主战战斗机与新型轰炸机机型；当晚举行焰火晚会和群众游行。",impact:"据新华社报道口径，此次阅兵集中展示国防和军队现代化建设的装备成果；2009年10月1日、2019年10月1日又先后举行国庆六十周年、七十周年庆祝大会与阅兵式。",figures:["江泽民","李鹏"],place:"北京（天安门广场）",state:"中华人民共和国",sources:["新华社1999年10月2日报道","《中国共产党的九十年》（中共党史出版社2016年）"],"tags":["国庆阅兵","1999年","军队装备"]},related:["cn--1984--m01", "cn--1999--p01"]},
  {id:"cn--2000--i01",track:"cn",year:2000,yearApprox:false,dim:"institution",weight:4,title:"中华人民共和国立法法通过",summary:"2000年3月15日通过，规范法律、法规与规章的立法权限。",detail:{background:"1979年后立法权逐步下放至省级人大与较大的市，立法冲突、越权设定许可与处罚等问题需要统一的规则约束。",process:"2000年3月15日，九届全国人大三次会议通过《中华人民共和国立法法》，自2000年7月1日起施行；法律划分全国人大及其常委会的专属立法事项，规定行政法规、地方性法规、自治条例和单行条例、规章的适用规则与备案审查制度，并确立法律案“三审制”的一般程序。",impact:"据全国人大常委会法制工作委员会的立法资料，2000年后法律案统一适用该法的审议与备案程序；2015年3月15日修改后赋予所有设区的市地方立法权，2023年3月13日再次修正，加强合宪性审查与备案审查。",figures:["李鹏","乔石"],place:"北京",state:"中华人民共和国",sources:["《中华人民共和国立法法》（2000年3月15日通过）、新华社2000年3月16日报道"],"tags":["立法体制","备案审查","专属立法权"]},related:["cn--1986--i02", "cn--1979--i01"]},
  {id:"cn--2000--i02",track:"cn",year:2000,yearApprox:false,dim:"institution",weight:2,title:"关于维护互联网安全的决定通过",summary:"2000年12月28日人大常委会作出决定，确立网络活动边界。",detail:{background:"1994年中国接入国际互联网后网民与网站数量快速增长，利用网络实施的危害国家安全、扰乱社会秩序与侵犯权益的行为缺乏统一法律界定。",process:"2000年12月28日，九届全国人大常委会第十九次会议通过《关于维护互联网安全的决定》，就利用互联网危害国家安全、扰乱社会秩序、破坏经济秩序与侵犯人身财产权利等行为明确依照刑法等追究责任；同月国务院公布《互联网信息服务管理办法》，将互联网信息服务分为经营性与非经营性两类。",impact:"此后《全国人大常委会关于加强网络信息保护的决定》（2012年12月28日）、《网络安全法》（2016年11月7日通过、2017年6月1日施行）与《数据安全法》《个人信息保护法》（2021年）相继出台，形成网络空间治理的法律框架。",figures:["李鹏"],place:"北京",state:"中华人民共和国",sources:["《全国人大常委会关于维护互联网安全的决定》（2000年12月28日）、国务院《互联网信息服务管理办法》（2000年9月公布）"],"tags":["网络治理","互联网信息服务","网络安全"]},related:["cn--1994--s01", "cn--2000--i01"]},
  {id:"cn--2000--s01",track:"cn",year:2000,yearApprox:false,dim:"science",weight:4,title:"北斗导航试验卫星发射建成北斗一号",summary:"2000年10月与12月发射两颗试验卫星，建成北斗一号系统。",detail:{background:"1994年北斗卫星导航系统工程立项，确立由有源定位的区域试验系统起步、再逐步建成全球系统的“三步走”路线。",process:"2000年10月31日与12月21日，两颗北斗导航试验卫星先后由长征三号甲运载火箭从西昌卫星发射中心发射入轨，建成北斗一号系统，为中国境内用户提供定位、授时与双向短报文通信服务。",impact:"据中国卫星导航系统管理办公室发布的进展信息，2004年起北斗二号区域组网，2012年12月27日正式向亚太地区提供无源定位服务，2020年6月23日最后一颗组网卫星发射后同年7月31日北斗三号全球卫星导航系统开通；据该白皮书公布的星座构成，北斗三号全球系统由3颗地球静止轨道、3颗倾斜地球同步轨道与24颗中圆地球轨道卫星组成。",figures:["孙家栋","王永志"],place:"西昌卫星发射中心",state:"中华人民共和国",sources:["中国卫星导航系统管理办公室《中国北斗卫星导航系统》白皮书（2013年12月）","新华社2000年11月1日、12月22日报道"],"tags":["北斗卫星导航","有源定位","短报文通信"]},related:["cn--1996--i01", "cn--2020--s01"]},
  {id:"cn--2000--s02",track:"cn",year:2000,yearApprox:false,dim:"science",weight:3,title:"中国参与人类基因组计划完成1%任务",summary:"2000年6月工作框架图完成，中国是唯一参与的发展中国家。",detail:{background:"1990年启动的国际人类基因组计划由美、英、法、德、日、中六国科学家合作实施，中国于1999年9月获准参与其中1%的测序任务。",process:"2000年6月26日，六国政府首脑与国家科学院联合宣布人类基因组工作框架图绘制完成，中国如期完成所承担的3号染色体短臂末端约3000万个碱基对的测序；参与单位为中国科学院遗传研究所（北京华大基因研究中心前身）等机构，负责人为杨焕明。",impact:"据科技部公布的信息，中国在此基础上建立基因组研究平台，2001年10月国际团队在《自然》杂志发表工作框架图论文、2003年4月宣布完成测序；此后中国基因组学与生物信息学能力进入农业、医学测序产业，华大基因等机构于2007年实现完整人类基因组测序。",figures:["杨焕明"],place:"北京",state:"中华人民共和国",sources:["2000年6月26日六国联合声明（新华社报道）、《自然》杂志2001年2月发表的人类基因组工作框架图论文"],"tags":["人类基因组计划","基因测序","国际科技合作"]},related:["cn--1986--s01", "cn--1995--s01", "world--2001--s01"]},
  {id:"cn--2000--e01",track:"cn",year:2000,yearApprox:false,dim:"economy",weight:3,title:"西部大开发战略进入实施阶段",summary:"2000年1月成立领导小组，12月首批重点工程开工。",detail:{background:"1999年9月中共十五届四中全会提出国家实施西部大开发战略、支持中西部地区加快改革开放，11月中央经济工作会议把其列为当年和今后的重要任务。",process:"2000年1月16日，国务院成立西部地区开发领导小组及其办公室；同年10月十五届五中全会把推进西部大开发写入“十五”计划建议；据新华社2000年12月报道，西部开发首批重点工程在当年陆续开工，涉及交通、能源、水利与生态建设等领域。",impact:"据国家统计局公布的分地区年度数据，2000年后西部12个省（自治区、直辖市）生产总值增速多次高于东部地区，占全国比重逐步回升；同期退耕还林还草（1999年试点、2000年扩大）、西气东输与青藏铁路等工程相继实施，2014年后相关省份又纳入“一带一路”建设布局。",figures:["朱镕基"],place:"陕西、重庆、内蒙古等西部12省区市",state:"中华人民共和国",sources:["国务院2000年关于成立西部地区开发领导小组的通知","新华社2000年12月关于首批西部开发重点工程开工的报道","国家统计局编《中国统计年鉴》各卷"],"tags":["西部大开发","区域协调","退耕还林"]},related:["cn--1999--p02", "cn--2006--e01"]},
  {id:"cn--2001--e01",track:"cn",year:2001,yearApprox:false,dim:"economy",weight:5,title:"中国成为世界贸易组织第143个成员",summary:"2001年11月10日多哈会议通过决定，12月11日正式加入。",detail:{background:"1986年7月申请恢复关贸总协定缔约国地位，1995年后转为加入世界贸易组织谈判，1999年11月与美、2000年与欧完成双边市场准入谈判。",process:"2001年11月10日，世界贸易组织第四次部长级会议在卡塔尔多哈审议通过中国加入的决定；12月11日中国正式成为第143个成员，并履行降低关税、开放服务业、清理涉外经济法规与接受贸易政策年度审议等承诺，2001年前后集中修改与废止了大量法律法规。",impact:"据海关总署统计，中国货物进出口总额由2001年的5098亿美元增至2013年的4.16万亿美元、2023年的41.75万亿元人民币；据世界贸易组织统计口径，中国货物贸易进出口位次由2001年的第六位升至第一位。加入后中国以《对外贸易法》（2004年4月6日修订）等衔接世贸规则，同时按承诺开放银行、保险与分销领域。",figures:["石广生","龙永图","素帕猜"],place:"卡塔尔多哈及北京",state:"中华人民共和国",sources:["世界贸易组织2001年11月10日第四次部长级会议决定与《中国加入议定书》","海关总署历年《中国海关统计》","新华社2001年12月12日报道"],"tags":["世界贸易组织","入世","贸易自由化"]},related:["cn--1999--e01", "cn--1986--e01", "world--2001--i03"]},
  {id:"cn--2001--e02",track:"cn",year:2001,yearApprox:false,dim:"economy",weight:3,title:"青藏铁路格尔木至拉萨段全线开工",summary:"2001年6月29日二期工程开工，2006年7月全线通车。",detail:{background:"青藏铁路西宁至格尔木段1984年建成投入运营；1994年第一次西藏工作座谈会后中央研究进藏铁路方案，2000年提出选用青藏线并开展冻土工程试验。",process:"2001年6月29日，青藏铁路格尔木至拉萨段正式开工建设，线路全长1142公里，其中海拔4000米以上路段约960公里、连续多年冻土区约550公里，需解决冻土路基、高原生态与供氧等工程难题；据铁道部公布的信息，工程对高温不稳定冻土路段采取以桥代路、设置热棒与通风管路基等措施。",impact:"2006年7月1日青藏铁路全线开通试运营（见2006年条目），结束西藏不通铁路的历史；据中国铁路总公司公布的信息，开通以来进藏物资运输中铁路所占比重持续上升，西藏铁路客运量逐年增长。",figures:["傅志寰"],place:"青海格尔木至西藏拉萨",state:"中华人民共和国",sources:["新华社2001年6月30日报道","国务院新闻办公室2006年7月关于青藏铁路通车的新闻发布会记录"],"tags":["青藏铁路","高原冻土","西部开发"]},related:["cn--2000--e01", "cn--2006--s01"]},
  {id:"cn--2001--p01",track:"cn",year:2001,yearApprox:false,dim:"politics",weight:3,title:"亚太经合组织第九次领导人会议在上海举行",summary:"2001年10月20日至21日在上海举行，通过《领导人宣言》。",detail:{background:"亚太经合组织2000年文莱会议确定由中国主办2001年领导人非正式会议，这是中国首次主办该机制会议，时为加入世界贸易组织前后。",process:"2001年10月20日至21日，亚太经合组织第九次领导人非正式会议在上海举行，21位成员领导人或代表出席并通过《领导人宣言》（即“上海共识”），确定贸易投资自由化、加强能力建设与抵制恐怖主义等议程，会议主题为“新世纪、新挑战：参与、合作，促进共同繁荣”。",impact:"此后中国多次主办APEC活动，2014年11月在北京举行第二十二次领导人非正式会议并通过《亚太经合组织北京纲领》；上海会议期间领导人着中式服装的安排被媒体广泛报道，成为此后APEC会议的传统环节之一。",figures:["江泽民"],place:"上海（科技馆）",state:"中华人民共和国",sources:["新华社2001年10月22日报道","外交部《上海共识》2001年10月21日文本"],"tags":["亚太经合组织","上海共识","多边外交"]},related:["cn--1996--p01", "cn--2001--e01"]},
  {id:"cn--2001--i01",track:"cn",year:2001,yearApprox:false,dim:"institution",weight:3,title:"修改后的婚姻法公布施行",summary:"2001年4月28日公布施行，增设禁止家庭暴力等条款。",detail:{background:"1980年婚姻法在1990年代后与事实婚姻、家庭暴力、离婚财产分割等实践问题脱节，2001年1月最高人民法院先行发布司法解释。",process:"2001年4月28日，九届全国人大常委会第二十次会议通过关于修改婚姻法的决定并公布施行；修改后明确禁止重婚、禁止有配偶者与他人同居、禁止家庭暴力，规定因实施家庭暴力等导致离婚时无过错方有权请求损害赔偿，并确立夫妻财产约定与离婚登记程序。",impact:"据最高人民法院公布的司法解释与统计数据，2001年后家庭暴力成为独立裁判事由；2015年12月27日通过、2016年3月1日施行的《反家庭暴力法》确立人身安全保护令制度，2020年5月28日通过的民法典婚姻家庭编进一步修改离婚冷静期与共同财产规则。",figures:["李鹏"],place:"北京",state:"中华人民共和国",sources:["《全国人大常委会关于修改〈中华人民共和国婚姻法〉的决定》（2001年4月28日）、新华社2001年4月29日报道"],"tags":["婚姻法","家庭暴力","离婚损害赔偿"]},related:["cn--1986--i02", "cn--2020--i01"]},
  {id:"cn--2001--c01",track:"cn",year:2001,yearApprox:false,dim:"culture",weight:3,title:"昆曲入选人类口头和非物质遗产代表作",summary:"2001年5月18日联合国教科文组织宣布第一批名录，昆曲在列。",detail:{background:"1997年联合国教科文组织设立“人类口头和非物质遗产代表作”机制，1999年中国以昆曲申报，此前昆曲观众萎缩、院团生存困难。",process:"2001年5月18日，联合国教科文组织在巴黎宣布第一批“人类口头和非物质遗产代表作”，共19个申报项目入选，中国申报的昆曲名列其中；申报由苏州市与江苏省文化部门及北方昆曲剧院等参与。",impact:"2004年文化部等部门启动民族民间文化保护工程，2006年国务院公布第一批国家级非物质文化遗产名录（昆曲列入），2011年2月25日通过《非物质文化遗产法》并于同年6月1日施行；据联合国教科文组织名录，截至2024年12月中国共有43个项目列入相关名录（含2024年12月4日列入的“春节——中国人庆祝传统新年的社会实践”），项目数量为各国之最。",figures:["俞玖林","蔡正仁"],place:"江苏苏州及北京",state:"中华人民共和国",sources:["联合国教科文组织2001年5月18日宣布第一批代表作名录的公告","国务院《关于公布第一批国家级非物质文化遗产名录的通知》（2006年5月20日）"],"tags":["昆曲","非物质遗产","联合国教科文组织"]},related:["cn--2006--c01"]},
  {id:"cn--2002--p01",track:"cn",year:2002,yearApprox:false,dim:"politics",weight:4,title:"中共十六大把三个代表重要思想确立为指导思想",summary:"2002年11月8日至14日召开，通过党章修正案并提出全面建设小康。",detail:{background:"2000年2月江泽民在广东考察工作时提出“三个代表”要求，2001年7月1日在庆祝建党80周年大会上系统阐述，2002年5月31日在中央党校讲话中提出写入的指导方针。",process:"2002年11月8日至14日，中国共产党第十六次全国代表大会在北京举行，江泽民作《全面建设小康社会，开创中国特色社会主义事业新局面》报告；大会通过关于《中国共产党章程（修正案）》的决议，把“三个代表”重要思想同马克思列宁主义、毛泽东思想、邓小平理论一道确立为党的指导思想，并选举新一届中央委员会，胡锦涛当选中央委员会总书记。",impact:"大会提出在本世纪头二十年集中力量全面建设惠及十几亿人口的更高水平的小康社会，并把国内生产总值到2020年力争比2000年翻两番作为目标；据国家统计局数据，2002年国内生产总值为121715亿元，按可比价计算增长9.1%。",figures:["江泽民","胡锦涛"],place:"北京（人民大会堂）",state:"中华人民共和国",sources:["《中国共产党第十六次全国代表大会文件汇编》（人民出版社2002年）","国家统计局《2002年国民经济和社会发展统计公报》"],"tags":["中共十六大","三个代表","党章修改"]},related:["cn--1997--p02", "cn--2007--p01"]},
  {id:"cn--2002--e01",track:"cn",year:2002,yearApprox:false,dim:"economy",weight:3,title:"中国与东盟签署自贸区全面合作框架协议",summary:"2002年11月4日在金边签署，启动十年建成自贸区进程。",detail:{background:"1997年亚洲金融危机后中国与东盟关系走近，2001年11月双方领导人确立十年内建立自由贸易区的方向，2002年1月启动货物贸易早期收获降税磋商。",process:"2002年11月4日，第六次中国与东盟领导人会议在柬埔寨金边举行，双方签署《中国—东盟全面经济合作框架协议》，确定到2010年建成中国—东盟自由贸易区，并附件就早期收获计划降税、服务贸易与投资谈判作出安排；同年7月1日早期收获计划开始实施。",impact:"框架协议确定了货物贸易早期收获降税与服务贸易、投资谈判的路径，2010年1月1日中国—东盟自由贸易区全面建成；据海关总署年度统计，东盟自2020年起成为中国第一大贸易伙伴，2022年1月1日《区域全面经济伙伴关系协定》生效后与自贸区规则叠加。",figures:["朱镕基"],place:"柬埔寨金边",state:"中华人民共和国",sources:["《中国—东盟全面经济合作框架协议》（2002年11月4日）及新华社同期报道","海关总署历年《中国海关统计》"],"tags":["中国东盟自贸区","早期收获","区域经济"]},related:["cn--1997--e01", "cn--2001--e01"]},
  {id:"cn--2002--e02",track:"cn",year:2002,yearApprox:false,dim:"economy",weight:3,title:"入世后首次大规模下调进口关税",summary:"2002年1月1日起5300多种商品降税，关税总水平降至12%。",detail:{background:"《中国加入议定书》附件列明关税减让承诺表，多数降税自2002年1月1日起执行，涉及汽车、化工、农产品与信息技术产品等税目。",process:"据国务院关税税则委员会2001年12月发布的通知，自2002年1月1日起对5300多种商品进口关税作下调调整，关税总水平由15.3%降至12%，其中信息技术产品按《信息技术协定》零关税税率执行，部分农产品实行关税配额管理。",impact:"据海关总署统计，2002年中国进出口总额达6208亿美元，同比增长21.8%，为入世后首个完整年度；此后逐年降税，据财政部口径，中国关税总水平到2021年降至7.4%左右，并自2018年起多次实施暂定税率调整。",figures:["项怀诚"],place:"北京",state:"中华人民共和国",sources:["国务院关税税则委员会2001年12月关于2002年关税调整方案的通知","海关总署《2002年中国海关统计》","财政部2022年1月关于2021年关税总水平的说明"],"tags":["关税减让","入世承诺","进口"]},related:["cn--2001--e01", "cn--1994--e02"]},
  {id:"cn--2002--i01",track:"cn",year:2002,yearApprox:false,dim:"institution",weight:3,title:"农村土地承包法通过",summary:"2002年12月28日通过，2003年3月1日起施行。",detail:{background:"1978年后家庭联产承包责任制在全国推行，但承包期限、调整程序与流转规则长期以政策文件与地方规定为依据，征地与纠纷案件增多。",process:"2002年12月28日，九届全国人大常委会第三十七次会议通过《中华人民共和国农村土地承包法》，自2003年3月1日起施行；法律规定耕地承包期为三十年、草地三十至五十年、林地三十至七十年，承包期内发包方不得调整或收回承包地，明确土地承包经营权流转的原则与方式。",impact:"该法把家庭承包关系的稳定写为法律义务，承包期限与流转规则自此有法可依；2007年12月、2018年12月29日两次修正，增入土地经营权流转与“三权分置”内容，为经营权抵押贷款与农业规模经营提供法律依据。",figures:["王兆国","田纪云"],place:"北京",state:"中华人民共和国",sources:["《中华人民共和国农村土地承包法》（2002年12月28日通过）、新华社2002年12月29日报道"],"tags":["农村土地制度","承包经营权","三权分置"]},related:["cn--1978--e01", "cn--1983--e01"]},
  {id:"cn--2002--s01",track:"cn",year:2002,yearApprox:false,dim:"science",weight:3,title:"南水北调工程正式开工",summary:"2002年12月27日东线一期与中线京石段先期开工。",detail:{background:"1952年毛泽东在考察黄河时提出“南方水多，北方水少，如有可能，借点水来也是可以的”的构想，1992年中共十四大把南水北调列入拟建重大工程，2002年10月国务院批复总体布局。",process:"2002年12月27日，南水北调工程正式开工，东线一期工程与中线工程北京至石家庄段先期建设；按总体布局，工程分东、中、西三条线路，把长江流域水资源调配至淮河、黄河、海河流域，中线以丹江口水库为水源，一期调水规模95亿立方米。",impact:"中线一期工程2014年12月12日通水、东线一期工程2013年11月15日通水；据国务院新闻办公室2022年12月发布会口径，东中线一期工程累计调水超过550亿立方米，直接受益人口超过1.5亿人，沿线城市供水保证率提高。",figures:["温家宝","汪恕诚"],place:"江苏扬州及北京、河北沿线",state:"中华人民共和国",sources:["国务院批复《南水北调工程总体规划》（2002年10月）、新华社2002年12月28日报道","国务院新闻办公室2022年12月关于南水北调东中线一期工程全面通水八年的新闻发布会记录"],"tags":["跨流域调水","南水北调","水资源配置"]},related:["cn--1994--e03", "cn--2000--e01"]},
  {id:"cn--2003--p01",track:"cn",year:2003,yearApprox:false,dim:"politics",weight:3,title:"十届全国人大一次会议完成国家机构换届",summary:"2003年3月选举胡锦涛为国家主席，决定温家宝任国务院总理。",detail:{background:"2002年11月中共十六大完成中央领导层新老交替，2003年3月全国人大按宪法程序改选国家机构领导人员。",process:"2003年3月5日至18日，十届全国人大一次会议在北京举行；会议选举胡锦涛为中华人民共和国主席、曾庆红为副主席，根据国家主席提名决定温家宝为国务院总理；会议批准国务院机构改革方案，决定设立国务院国有资产监督管理委员会、中国银行业监督管理委员会，组建商务部，不再保留对外贸易经济合作部与国家经济贸易委员会。",impact:"2003年10月中共十六届三中全会通过《关于完善社会主义市场经济体制若干问题的决定》，提出坚持以人为本、树立全面协调可持续的发展观；同年12月中共中央印发《中国共产党党内监督条例（试行）》与《中国共产党党员权利保障条例》。",figures:["胡锦涛","温家宝","曾庆红"],place:"北京（人民大会堂）",state:"中华人民共和国",sources:["新华社2003年3月18日报道","《关于国务院机构改革方案的说明》（2003年3月6日十届全国人大一次会议）"],"tags":["全国人大","国家机构换届","机构改革"]},related:["cn--2002--p01", "cn--1998--i02"]},
  {id:"cn--2003--e01",track:"cn",year:2003,yearApprox:false,dim:"economy",weight:3,title:"东北地区等老工业基地振兴战略启动",summary:"2003年10月中央、国务院印发振兴意见，年底成立领导小组。",detail:{background:"1990年代中后期以来东北三省国有企业集中困难、社会保障支出压力大，2002年11月中共十六大提出支持东北地区等老工业基地加快调整和改造。",process:"2003年10月，中共中央、国务院印发《关于实施东北地区等老工业基地振兴战略的若干意见》，以结构调整、企业改组改制与社会保障试点为重点推进辽宁、吉林、黑龙江等老工业基地改造；2003年6月起辽宁在全省开展完善城镇社会保障体系试点，把国有企业下岗职工基本生活保障向失业保险并轨作为主要内容；同年年底国务院成立振兴东北地区等老工业基地领导小组。",impact:"2007年8月国务院批复《东北地区振兴规划》，规划范围包含辽宁、吉林、黑龙江三省和内蒙古自治区东部五个盟市；2016年、2023年中共中央、国务院先后就新一轮东北振兴出台意见，政策重点转向产业结构、营商环境与对外开放。",figures:["温家宝"],place:"辽宁、吉林、黑龙江三省",state:"中华人民共和国",sources:["中共中央、国务院2003年10月《关于实施东北地区等老工业基地振兴战略的若干意见》及新华社报道","国务院2007年关于东北地区振兴规划的批复"],"tags":["东北振兴","老工业基地","社会保障试点"]},related:["cn--2000--e01", "cn--1998--e02"]},
  {id:"cn--2003--i01",track:"cn",year:2003,yearApprox:false,dim:"institution",weight:3,title:"突发公共卫生事件应急条例公布施行",summary:"2003年5月9日国务院公布条例，确立1小时内上报等制度。",detail:{background:"非典疫情暴露出信息迟报、责任不清与预案缺失等问题，国务院决定以紧急行政法规方式建立突发公共卫生事件应急机制。",process:"2003年5月9日，国务院公布施行《突发公共卫生事件应急条例》；条例规定省级人民政府接到突发公共卫生事件报告后应当在1小时内向国务院卫生行政主管部门报告，医疗卫生机构与有关单位落实监测、预警、信息报告与应急处理要求，并明确隐瞒、缓报、谎报以及阻碍应急处理的法律责任。",impact:"据卫生部公布的信息，2004年1月1日起全国传染病疫情与突发公共卫生事件网络直报系统正式运行；2004年8月28日十届全国人大常委会第十一次会议修订《传染病防治法》，2007年8月30日通过的《突发事件应对法》自2007年11月1日起施行，与条例共同构成突发公共卫生事件应急制度框架。",figures:["温家宝","吴仪"],place:"北京",state:"中华人民共和国",sources:["《突发公共卫生事件应急条例》（2003年5月9日国务院公布施行）、新华社当日报道","卫生部2004年关于网络直报系统建成运行的通报"],"tags":["行政法规","应急机制","信息报告"]},related:["cn--2003--d01", "cn--2003--i02"]},
  {id:"cn--2003--i02",track:"cn",year:2003,yearApprox:false,dim:"institution",weight:3,title:"行政许可法通过并定于次年施行",summary:"2003年8月27日通过，2004年7月1日施行，规范审批权设定。",detail:{background:"行政审批事项过多、设定随意与许可收费等问题在1990年代末后持续被讨论，1999年起国务院部署行政审批制度改革。",process:"2003年8月27日，十届全国人大常委会第四次会议通过《中华人民共和国行政许可法》，自2004年7月1日起施行；法律限定可以设定行政许可的事项范围与设定权限，确立公开、公平、便民、信赖保护与统一受理窗口等实施规则，规定行政机关实施许可和对许可事项的监督检查原则上不得收取费用。",impact:"据国务院2004年贯彻实施行政许可法的工作部署口径，国务院部门与地方政府集中清理了一批行政许可规定、实施机关与收费项目；2013年起国务院分批取消和下放行政审批事项，并推行权力清单、责任清单与市场准入负面清单制度。",figures:["吴邦国"],place:"北京",state:"中华人民共和国",sources:["《中华人民共和国行政许可法》（2003年8月27日通过）、新华社2003年8月28日报道","国务院2004年关于贯彻实施行政许可法的通知"],"tags":["行政许可","审批制度改革","依法行政"]},related:["cn--1996--i01", "cn--1989--i01"]},
  {id:"cn--2003--s01",track:"cn",year:2003,yearApprox:false,dim:"science",weight:5,title:"神舟五号完成首次载人航天飞行",summary:"2003年10月15日发射，杨利伟在轨约21小时、绕地14圈后返回。",detail:{background:"1992年9月21日中央批准实施载人航天工程三步走方案；神舟一号至四号无人飞船于1999年11月至2002年12月完成四次飞行试验。",process:"2003年10月15日，长征二号F运载火箭在酒泉卫星发射中心将神舟五号载人飞船送入预定轨道，航天员杨利伟成为进入太空的第一位中国公民；飞船绕地球飞行14圈、在轨飞行约21小时，10月16日6时23分在内蒙古中部预定着陆场安全着陆。",impact:"据中国载人航天工程办公室公布，中国成为继苏联、美国之后第三个独立掌握载人航天技术的国家；此后2005年神舟六号实现多人多天飞行，2008年9月神舟七号完成首次空间出舱活动，2011年11月天宫一号与神舟八号完成首次交会对接，2021年4月天和核心舱发射后空间站进入在轨建造阶段。",figures:["杨利伟","王永志"],place:"酒泉卫星发射中心及内蒙古中部着陆场",state:"中华人民共和国",sources:["新华社2003年10月16日报道","中国载人航天工程办公室2003年10月16日发布的神舟五号飞行信息"],"tags":["载人航天","神舟五号","杨利伟"]},related:["cn--1992--s01", "cn--1999--s01"]},
  {id:"cn--2003--d01",track:"cn",year:2003,yearApprox:false,dim:"disaster",weight:4,title:"非典型肺炎疫情在全国暴发",summary:"2003年春夏多地疫情严重，据世卫统计大陆诊断病例5327例。",detail:{background:"2002年11月中旬起广东省出现非典型肺炎病例，2003年2月疫情在广东集中暴发并向多个省份扩散，病原体为一种新型冠状病毒。",process:"2003年3月12日世界卫生组织就非典发出全球警告；2003年4月中国把非典列入法定传染病并按甲类传染病管理，实行疫情每日公布与零报告制度；4月23日国务院成立全国防治非典型肺炎指挥部，吴仪任总指挥，同月底卫生部部长与北京市市长职务作出调整、吴仪兼任卫生部部长；6月下旬世界卫生组织解除对北京的旅行警告并把北京移出疫区名单，8月中旬北京最后一名临床诊断病例出院。",impact:"据世界卫生组织2003年8月公布的疫情数据，全球共报告非典临床诊断病例8096例、死亡774人，其中中国大陆报告5327例、死亡349人；疫情直接推动《突发公共卫生事件应急条例》出台、2004年全国网络直报系统建成，以及2007年6月15日生效的《国际卫生条例（2005）》修订。",figures:["吴仪","钟南山","张文康"],place:"广东、北京等地及全国",state:"中华人民共和国",sources:["世界卫生组织2003年8月公布的全球非典累计疫情数据","卫生部2003年非典型肺炎疫情每日通报及2003年8月疫情信息通报","新华社2003年4月至8月关于防治非典工作的系列报道"],"tags":["非典型肺炎","突发公共卫生事件","疫情防控"]},related:["cn--2003--i01", "cn--2003--i02"]},
  {id:"cn--2004--p01",track:"cn",year:2004,yearApprox:false,dim:"politics",weight:3,title:"十六届四中全会与军队最高领导职务交接",summary:"2004年9月全会通过执政能力建设决定，胡锦涛任中央军委主席。",detail:{background:"2002年十六大后中央领导集体处于新老交替阶段，军队最高领导职务的过渡安排受到关注。",process:"2004年9月16日至19日，中共十六届四中全会在北京举行，通过《中共中央关于加强党的执政能力建设的决定》，总结执政经验并提出科学执政、民主执政、依法执政等要求；全会同意江泽民辞去中共中央军事委员会主席职务，决定胡锦涛任中共中央军委主席。",impact:"2005年3月十届全国人大三次会议完成国家中央军事委员会主席的相应调整，十六大开始的中央领导层换届程序全部完成；2005年2月起全党分三批开展以实践三个代表重要思想为主要内容的保持共产党员先进性教育活动，至2006年6月基本结束。",figures:["胡锦涛","江泽民"],place:"北京",state:"中华人民共和国",sources:["《中国共产党第十六届中央委员会第四次全体会议公报》（2004年9月19日）、新华社报道","新华社2005年3月关于十届全国人大三次会议选举决定的报道"],"tags":["十六届四中全会","中央军委","执政能力建设"]},related:["cn--2002--p01", "cn--2004--i01"]},
  {id:"cn--2004--i01",track:"cn",year:2004,yearApprox:false,dim:"institution",weight:4,title:"2004年宪法修正案通过",summary:"增加人权保障、私有财产保护与社会保障制度等条款。",detail:{background:"2003年12月中共中央向全国人大常委会提出关于修改宪法部分内容的建议，2004年1月宪法修正案草案提请审议。",process:"2004年3月14日，十届全国人大二次会议通过宪法修正案，把三个代表重要思想同邓小平理论、马克思列宁主义、毛泽东思想一道写入国家指导思想，增加国家尊重和保障人权、公民的合法的私有财产不受侵犯、国家建立健全同经济发展水平相适应的社会保障制度等条款，并把乡镇人大每届任期由3年改为5年、将戒严改为紧急状态。",impact:"1982年现行宪法至此历经1988年、1993年、1999年、2004年四次修正，2018年3月11日第五次修正进一步调整国家机构与指导思想表述；私有财产保护与社会保障条款此后成为《物权法》（2007年）与《社会保险法》（2010年10月28日通过、2011年7月1日施行）的立法依据之一。",figures:["吴邦国"],place:"北京",state:"中华人民共和国",sources:["《中华人民共和国宪法修正案（2004年）》、新华社2004年3月15日报道","《中国共产党第十六届中央委员会第三次全体会议公报》关于修宪建议的说明"],"tags":["宪法修正","人权保障","私有财产"]},related:["cn--1982--i01", "cn--1999--i01"]},
  {id:"cn--2004--s01",track:"cn",year:2004,yearApprox:false,dim:"science",weight:3,title:"绕月探测工程正式批准立项",summary:"2004年1月国务院批准探月方案，确定绕落回三步走。",detail:{background:"1990年代以来中国科学院多位院士提出开展月球探测的建议，2000年《中国的航天》白皮书首次公布探月设想，2003年工程方案完成论证。",process:"2004年1月，国务院批准绕月探测工程实施方案，中国月球探测工程正式立项；工程按绕、落、回三步走实施，第一步发射绕月卫星获取月球全球影像与元素分布数据，第二步实现月面软着陆与巡视探测，第三步采集样品返回；据国防科工委公布，孙家栋担任工程总设计师，欧阳自远担任应用系统总设计师。",impact:"2007年10月嫦娥一号发射并获取全月球影像图，2009年3月1日按计划受控撞月；2013年12月嫦娥三号携玉兔号月球车实现月面软着陆；2019年1月3日嫦娥四号在月球背面冯·卡门撞击坑着陆；2020年11月至12月嫦娥五号实现月面采样返回，带回月壤样品1731克。",figures:["孙家栋","欧阳自远"],place:"北京及西昌卫星发射中心",state:"中华人民共和国",sources:["国务院2004年批准绕月探测工程的公开信息及新华社报道","国防科工委2004年关于绕月探测工程命名的新闻发布"],"tags":["探月工程","绕月探测","深空探测"]},related:["cn--2007--s01", "cn--1995--s01"]},
  {id:"cn--2004--e01",track:"cn",year:2004,yearApprox:false,dim:"economy",weight:3,title:"中央一号文件聚焦农民增加收入",summary:"提出多予少取放活，实行种粮直补并降低农业税税率。",detail:{background:"1999年至2003年全国粮食总产量连续下降，农民收入增长缓慢，2003年12月中央经济工作会议把解决三农问题作为全党工作的重中之重。",process:"2004年初，中共中央、国务院印发《关于促进农民增加收入若干政策的意见》（当年中央一号文件），确立多予、少取、放活方针，决定对种粮农民实行直接补贴、良种补贴与农机具购置补贴，降低农业税税率并在吉林、黑龙江两省开展全省免征农业税试点，同时放开粮食收购市场和收购价格。",impact:"据国家统计局公布，2004年全国粮食总产量结束此前数年的下降转为增产；2004年至2015年中央连续发布以三农为主题的年度一号文件，据国家统计局数据2013年全国粮食总产量首次超过6亿吨并在此后连续多年保持在6亿吨以上。",figures:["温家宝","回良玉"],place:"北京及全国农村地区",state:"中华人民共和国",sources:["《中共中央 国务院关于促进农民增加收入若干政策的意见》（2004年中央一号文件）","国家统计局《2004年国民经济和社会发展统计公报》"],"tags":["中央一号文件","三农","农业补贴"]},related:["cn--1978--e01", "cn--2006--e01"]},
  {id:"cn--2004--e02",track:"cn",year:2004,yearApprox:false,dim:"economy",weight:3,title:"第一次全国经济普查完成并修订经济总量",summary:"2004年开展首次经济普查，2005年12月公布主要数据。",detail:{background:"第三产业与个体私营经济长期存在漏统，2003年8月国务院决定建立国家经济普查制度，把第三产业普查、工业普查与基本单位普查合并为全国经济普查，每5年实施一次。",process:"2004年全国开展第一次经济普查，普查标准时点为2004年12月31日，对象为第二、第三产业法人单位、产业活动单位和个体经营户；据国家统计局2005年12月发布的第一次全国经济普查主要数据公报，2004年全国国内生产总值为159878亿元，比原初步核算数增加23393亿元、上调16.8%。",impact:"普查后国家建立了以经济普查为基础的年度数据修订与衔接机制，第三产业占比数据相应上调；据国家统计局公布，2008年、2013年、2018年、2023年先后开展第二至第五次全国经济普查，其中第五次全国经济普查标准时点为2023年12月31日、主要数据于2024年12月公布。",figures:["李德水"],place:"北京及全国",state:"中华人民共和国",sources:["《国务院关于开展第一次全国经济普查的通知》（2003年8月）","国家统计局《第一次全国经济普查主要数据公报》（2005年12月发布）"],"tags":["经济普查","统计制度","第三产业"]},related:[]},
  {id:"cn--2004--c01",track:"cn",year:2004,yearApprox:false,dim:"culture",weight:3,title:"刘翔雅典奥运会夺男子110米栏金牌",summary:"2004年雅典奥运会，刘翔以12秒91追平世界纪录夺冠。",detail:{background:"1984年中国首次全面参加洛杉矶奥运会后以奥运项目为重点推进竞技体育，男子短距离项目长期由欧美选手占据。",process:"2004年雅典奥运会男子110米栏决赛中，21岁的中国选手刘翔以12秒91获得金牌并追平科林·杰克逊保持的世界纪录，成为中国男子选手在奥运会短距离项目上的首枚金牌；中国体育代表团在该届奥运会获得32枚金牌、17枚银牌、14枚铜牌，金牌数仅次于美国代表团。",impact:"2006年7月刘翔以12秒88打破男子110米栏世界纪录；据中国田径协会公布，此后中国男子短距离与跳跃项目在国际大赛中成绩提升，2020年9月苏炳添在男子100米跑出9秒91。中国代表团在2008年北京奥运会金牌榜位居第一。",figures:["刘翔","孙海平"],place:"希腊雅典",state:"中华人民共和国",sources:["国际奥林匹克委员会2004年雅典奥运会官方成绩记录","新华社2004年8月关于雅典奥运会中国代表团的系列报道"],"tags":["奥运会","田径","竞技体育"]},related:["cn--1984--c01", "cn--2008--c01"]},
  {id:"cn--2005--i01",track:"cn",year:2005,yearApprox:false,dim:"institution",weight:4,title:"反分裂国家法通过施行",summary:"2005年3月14日十届全国人大三次会议通过，全文共10条。",detail:{background:"1995年1月江泽民提出发展两岸关系的八项主张，2000年前后台湾当局推动有关两国的定位论述，2004年3月19日台湾发生枪击事件后公投议题争议升温。",process:"2005年3月14日，十届全国人大三次会议表决通过《反分裂国家法》，自公布之日起施行，全文10条；法律确认台湾是中国的一部分、国家绝不允许台独分裂势力以任何名义任何方式把台湾从中国分裂出去，规定和平统一的基础与谈判程序，并在台独分裂事实、导致台湾分裂出去的重大事变或和平统一可能性完全丧失三种情形下授权采取非和平方式及其他必要措施。",impact:"据国务院台湾事务办公室公布，该法此后成为大陆对台政策表述中的法律基准；2005年4月至5月中国国民党主席连战、亲民党主席宋楚瑜先后访问大陆，2008年后海峡两岸关系协会与海峡交流基金会恢复制度化协商并于2015年11月实现两岸领导人新加坡会晤。",figures:["吴邦国"],place:"北京",state:"中华人民共和国",sources:["《反分裂国家法》（2005年3月14日第十届全国人民代表大会第三次会议通过）、新华社受权发布全文","国务院台湾事务办公室2005年3月新闻发布"],"tags":["反分裂国家法","对台政策","全国人大"]},related:["cn--1995--p01", "cn--2005--p01"]},
  {id:"cn--2005--p01",track:"cn",year:2005,yearApprox:false,dim:"politics",weight:3,title:"中国国民党主席连战率团访问大陆",summary:"2005年4月26日至5月3日的访问被称为和平之旅。",detail:{background:"1949年后两党高层长期无正式往来，2003年起两岸包机节日飞行与民间交流增多，2005年前后两岸政党接触渠道开启。",process:"2005年4月26日至5月3日，中国国民党主席连战率团访问南京、北京、西安、上海，4月29日与胡锦涛在北京会面；5月3日两党发布《两岸和平发展共同愿景》，提出坚持九二共识、反对台独，促进两岸务实协商、实现全面直接双向三通、恢复两岸谈判等共同目标；同年5月5日至13日亲民党主席宋楚瑜访问大陆并在西安公祭黄帝陵。",impact:"据新华社报道，这是1949年后中国国民党现任最高领导人首次访问大陆；2006年4月起国共两党以两岸经贸论坛（后改称两岸经贸文化论坛）为机制化交流平台，至2016年停止举办；2008年至2016年海协会与海基会举行多次领导人会谈并签署多项协议。",figures:["连战","宋楚瑜","胡锦涛"],place:"南京、北京、西安、上海",state:"中华人民共和国",sources:["新华社2005年4月26日至5月13日关于连战、宋楚瑜访问大陆的报道","国共两党《两岸和平发展共同愿景》（2005年5月3日发布）"],"tags":["国共交流","两岸关系","连战"]},related:["cn--1995--p01", "cn--2005--i01"]},
  {id:"cn--2005--e01",track:"cn",year:2005,yearApprox:false,dim:"economy",weight:3,title:"人民币汇率形成机制改革启动",summary:"2005年7月21日改为参考一篮子货币的有管理浮动汇率。",detail:{background:"1994年汇率并轨后人民币长期实行以市场供求为基础的、单一的、有管理的浮动汇率制度，2005年前实际盯住美元，贸易顺差与外汇储备在2004年后快速增长。",process:"2005年7月21日，中国人民银行发布公告，宣布实行以市场供求为基础、参考一篮子货币进行调节、有管理的浮动汇率制度，美元兑人民币交易价格由8.2765元调整为8.11元；同年5月银行间即期外汇市场浮动区间已作调整，2006年1月4日引入做市询价方式并把前一日收盘价作为次日中间价的重要参考，2007年5月21日每日浮动幅度由千分之三扩大至千分之五。",impact:"据中国人民银行公布，2010年6月19日继续推进汇率形成机制改革、增强人民币汇率弹性，2012年4月、2014年3月每日浮动幅度先后扩大至百分之一和百分之二；2015年8月11日人民银行宣布完善人民币兑美元汇率中间价报价，2016年12月中国外汇交易中心发布CFETS人民币汇率指数。",figures:["周小川"],place:"北京",state:"中华人民共和国",sources:["中国人民银行2005年7月21日《关于完善人民币汇率形成机制改革的公告》","中国人民银行历年《中国货币政策执行报告》"],"tags":["汇率改革","一篮子货币","人民币汇率"]},related:["cn--1994--e02", "cn--2001--e01"]},
  {id:"cn--2005--s01",track:"cn",year:2005,yearApprox:false,dim:"science",weight:3,title:"神舟六号实现多人多天载人飞行",summary:"2005年10月12日发射，费俊龙、聂海胜在轨115小时32分。",detail:{background:"神舟五号任务后工程进入第二步第一阶段，需要突破多人多天飞行、飞船载人与生命保障扩展等技术。",process:"2005年10月12日，长征二号F火箭在酒泉卫星发射中心发射神舟六号载人飞船，航天员费俊龙、聂海胜进入太空，开展多人多天飞行与空间科学实验，期间航天员进入轨道舱操作；飞船在轨飞行115小时32分、绕地77圈，10月17日凌晨在内蒙古四子王旗主着陆场安全着陆。",impact:"据中国载人航天工程办公室公布，2008年9月27日神舟七号航天员翟志刚完成中国首次空间出舱活动；2011年11月神舟八号与天宫一号实现首次交会对接，2012年6月神舟九号首次载人交会对接并首次有女航天员进入太空，2016年10月神舟十一号与天宫二号完成30天中期驻留。",figures:["费俊龙","聂海胜"],place:"酒泉卫星发射中心及内蒙古四子王旗着陆场",state:"中华人民共和国",sources:["新华社2005年10月17日报道","中国载人航天工程办公室2005年10月神舟六号任务飞行情况通报"],"tags":["神舟六号","载人航天","多人多天"]},related:["cn--2003--s01"]},
  {id:"cn--2005--m01",track:"cn",year:2005,yearApprox:false,dim:"military",weight:3,title:"中俄举行首次联合军事演习",summary:"2005年8月18日至25日进行和平使命-2005联合反恐演习。",detail:{background:"2001年上海合作组织成立后安全合作列为优先方向，2002年中俄签署关于军事合作协定，2004年两国确立举行联合反恐军事演习的安排。",process:"2005年8月18日至25日，中俄两国军队举行和平使命-2005联合反恐军事演习，实兵演练在山东半岛及附近海域进行；参演兵力通过铁路与空中输送跨境机动，演练联合反恐行动的组织指挥、封控与歼灭等科目，这是两国军队首次举行联合军事演习，也是解放军首次在外军参与下在本国境内组织联合演习。",impact:"据国防部公布，此后中俄联合演习机制化，2007年8月上海合作组织举行首次成员国联合反恐军事演习，2012年起中俄先后举行海上联合系列演习，2018年9月中国军队派员参加俄军东方-2018战略演习。",figures:["曹刚川"],place:"山东半岛及附近海域",state:"中华人民共和国",sources:["新华社2005年8月关于和平使命-2005联合军事演习的报道","国防部2005年8月例行记者会相关通报"],"tags":["中俄军演","上海合作组织","联合反恐"]},related:["cn--1996--p01", "cn--1996--m01"]},
  {id:"cn--2005--x01",track:"cn",year:2005,yearApprox:false,dim:"explore",weight:3,title:"珠峰岩面高程测定结果公布",summary:"2005年10月9日国务院批准发布珠穆朗玛峰高程8844.43米。",detail:{background:"中国曾于1966年至1968年、1975年测定珠峰高程，1975年公布的数据为雪面高程8848.13米；随着测绘技术与对岩面、雪面定义的变化，需要重新测量。",process:"2005年5月22日中国测绘突击队员登顶开展觇标架设与雪深测量等作业，结合全球定位系统、水准测量与重力测量数据推算；2005年10月9日国务院批准发布珠穆朗玛峰岩面高程为8844.43米，并公布测量误差与雪深数据。",impact:"这次测量首次完整给出珠峰岩面高程与雪面高程的区分，并综合运用卫星定位、精密水准与重力测量手段；2020年5月27日中国珠峰测量登山队再次登顶观测，12月8日中国与尼泊尔共同宣布珠穆朗玛峰最新高程8848.86米。",figures:["陈俊勇"],place:"西藏定日县珠峰地区",state:"中华人民共和国",sources:["国务院2005年10月9日关于珠穆朗玛峰高程的批准发布及新华社报道","国家测绘局2005年珠峰测量成果发布材料"],"tags":["珠峰高程","测绘","科学考察"]},related:["cn--1960--x01"]},
  {id:"cn--2006--e01",track:"cn",year:2006,yearApprox:false,dim:"economy",weight:5,title:"农业税条例废止实现全面取消农业税",summary:"2005年12月29日人大常委会决定废止，2006年1月1日起生效。",detail:{background:"2004年起吉林、黑龙江两省率先全省免征农业税，据新华社2005年12月报道，当年已有28个省（自治区、直辖市）全面免征农业税，继续征收失去实际条件。",process:"2005年12月29日，十届全国人大常委会第十九次会议通过《关于废止〈中华人民共和国农业税条例〉的决定》，自2006年1月1日起执行，1958年公布的农业税条例被废止，实施48年的农业税制度结束；同期明确取消牧业税、屠宰税以及面向农民征收的乡统筹、村提留等收费项目。",impact:"据财政部、农业部公布，取消农业税后国家对农业的支持保护转为以补贴与项目投入为主，2006年全面放开粮食收购市场；同年西部农村义务教育率先免除学杂费、2007年在全国推开，2009年10月起开展新型农村社会养老保险试点并于2012年7月实现制度全覆盖。",figures:["吴邦国","回良玉"],place:"北京及全国农村",state:"中华人民共和国",sources:["《中华人民共和国全国人民代表大会常务委员会关于废止〈中华人民共和国农业税条例〉的决定》（2005年12月29日）","新华社2005年12月30日报道、财政部2006年关于农村税费改革的通报"],"tags":["农业税","农村税费改革","三农"]},related:["cn--1978--e01", "cn--2004--e01"]},
  {id:"cn--2006--s01",track:"cn",year:2006,yearApprox:false,dim:"science",weight:4,title:"青藏铁路全线建成通车试运营",summary:"2006年7月1日格尔木至拉萨段投入试运营，西藏结束不通铁路。",detail:{background:"格尔木至拉萨段2001年6月29日开工，总投资约330亿元，工程需克服高寒缺氧、多年冻土与生态脆弱三大难题，2005年10月12日全线铺轨接通。",process:"2006年7月1日，青藏铁路格尔木至拉萨段与既有西宁至格尔木段全线贯通试运营，开行进出藏旅客列车与货物列车；格拉段全长1142公里，其中连续多年冻土区约550公里，海拔4000米以上地段约960公里，沿线设置野生动物通道并采取以桥代路、热棒与通风管路基等冻土保护措施。",impact:"据铁道部及后续国铁集团公布的信息，通车后铁路成为进出藏物资运输的主要方式，运输成本与票价低于公路与航空；2014年8月拉萨至日喀则铁路开通，2021年6月25日拉萨至林芝段开通，西藏铁路网延伸至藏东南地区。",figures:["孙永福"],place:"青海格尔木至西藏拉萨",state:"中华人民共和国",sources:["国务院2006年关于青藏铁路通车的公开信息及新华社2006年7月2日报道","铁道部2006年青藏铁路建设工作总结与新闻发布会记录"],"tags":["青藏铁路","高原冻土","西藏交通"]},related:["cn--2001--e02", "cn--1994--p01"]},
  {id:"cn--2006--c01",track:"cn",year:2006,yearApprox:false,dim:"culture",weight:3,title:"国务院公布第一批国家级非遗名录",summary:"2006年5月20日公布名录518项，涉及10个门类。",detail:{background:"2003年文化部与中国民间文艺家协会等启动非遗普查，2004年12月中国加入联合国教科文组织《保护非物质文化遗产公约》，需建立国家层面的名录制度。",process:"2006年5月20日，国务院发布《关于公布第一批国家级非物质文化遗产名录的通知》，批准文化部确定的第一批国家级非物质文化遗产名录共518项，分民间文学、传统音乐、传统舞蹈、传统戏剧、曲艺、传统体育游艺与杂技、传统美术、传统技艺、传统医药、民俗10类，昆曲、古琴艺术、新疆维吾尔木卡姆艺术、蒙古族长调等列入。",impact:"据文化部公布，2005年12月《国务院关于加强文化遗产保护的通知》确定每年6月第二个星期六为文化遗产日，2006年6月10日为我国首个文化遗产日；2011年2月25日全国人大常委会通过《非物质文化遗产法》并于当年6月1日施行，确立国家、省、市、县四级名录与代表性传承人制度，此后国家级名录又于2008年、2011年、2014年、2021年分批扩展。",figures:["孙家正"],place:"北京",state:"中华人民共和国",sources:["《国务院关于公布第一批国家级非物质文化遗产名录的通知》（2006年5月20日）","文化部2006年关于首个文化遗产日的通报"],"tags":["非物质文化遗产","名录制度","文化遗产日"]},related:["cn--2001--c01"]},
  {id:"cn--2006--i01",track:"cn",year:2006,yearApprox:false,dim:"institution",weight:3,title:"各级人大常委会监督法通过",summary:"2006年8月27日通过，2007年1月1日起施行。",detail:{background:"1982年宪法与地方组织法规定的人大监督职权缺乏可操作程序，备案审查、预算监督与质询在实践中使用较少。",process:"2006年8月27日，十届全国人大常委会第二十三次会议通过《中华人民共和国各级人民代表大会常务委员会监督法》，自2007年1月1日起施行；法律规定县级以上人大常委会通过听取和审议专项工作报告、审查和批准决算与预算执行情况报告、执法检查、规范性文件备案审查、询问和质询、特定问题调查、撤职案审议等方式行使监督职权，并要求监督工作情况向本级人民代表大会报告。",impact:"法律实施后，听取审议专项工作报告与执法检查成为全国人大常委会年度监督工作的常规方式；据全国人大常委会法制工作委员会公布，备案审查工作在2017年后建立年度通报制度，与2014年8月31日修改的《预算法》共同构成人大预算与立法监督的程序依据。",figures:["吴邦国"],place:"北京",state:"中华人民共和国",sources:["《中华人民共和国各级人民代表大会常务委员会监督法》（2006年8月27日通过）、新华社2006年8月28日报道","全国人大常委会法制工作委员会历年备案审查工作情况报告"],"tags":["人大监督","备案审查","预算监督"]},related:["cn--1982--i01"]},
  {id:"cn--2006--p01",track:"cn",year:2006,yearApprox:false,dim:"politics",weight:3,title:"十届全国人大四次会议批准十一五规划纲要",summary:"2006年3月14日批准，首次改计划为规划并设约束性指标。",detail:{background:"2005年10月中共十六届五中全会通过关于制定国民经济和社会发展第十一个五年规划的建议，把单位国内生产总值能耗下降列为重要约束目标。",process:"2006年3月14日，十届全国人大四次会议批准《国民经济和社会发展第十一个五年规划纲要》；纲要把延续多年的五年计划改称五年规划，设定单位国内生产总值能源消耗比2005年降低20%左右、主要污染物排放总量减少10%等约束性指标，并把建设社会主义新农村、增强自主创新能力列为重点任务。",impact:"据国家统计局与国家发改委2011年公布，十一五期间单位国内生产总值能耗累计降低接近20%的约束性要求，主要污染物减排目标完成；此后十二五、十三五、十四五规划纲要延续设置能耗、碳排放与生态环境类约束性指标，2020年9月中国宣布力争2030年前实现碳达峰、2060年前实现碳中和。",figures:["温家宝"],place:"北京",state:"中华人民共和国",sources:["《中华人民共和国国民经济和社会发展第十一个五年规划纲要》（2006年3月14日批准）","国家统计局《2010年国民经济和社会发展统计公报》、国务院关于节能减排工作情况的报告"],"tags":["五年规划","约束性指标","节能减排"]},related:["cn--2003--p01", "cn--2006--p02"]},
  {id:"cn--2006--p02",track:"cn",year:2006,yearApprox:false,dim:"politics",weight:3,title:"十六届六中全会作出构建和谐社会决定",summary:"2006年10月通过决定，提出到2020年构建和谐社会的目标。",detail:{background:"2003年至2005年间中央先后提出科学发展观与构建社会主义和谐社会命题，2005年2月省部级主要领导干部专题研讨会对和谐社会基本特征作出系统阐述。",process:"2006年10月8日至11日，中共十六届六中全会在北京举行，通过《中共中央关于构建社会主义和谐社会若干重大问题的决定》；决定提出到2020年构建社会主义和谐社会的目标和任务，包括城乡区域发展差距扩大趋势基本遏制、基本公共服务体系逐步形成、覆盖城乡居民的社会保障体系基本建立等，强调经济建设、政治建设、文化建设与社会建设协调发展。",impact:"2007年中共十七大把和谐与富强、民主、文明并列写入现代化建设目标并相应修改党章；据国务院公布，2009年10月启动新型农村社会养老保险试点、2011年启动城镇居民社会养老保险试点，2012年7月两项制度实现全覆盖；2018年深化党和国家机构改革中组建国家医疗保障局，整合职工与城乡居民医保制度。",figures:["胡锦涛"],place:"北京",state:"中华人民共和国",sources:["《中共中央关于构建社会主义和谐社会若干重大问题的决定》（2006年10月11日中国共产党第十六届中央委员会第六次全体会议通过）","新华社2006年10月12日报道"],"tags":["和谐社会","社会建设","社会保障"]},related:["cn--2002--p01", "cn--2007--p01"]},
  {id:"cn--2007--p01",track:"cn",year:2007,yearApprox:false,dim:"politics",weight:4,title:"中共十七大把科学发展观写入党章",summary:"2007年10月15日至21日召开，提出全面建设小康新要求。",detail:{background:"2003年十六届三中全会提出科学发展观，2004年至2006年在经济过热与资源环境约束加重的背景下逐步形成理论表述。",process:"2007年10月15日至21日，中国共产党第十七次全国代表大会在北京举行，胡锦涛作《高举中国特色社会主义伟大旗帜，为夺取全面建设小康社会新胜利而奋斗》的报告；大会通过关于党章修正案的决议，把科学发展观、中国特色社会主义道路与中国特色社会主义理论体系写入党章，并把和谐与富强、民主、文明并列作为现代化建设目标。",impact:"大会提出实现人均国内生产总值到2020年比2000年翻两番的目标；2007年爆发国际金融危机后宏观调控方向转向保增长、扩内需、调结构，2010年10月十七届五中全会把加快转变经济发展方式写入十二五规划建议，2012年11月中共十八大把科学发展观同马克思列宁主义一道确立为党的指导思想。",figures:["胡锦涛"],place:"北京（人民大会堂）",state:"中华人民共和国",sources:["《中国共产党第十七次全国代表大会文件汇编》（人民出版社2007年）","新华社2007年10月22日报道"],"tags":["中共十七大","科学发展观","党章修改"]},related:["cn--2002--p01", "cn--2006--p02"]},
  {id:"cn--2007--i01",track:"cn",year:2007,yearApprox:false,dim:"institution",weight:4,title:"物权法通过并自当年10月施行",summary:"2007年3月16日十届全国人大五次会议通过，确立平等保护原则。",detail:{background:"1986年民法通则与1999年3月15日通过的合同法等已确立财产关系基本规则，但所有权与担保物权缺乏统一法律，2005年7月全国人大常委会办公厅曾将物权法草案全文向社会公开征求意见。",process:"2007年3月16日，十届全国人大五次会议表决通过《中华人民共和国物权法》，自2007年10月1日起施行；法律规定国家、集体、私人的物权受法律平等保护，明确征收征用的条件与补偿原则、住宅建设用地使用权期间届满自动续期、业主的建筑物区分所有权、预告登记与善意取得以及担保物权登记规则。",impact:"据全国人大宪法和法律委员会公布，物权法实施后不动产统一登记制度的建立被持续推进，2014年3月《不动产登记暂行条例》公布并于2015年3月施行；2020年5月28日十三届全国人大三次会议通过《中华人民共和国民法典》，自2021年1月1日起施行，物权法与合同法、担保法、婚姻法、继承法、收养法、侵权责任法同时废止。",figures:["王兆国"],place:"北京",state:"中华人民共和国",sources:["《中华人民共和国物权法》（2007年3月16日通过）、新华社2007年3月17日报道","全国人大常委会法制工作委员会关于物权法草案的说明（2007年3月）"],"tags":["物权法","财产保护","不动产统一登记"]},related:["cn--1986--i02", "cn--2020--i01"]},
  {id:"cn--2007--i02",track:"cn",year:2007,yearApprox:false,dim:"institution",weight:3,title:"劳动合同法与就业促进法通过",summary:"2007年6月29日与8月30日分别通过，同于2008年1月1日施行。",detail:{background:"1994年劳动法确立的用工规则在国有企业改制与农民工进城后暴露出书面合同签订率低、劳务派遣滥用等问题，2005年至2006年拖欠工资与工伤争议案件增多。",process:"2007年6月29日，十届全国人大常委会第二十八次会议通过《中华人民共和国劳动合同法》，自2008年1月1日起施行，规定书面劳动合同的订立与无固定期限合同适用情形、试用期上限、经济补偿与竞业限制，并把劳务派遣、非全日制用工与集体合同纳入统一规则；2007年8月30日全国人大常委会通过《就业促进法》，同日起施行，确立积极就业政策、公平就业、免费公共就业服务与职业培训补贴制度。",impact:"据人力资源和社会保障部历年统计公报，法律实施后用工书面化与社会保险参保覆盖面扩大，劳动争议仲裁受理案件数量在2008年明显增加；2007年12月29日通过的《劳动争议调解仲裁法》自2008年5月1日施行，2012年12月28日全国人大常委会修改劳动合同法并规范劳务派遣用工。",figures:["吴邦国"],place:"北京",state:"中华人民共和国",sources:["《中华人民共和国劳动合同法》（2007年6月29日通过）、《中华人民共和国就业促进法》（2007年8月30日通过）","人力资源和社会保障部历年《人力资源和社会保障事业发展统计公报》"],"tags":["劳动合同","就业促进","劳动者权益"]},related:["cn--1994--i01"]},
  {id:"cn--2007--e01",track:"cn",year:2007,yearApprox:false,dim:"economy",weight:3,title:"企业所得税法实现两法合并",summary:"2007年3月16日通过，内资与外资企业统一按25%税率纳税。",detail:{background:"1994年税制改革后内资企业适用《企业所得税暂行条例》，外商投资企业和外国企业适用单独的所得税法律并享受区域性与两免三减半优惠，税负差异长期存在。",process:"2007年3月16日，十届全国人大五次会议通过《中华人民共和国企业所得税法》，自2008年1月1日起施行，将内资与外资企业所得税制度合并，统一基本税率为25%，对国家重点扶持的高新技术企业减按15%、对小型微利企业减按20%征税，并统一税前扣除、关联交易与税收优惠规则；《外商投资企业和外国企业所得税法》与《企业所得税暂行条例》同时废止。",impact:"据财政部、国家税务总局公布，法律实施后对外资的税收优惠由区域导向转为产业导向，高新技术企业与研发费用加计扣除成为主要优惠工具；2018年起对小微企业实施阶段性所得减计与税率优惠，2021年财政部、税务总局进一步明确加计扣除比例提高至100%的适用范围。",figures:["吴邦国"],place:"北京",state:"中华人民共和国",sources:["《中华人民共和国企业所得税法》（2007年3月16日通过）、新华社2007年3月17日报道","财政部、国家税务总局历年关于企业所得税优惠政策的公告"],"tags":["企业所得税","税制改革","税收优惠"]},related:["cn--1994--e01", "cn--1980--i03"]},
  {id:"cn--2007--s01",track:"cn",year:2007,yearApprox:false,dim:"science",weight:4,title:"嫦娥一号发射实现首次绕月探测",summary:"2007年10月24日发射，11月5日进入环月轨道并传回月面影像。",detail:{background:"2004年绕月探测工程立项，选用长征三号甲运载火箭与东方红三号卫星平台，在西昌卫星发射中心发射。",process:"2007年10月24日，嫦娥一号月球探测卫星由长征三号甲火箭在西昌发射，经多次近月制动后于11月5日进入周期127分钟的环月工作轨道；卫星通过CCD立体相机与干涉光谱仪等载荷获取全月球影像图、月表化学元素与矿物分布、月壤厚度与地月空间环境数据，11月26日国家航天局公布首幅月面影像图；2009年3月1日嫦娥一号按计划受控撞向月面。",impact:"据国家航天局公布，嫦娥一号获取了覆盖全月球的影像图以及月壤厚度、元素分布等地月探测数据，中国成为继苏联、美国、日本与欧洲空间局之后发射月球探测器的国家或机构之一；2010年10月嫦娥二号发射并于2012年12月飞越小行星图塔蒂斯，2013年12月嫦娥三号、2019年1月嫦娥四号与2020年12月嫦娥五号相继完成月面软着陆、月背巡视与采样返回。",figures:["叶培建","孙家栋"],place:"西昌卫星发射中心及北京",state:"中华人民共和国",sources:["国家航天局2007年11月26日关于首幅月面影像图的发布及新华社报道","国防科工委2007年10月关于嫦娥一号发射的新闻发布材料"],"tags":["嫦娥一号","绕月探测","月球影像"]},related:["cn--2004--s01"]},
{id:"cn--2008--p01",track:"cn",year:2008,yearApprox:false,dim:"politics",weight:3,title:"十一届全国人大一次会议完成换届",summary:"2008年3月5日至18日召开，选举国家主席并决定国务院总理人选。",detail:{background:"2003年十届全国人大一次会议完成第一次跨届换届。按当时宪法关于国家主席、国务院总理连续任职不得超过两届的规定，2008年3月十一届全国人大一次会议选举和决定新一届国家机构领导人员；本届代表由2007年12月至2008年1月选出。",process:"会议3月5日至18日在北京举行。3月15日选举胡锦涛为中华人民共和国主席；3月16日选举吴邦国为全国人大常委会委员长，并根据国家主席提名决定温家宝为国务院总理。会议3月15日表决通过国务院机构改革方案。同期举行的全国政协十一届一次会议3月3日开幕，3月13日贾庆林当选主席。",impact:"机构改革方案推进“大部制”，新设工业和信息化部、交通运输部、人力资源和社会保障部、环境保护部、住房和城乡建设部，国务院组成部门调整为27个；环境保护部2018年改组为生态环境部。此次换届后，2013年、2018年、2023年全国人大一次会议均按相同程序产生新一届国家机构领导人员。",figures:["胡锦涛","温家宝","吴邦国","贾庆林"],place:"北京",state:"中华人民共和国",sources:["新华社2008年3月15日至18日关于十一届全国人大一次会议选举和决定结果的报道","十一届全国人大一次会议2008年3月15日批准的国务院机构改革方案及新华社受权发布的说明"],tags:["换届","全国人大","大部制改革"]},related:["cn--2003--p01", "cn--1998--i02"]},
{id:"cn--2008--c01",track:"cn",year:2008,yearApprox:false,dim:"culture",weight:4,title:"第29届夏季奥运会在北京举行",summary:"8月8日开幕、8月24日闭幕，中国代表团以51枚金牌列金牌榜第一。",detail:{background:"北京2001年7月13日在国际奥委会第112次全会（莫斯科）投票中获得第29届夏季奥林匹克运动会举办权。此后用于场馆与城市基础设施建设，国家体育场、国家游泳中心等新场馆建成。",process:"运动会8月8日晚在国家体育场（“鸟巢”）开幕，开幕式总导演为张艺谋，李宁以空中点火方式点燃主火炬。本届设28个大项、302个小项，204个国家和地区奥委会参赛。中国代表团获51枚金牌、21枚银牌、28枚铜牌共100枚奖牌，金牌数居第一位，美国以110枚奖牌居总数第一；菲尔普斯单届获8枚金牌，博尔特以9秒69创男子100米世界纪录。残奥会9月6日至17日在北京举行。",impact:"据北京奥组委发布的赛后报告，主要竞赛场馆赛后转为面向公众开放的体育与文化活动场所。2015年7月31日国际奥委会第128次全会投票确定北京举办2022年第24届冬季奥运会，北京成为既举办夏奥会又举办冬奥会的城市；2022年2月4日至20日冬奥会举行，中国代表团获9枚金牌。",figures:["张艺谋","李宁"],place:"北京，部分赛事在天津、上海、沈阳、青岛及香港举行",state:"中华人民共和国",sources:["国际奥委会2001年7月13日第112次全会投票结果及新华社报道","北京奥组委2008年8月至9月赛事成绩公告及新华社报道","国际奥委会2015年7月31日第128次全会关于2022年冬奥会举办地的投票结果"],tags:["北京奥运会","国家体育场","金牌榜"]},related:["cn--1984--c01", "cn--2004--c01", "cn--1990--p01"]},
{id:"cn--2008--d01",track:"cn",year:2008,yearApprox:false,dim:"disaster",weight:5,title:"四川汶川发生8.0级特大地震",summary:"2008年5月12日14时28分发生，随后展开全国范围抗震救灾与重建。",detail:{background:"震中位于四川省阿坝藏族羌族自治州汶川县映秀镇，地处龙门山断裂带。据中国地震台网测定，发震时刻为5月12日14时28分，震级8.0级，震源深度约14公里；据中国地震局发布的烈度图，极震区烈度达11度，波及四川、甘肃、陕西等省份。",process:"地震发生当天中共中央、国务院、中央军委作出部署，成立国务院抗震救灾总指挥部，温家宝任总指挥并赶赴灾区。军队、武警部队和民兵预备役人员投入救援，2008年5月14日15名空降兵在无气象资料、无地面指挥、无通讯保障条件下于4999米高度伞降四川茂县，打开首批救灾通道。据国务院抗震救灾总指挥部2008年通报，地震造成69227人遇难、374643人受伤、17923人失踪。",impact:"2008年6月国务院印发对口支援方案，实行“一省对一县”，由受灾省份以外省份对口支援重灾县（市、区）；2008年9月国务院发布《汶川地震灾后恢复重建总体规划》，提出力争用两年时间完成主要重建任务、五年时间完成规划目标。2009年3月国务院批复，自2009年起每年5月12日为全国“防灾减灾日”；2008年12月27日全国人大常委会修订通过《防震减灾法》，自2009年5月1日施行。据国务院新闻办公室2011年发布的重建情况，规划确定的主要重建任务基本完成。",figures:["温家宝"],place:"四川省汶川县映秀镇及周边受灾地区",state:"中华人民共和国",sources:["国务院抗震救灾总指挥部2008年历次震情灾情通报","中国地震台网中心速报与中国地震局汶川地震烈度图","国务院2008年9月发布的《汶川地震灾后恢复重建总体规划》","国务院2009年关于同意设立防灾减灾日的批复"],tags:["汶川地震","抗震救灾","灾后恢复重建"]},related:["cn--1976--d01", "cn--1991--d01"]},
{id:"cn--2008--e01",track:"cn",year:2008,yearApprox:false,dim:"economy",weight:4,title:"应对国际金融危机推出4万亿元投资",summary:"2008年9月起连续降息降准，扩大内需投资规模到2010年约4万亿元。",detail:{background:"2007年美国次级住房抵押贷款违约扩散，2008年9月15日雷曼兄弟公司申请破产保护后国际金融危机加剧，外部需求急剧收缩。据海关总署统计，2009年中国货物出口额比上年下降16.0%，沿海出口导向型企业订单与就业压力上升。",process:"2008年9月15日中国人民银行宣布下调部分银行存款准备金率1个百分点，9月16日起下调存贷款基准利率，据新华社报道这是央行十年来首次下调存款准备金率；至12月23日累计五次降息，一年期贷款基准利率由7.47%降至5.31%。2008年11月9日国务院常务会议提出改进宏观调控的十项措施，其后明确的扩大内需投资规划到2010年底约4万亿元，据国家发展和改革委员会公布，其中中央政府投资约1.18万亿元。同年12月起数次提高部分商品出口退税率并取消和降低部分行政事业性收费。",impact:"据中国人民银行统计，2009年金融机构新增人民币贷款9.59万亿元。据国家统计局年度核算，2009年经济增速回升至9%以上，2010年达到10%以上。投资与信贷快速扩张同时带来部分行业产能过剩、地方政府融资平台债务规模扩大和房价上涨，2010年4月17日国务院常务会议出台房地产调控“国十条”，央行自2010年11月起再次上调存款准备金率和存贷款基准利率。",figures:["周小川","温家宝"],place:"北京",state:"中华人民共和国",sources:["中国人民银行2008年9月至12月货币政策调整公告及2010年1月发布的2009年金融统计数据报告","国务院2008年11月9日常务会议关于改进宏观调控十项措施及新华社报道","国家统计局2009年、2010年国民经济和社会发展统计公报","海关总署2010年1月发布的2009年进出口统计数据"],tags:["国际金融危机","扩大内需","4万亿元投资"]},related:["cn--1998--e03", "cn--1997--e01", "cn--2009--e01"]},
{id:"cn--2008--i01",track:"cn",year:2008,yearApprox:false,dim:"institution",weight:3,title:"反垄断法自2008年8月1日起施行",summary:"2007年8月30日通过，确立垄断协议与滥用市场支配地位禁止规则。",detail:{background:"该法起草工作自1994年前后启动，因涉及部门执法职责划分与体制争议多次调整，前后历时约十三年；2006年6月十届全国人大常委会第二十二次会议初次审议草案，2007年8月30日第二十九次会议表决通过。",process:"法律禁止垄断协议、滥用市场支配地位以及具有或者可能具有排除、限制竞争效果的经营者集中，并禁止行政机关和法律、法规授权的具有管理公共事务职能的组织滥用行政权力排除、限制竞争。2008年8月1日施行，同年设立国务院反垄断委员会，执法由商务部负责经营者集中审查、国家发展改革委负责价格垄断案件、工商总局负责非价格垄断案件。",impact:"据有关部门公布，执法机构此后查处了一批横向价格协议、滥用市场支配地位和未依法申报的经营者集中案件，2015年2月国家发展改革委对高通公司作出60.88亿元罚款。2018年机构改革后反垄断执法统一由国家市场监督管理总局承担，2021年9月国家反垄断局挂牌；2021年4月市场监管总局对阿里巴巴集团作出182.28亿元罚款。2022年6月24日全国人大常委会通过关于修改反垄断法的决定，加大处罚力度。",figures:["吴邦国"],place:"北京",state:"中华人民共和国",sources:["十届全国人大常委会2007年8月30日通过《中华人民共和国反垄断法》及新华社受权发布","国家发展改革委2015年2月对高通公司行政处罚公告","国家市场监督管理总局2021年4月对阿里巴巴集团行政处罚公告","全国人大常委会2022年6月24日关于修改反垄断法的决定"],tags:["反垄断法","经营者集中","市场竞争"]},related:["cn--2007--i01", "cn--1992--p02"]},
{id:"cn--2008--s01",track:"cn",year:2008,yearApprox:false,dim:"science",weight:3,title:"神舟七号航天员完成首次空间出舱活动",summary:"2008年9月25日发射，27日翟志刚出舱行走并释放伴飞小卫星。",detail:{background:"空间出舱活动是中国载人航天工程“三步走”第二步前期需要突破的关键技术之一。执行任务的“飞天”舱外航天服由国内自主研制，2008年通过鉴定。",process:"2008年9月25日21时10分，神舟七号由长征二号F运载火箭在酒泉卫星发射中心发射，航天员翟志刚、刘伯明、景海鹏进入轨道舱。9月27日16时41分翟志刚打开轨道舱舱门出舱，在刘伯明协助下完成舱外作业，17时许返回轨道舱，舱外活动历时约20分钟；随后释放伴随小卫星开展近距离成像试验。9月28日17时37分返回舱在内蒙古四子王旗着陆场着陆。",impact:"据中国载人航天工程办公室公布，中国由此成为继俄罗斯、美国之后第三个独立掌握空间出舱活动技术的国家。该次任务使用的舱外航天服与伴飞卫星技术为2011年11月天宫一号与神舟八号交会对接及后续空间站建造阶段出舱活动奠定基础，2021年7月4日神舟十二号航天员在中国空间站完成空间站阶段首次出舱活动。",figures:["翟志刚","刘伯明","景海鹏"],place:"酒泉卫星发射中心、内蒙古四子王旗着陆场",state:"中华人民共和国",sources:["中国载人航天工程办公室2008年9月任务公告及新华社关于出舱活动的报道","中国载人航天工程办公室2021年7月关于神舟十二号航天员出舱活动的通报"],tags:["神舟七号","空间出舱","载人航天"]},related:["cn--2005--s01", "cn--1992--s01", "cn--2011--s01"]},
{id:"cn--2008--s02",track:"cn",year:2008,yearApprox:false,dim:"science",weight:3,title:"京津城际高速铁路开通运营",summary:"2008年8月1日开通，全长约116公里，最高运营时速350公里。",detail:{background:"2004年起铁道部组织引进国外时速200公里级别动车组技术并开展联合设计，为高速列车国产化与更高速度线路运营准备条件；京津之间原有铁路客运能力紧张，两地往来长期依赖公路与普速列车。",process:"2008年8月1日京津城际铁路开通运营，连接北京南站与天津站，全长约116公里，设计并运营时速350公里，使用“和谐号”动车组，最快30分钟左右到达，按公交化方式高密度开行。该线是中国第一条设计时速350公里的高速铁路。",impact:"据中国国家铁路集团有限公司和原铁道部公布，此后武广高铁于2009年12月26日开通、京沪高铁于2011年6月30日开通运营，高速铁路逐步成为中长途客运主力；截至2023年底，据国铁集团公布，全国铁路营业里程15.9万公里，其中高速铁路约4.5万公里。2011年7月甬温线事故发生后，包括京津城际在内的高速线路一度降低运行时速。",figures:["刘志军"],place:"北京市、天津市",state:"中华人民共和国",sources:["铁道部2008年7月关于京津城际铁路开通运营的新闻发布会材料","中国国家铁路集团有限公司2024年初公布的2023年铁路运输统计数据"],tags:["京津城际","高速铁路","动车组"]},related:["cn--1952--s01", "cn--1970--s02", "cn--2011--d01"]},
{id:"cn--2009--p01",track:"cn",year:2009,yearApprox:false,dim:"politics",weight:3,title:"首都举行庆祝新中国成立60周年阅兵",summary:"2009年10月1日在北京举行阅兵与群众游行，展示多型国产装备。",detail:{background:"此前一次全国性国庆阅兵为1999年国庆五十周年阅兵。2009年是中华人民共和国成立60周年，中央决定在北京举行庆祝大会、阅兵式和群众游行。",process:"10月1日，胡锦涛在天安门城楼发表讲话后检阅受阅部队。阅兵方队由中国人民解放军、武警部队和民兵预备役人员组成，涵盖陆军、海军、空军和第二炮兵等装备方队与空中梯队，受阅装备多为国产现役主战装备，包括新型主战坦克、自行火炮、防空导弹以及预警机、歼击机等型号。此后举行70万人参与的群众游行，当晚有联欢活动。",impact:"据新华社报道，这是改革开放后第11次国庆阅兵。此次阅兵的方队编成与装备公开方式延续到2015年9月3日纪念中国人民抗日战争暨世界反法西斯战争胜利70周年阅兵和2019年国庆70周年阅兵；2015年阅兵中宣布裁减军队员额30万。",figures:["胡锦涛"],place:"北京天安门",state:"中华人民共和国",sources:["新华社2009年10月1日关于庆祝中华人民共和国成立60周年大会、阅兵式和群众游行的报道","新华社2015年9月3日关于纪念抗战胜利70周年阅兵式及裁军宣布的报道"],tags:["国庆60周年","阅兵","群众游行"]},related:["cn--1999--m01", "cn--1984--m01"]},
{id:"cn--2009--p02",track:"cn",year:2009,yearApprox:false,dim:"politics",weight:3,title:"乌鲁木齐发生7·5严重暴力犯罪事件",summary:"2009年7月5日发生，官方通报197人死亡、1700余人受伤。",detail:{background:"2009年6月25日广东韶关一玩具厂发生涉及少数民族员工的事件，相关信息经网络与手机传播后引发关注。7月5日晚乌鲁木齐市中心城区出现大规模打砸抢烧行为。",process:"事件发生在2009年7月5日晚，涉及对过往车辆、商铺和行人的暴力攻击。新疆维吾尔自治区党委、政府和武警部队组织处置并恢复秩序。据新疆维吾尔自治区政府2009年7月披露的统计，事件造成197人死亡、1700余人受伤，大量车辆、房屋被毁。据官方通报，事件被定性为境内外策划组织的严重暴力犯罪事件，公安机关依法逮捕了一批涉事人员。",impact:"2010年5月17日至18日第一次中央新疆工作座谈会召开，部署推进新疆经济社会发展并组织对口支援新疆，据会后部署由19个省市分别对口支援新疆地州市和县市区；2014年5月、2020年9月分别召开第二次、第三次座谈会。制度建设方面，《中华人民共和国反恐怖主义法》2015年12月27日通过、2016年1月1日施行，新疆维吾尔自治区人大常委会2017年4月通过《新疆维吾尔自治区去极端化条例》。",figures:["努尔·白克力"],place:"新疆维吾尔自治区乌鲁木齐市",state:"中华人民共和国",sources:["新华社2009年7月关于乌鲁木齐打砸抢烧严重暴力犯罪事件的报道","新疆维吾尔自治区政府2009年7月关于“7·5”事件情况的新闻发布会通报","新华社2010年5月关于第一次中央新疆工作座谈会的报道"],tags:["乌鲁木齐","社会稳定","对口援疆"]},related:[]},
{id:"cn--2009--i01",track:"cn",year:2009,yearApprox:false,dim:"institution",weight:4,title:"中共中央国务院发布深化医药卫生体制改革意见",summary:"2009年3月17日发布，明确五项重点，前三年各级政府投入8500亿元。",detail:{background:"2006年9月国务院成立深化医药卫生体制改革领导小组，起草工作由国家发展改革委和卫生部牵头；2008年10月改革方案草案向社会公开征求意见，据主办方统计收到数万条建议后作出修改。",process:"2009年3月17日《中共中央 国务院关于深化医药卫生体制改革的意见》由新华社受权发布，同期公布《医药卫生体制改革近期重点实施方案（2009—2011年）》。意见提出坚持公共医疗卫生的公益性质，确定加快推进基本医疗保障制度、建立国家基本药物制度、健全基层医疗卫生服务体系、促进基本公共卫生服务逐步均等化、开展公立医院综合改革试点五项重点；实施方案测算2009—2011年重点改革需各级政府投入8500亿元，其中中央政府3318亿元。2009年8月启动国家基本药物制度，基层医疗卫生机构配备使用基本药物并实行零差率销售。",impact:"据人力资源和社会保障部、卫生部2011年公布，职工基本医疗保险、城镇居民基本医疗保险和新农合三项制度参保人数合计超过13亿人。此后2016年1月国务院印发关于整合城乡居民基本医疗保险制度的意见，2018年3月组建国家医疗保障局统一负责医保、医疗救助与药品招标采购，2018年11月国家组织药品集中带量采购试点启动；据国务院办公厅2021年印发的《“十四五”全民医疗保障规划》，基本医疗保险参保率目标稳定在95%以上。",figures:["李克强","陈竺"],place:"北京",state:"中华人民共和国",sources:["新华社2009年3月17日受权发布《中共中央 国务院关于深化医药卫生体制改革的意见》","国务院2009年3月发布的《医药卫生体制改革近期重点实施方案（2009—2011年）》","人力资源和社会保障部、卫生部2011年关于全民医保进展的新闻发布会通报","国务院办公厅2021年印发的《“十四五”全民医疗保障规划》"],tags:["医药卫生体制","基本药物","医疗保障"]},related:["cn--2006--p02", "cn--2010--i01"]},
{id:"cn--2009--e01",track:"cn",year:2009,yearApprox:false,dim:"economy",weight:3,title:"国务院发布十大产业调整振兴规划",summary:"2008年11月至2009年2月陆续出台，覆盖汽车、钢铁等十个行业。",detail:{background:"国际金融危机冲击下出口下滑、部分企业生产经营困难。为稳定增长并推动结构调整，国务院自2008年11月起陆续审议并通过相关产业规划，作为应对危机的一揽子政策组成部分。",process:"规划包括汽车、钢铁、纺织、装备制造、船舶、石化、轻工、有色金属、物流和电子信息十个产业，内容涉及技术改造、企业兼并重组、淘汰落后产能、出口退税调整和财政支持等。2009年1月国务院通过汽车产业调整振兴规划，对1.6升及以下排量乘用车减按5%征收车辆购置税，并安排补贴支持汽车下乡与以旧换新。",impact:"据中国汽车工业协会统计，2009年中国汽车产销分别达1379.1万辆和1364.48万辆，首次居世界第一位，此后多年保持第一。据海关总署统计，2009年中国货物出口总额超过德国，成为世界第一大货物出口国。投资与政策推动也加剧部分行业产能过剩压力，2009年9月国务院批转国家发展改革委等部门关于抑制部分行业产能过剩和重复建设引导产业健康发展的若干意见。",figures:["马凯"],place:"北京",state:"中华人民共和国",sources:["国务院2008年11月至2009年2月先后发布的十大产业调整振兴规划及新华社报道","中国汽车工业协会2010年1月发布的2009年汽车产销数据","海关总署2010年1月发布的2009年进出口统计数据"],tags:["产业振兴","汽车购置税","产能过剩"]},related:["cn--2008--e01", "cn--2001--e01"]},
{id:"cn--2009--f01",track:"cn",year:2009,yearApprox:false,dim:"figure",weight:3,title:"科学家钱学森在北京逝世",summary:"2009年10月31日逝世，享年98岁，是航天与导弹事业组织者。",detail:{background:"钱学森1911年12月生于上海，1930年代赴美留学，参与美国早期火箭研究及喷气推进实验室的创建工作；1950年起在美国被限制行动，1955年10月回到中国。",process:"回国后任中国科学院力学研究所所长、国防部第五研究院院长，主持组建中国第一个火箭与导弹研制机构；此后任第七机械工业部副部长、国防科学技术委员会副主任，参与组织导弹、火箭与卫星研制。1991年10月获国务院、中央军委授予“国家杰出贡献科学家”荣誉称号，1999年9月18日获中共中央、国务院、中央军委授予“两弹一星功勋奖章”。2009年10月31日14时29分在北京因病逝世。",impact:"其1954年出版的《工程控制论》与关于系统工程、系统科学的论述长期被国内高校与研究机构引用。他所参与和组织的航天工程形成酒泉、太原、西昌等发射场及长征系列运载火箭体系，1970年4月24日中国首颗人造地球卫星“东方红一号”发射。",figures:["钱学森"],place:"北京",state:"中华人民共和国",sources:["新华社2009年10月31日关于钱学森逝世的讣告与报道","国务院、中央军委1991年授予钱学森“国家杰出贡献科学家”荣誉称号的相关报道","中共中央、国务院、中央军委1999年9月18日授予“两弹一星功勋奖章”的表彰大会报道"],tags:["钱学森","两弹一星","航天事业"]},related:["cn--1956--s02", "cn--1964--s01", "cn--1970--s01"]},
{id:"cn--2010--e01",track:"cn",year:2010,yearApprox:false,dim:"economy",weight:4,title:"中国经济总量超过日本居世界第二",summary:"国家统计局公布2010年GDP初步核算为397983亿元、增长10.3%。",detail:{background:"国际金融危机后中国经济依靠扩大内需政策回升，同期日本经济长期低增长。经济总量位次按当年市场汇率折算比较，受汇率与价格统计影响明显。",process:"2011年1月国家统计局发布2010年国民经济运行情况，全年国内生产总值初步核算为397983亿元，按可比价格计算比上年增长10.3%。据国际货币基金组织和世界银行按市场汇率计算的年度统计，2010年中国经济总量超过日本，成为世界第二大经济体。2010年12月中央经济工作会议确定2011年实行积极的财政政策和稳健的货币政策。",impact:"据国家统计局后续年鉴核算，2010年经济总量数据有所上修。据联合国统计司数据，2010年中国制造业增加值超过美国居世界首位。此后据国家统计局公布，2019年人均国内生产总值超过1万美元，2020年国内生产总值突破100万亿元；中国在世界银行按市场汇率统计的经济总量排名中保持第二位。",figures:["马建堂"],place:"北京",state:"中华人民共和国",sources:["国家统计局2011年1月发布的2010年国民经济运行情况新闻发布材料","联合国统计司各国制造业增加值年度统计数据","国家统计局2021年1月发布的2020年国内生产总值初步核算结果"],tags:["经济总量","国内生产总值","世界第二大经济体"]},related:["cn--2001--e01", "cn--2004--e02", "cn--2008--e01"]},
{id:"cn--2010--i01",track:"cn",year:2010,yearApprox:false,dim:"institution",weight:4,title:"社会保险法通过并自2011年7月施行",summary:"2010年10月28日通过，确立养老、医疗、工伤、失业、生育保险框架。",detail:{background:"1951年劳动保险条例与1990年代各项保险单行规定长期并存；2003年新型农村合作医疗、2007年城镇居民基本医疗保险试点、2009年新型农村社会养老保险试点相继推开。该法1994年前后列入立法规划，2008年12月、2009年12月和2010年10月经全国人大常委会三次审议。",process:"2010年10月28日十一届全国人大常委会第十七次会议通过，自2011年7月1日施行。法律覆盖职工基本养老保险、职工基本医疗保险、工伤保险、失业保险和生育保险，规定个人跨统筹地区就业时基本养老保险关系随本人转移、缴费年限累计计算，基本养老保险基金逐步实行全国统筹；参加基本养老保险的个人达到法定退休年龄且累计缴费满十五年的，按月领取基本养老金。",impact:"据人力资源和社会保障部口径，2012年新农保与城镇居民社会养老保险合并为城乡居民社会养老保险，2014年国务院发布关于建立统一的城乡居民基本养老保险制度的意见；2018年12月29日全国人大常委会对社会保险法作部分修改，2019年5月起企业职工基本养老保险单位缴费比例降至16%，2019年起生育保险与职工基本医疗保险合并实施。据人力资源和社会保障部2023年度统计公报，截至2023年末全国基本养老保险参保人数超过10.6亿人。",figures:["尹蔚民"],place:"北京",state:"中华人民共和国",sources:["新华社2010年10月28日受权发布《中华人民共和国社会保险法》","国务院2014年2月关于建立统一的城乡居民基本养老保险制度的意见","人力资源和社会保障部2024年发布的2023年度人力资源和社会保障事业发展统计公报"],tags:["社会保险法","养老保险","全国统筹"]},related:["cn--2009--i01", "cn--2004--i01"]},
{id:"cn--2010--i02",track:"cn",year:2010,yearApprox:false,dim:"institution",weight:3,title:"选举法修改实行城乡同比选举代表",summary:"2010年3月14日通过修改决定，取消城乡代表所代表人口4比1的差别。",detail:{background:"1953年选举法规定农村与每一城市代表所代表人口比例为8比1，1995年修改为4比1。随着城镇化推进，2007年中共十七大报告提出建议逐步实行城乡按相同人口比例选举人大代表。",process:"2010年3月14日十一届全国人大三次会议通过关于修改选举法的决定，规定地方各级人民代表大会代表名额和每一代表所代表的人口数按城乡相同比例分配，即每一农村代表所代表人口数与城市每一代表所代表人口数相同；同时增加选举时应当设有秘密写票处等规定。",impact:"据全国人大常委会法制工作委员会关于修改决定的说明，修改后各级人大代表名额按城乡相同人口比例分配。此后2021年至2022年县乡两级人大换届选举、2023年1月至2月第十四届全国人大代表选举均按修改后的选举法进行。据国家统计局2021年5月发布的第七次全国人口普查公报，2020年11月1日零时全国城镇人口占常住人口比重为63.89%。",figures:["王兆国"],place:"北京",state:"中华人民共和国",sources:["新华社2010年3月14日关于十一届全国人大三次会议通过选举法修改决定的报道","全国人大常委会法制工作委员会关于选举法修改决定的说明","国家统计局2021年5月发布的第七次全国人口普查公报"],tags:["选举法","城乡同比","人大代表"]},related:["cn--1953--i01", "cn--1979--i01", "cn--2007--p01"]},
{id:"cn--2010--c01",track:"cn",year:2010,yearApprox:false,dim:"culture",weight:3,title:"上海举办中国首次注册类世界博览会",summary:"2010年5月1日至10月31日举行，246个参展方、参观逾7300万人次。",detail:{background:"世界博览会分为注册类与认可类。2002年12月3日，在国际展览局第132次大会上投票确定上海举办2010年注册类世博会，主题为“城市，让生活更美好”。此后按国际展览局规则编制总体规划并建设园区。",process:"2010年4月30日晚举行开幕式，国家主席胡锦涛宣布开幕，5月1日开园，10月31日闭幕，为期184天。园区分布在黄浦江两岸卢浦大桥与南浦大桥之间水域两岸，中国国家馆以“东方之冠”造型建成。据上海世博会事务协调局闭幕统计，共有246个国家和国际组织参展，累计参观7308.44万人次。",impact:"据国际展览局口径，这是首次在发展中国家举办的注册类世博会。此后中国以主办国身份参加2015年米兰世博会和2020年迪拜世博会（因疫情延至2021年10月至2022年3月举行）；世博会期间形成的城市运行、安保与志愿服务机制在此后国内大型活动中沿用，浦西园区部分场馆改造为文化与展览设施。",figures:["胡锦涛"],place:"上海",state:"中华人民共和国",sources:["国际展览局2002年12月3日第132次大会关于2010年注册类世博会举办地的投票结果","新华社2010年4月30日关于上海世博会开幕式的报道","上海世博会事务协调局2010年10月31日关于参展方与参观人次的统计发布"],tags:["上海世博会","城市让生活更美好","参观人次"]},related:["cn--1990--p01", "cn--2008--c01"]},
{id:"cn--2010--s01",track:"cn",year:2010,yearApprox:false,dim:"science",weight:3,title:"嫦娥二号发射并拓展至小行星探测",summary:"2010年10月1日发射，获取全月影像后于2012年飞越图塔蒂斯小行星。",detail:{background:"嫦娥二号作为嫦娥三号工程的先导验证星，搭载激光高度计、γ射线谱仪、X射线谱仪、微波探测仪与CCD立体相机等载荷，用于验证直接奔月轨道与高分辨率月面成像。",process:"2010年10月1日18时59分，嫦娥二号由长征三号丙运载火箭在西昌卫星发射中心发射，10月6日进入环月轨道。卫星先在100公里圆形轨道、后降至约15公里近月轨道开展成像，据国防科工局2011年7月发布，获取了覆盖全月面、分辨率为7米的月球影像图。2011年4月卫星受控进入日地拉格朗日L2点附近探测，之后返回并实施拓展任务；2012年12月13日飞越图塔蒂斯（4179 Toutatis）小行星，据国家航天局公布最近距离约3.2公里并获得小行星影像。",impact:"据国家航天局公布，嫦娥二号成为中国首个进入日地L2点探测并飞越小行星的航天器，其直接奔月转移轨道与高分辨率成像为2013年12月嫦娥三号月面软着陆提供了技术验证；此后嫦娥四号2019年1月实现月球背面软着陆，嫦娥五号2020年12月完成月球样品自动取样返回。",figures:["孙家栋","欧阳自远"],place:"西昌卫星发射中心及北京",state:"中华人民共和国",sources:["国防科工局2011年7月发布的嫦娥二号全月面影像图及相关说明","国家航天局2012年12月13日关于嫦娥二号飞越图塔蒂斯小行星的通报","国家航天局关于嫦娥三号、四号、五号任务的公开公告"],tags:["嫦娥二号","月球影像","小行星飞越"]},related:["cn--2007--s01", "cn--2004--s01"]},
{id:"cn--2010--d01",track:"cn",year:2010,yearApprox:false,dim:"disaster",weight:3,title:"玉树地震、舟曲泥石流与西南干旱相继发生",summary:"2010年4月青海玉树7.1级地震，8月甘肃舟曲特大山洪泥石流。",detail:{background:"2009年入秋后云南、贵州、广西、四川、重庆等省（区、市）降水持续偏少，出现冬春夏连旱；2010年4月14日青海玉树发生地震，同年8月甘肃舟曲因强降雨发生山洪泥石流。",process:"据中国地震台网测定，2010年4月14日7时49分青海省玉树藏族自治州玉树县发生7.1级地震，震源深度约14公里，结古镇、隆宝滩受灾严重，国务院成立抗震救灾总指挥部玉树指挥部。2010年8月7日夜间至8日凌晨，舟曲县城关镇一带暴发特大山洪泥石流，堵塞白龙江形成堰塞体，国家防汛抗旱总指挥部启动防汛应急响应并派出工作组。据国家防汛抗旱总指挥部办公室2010年通报，西南五省（区、市）旱情造成大范围农作物受灾和人口饮水困难。",impact:"2010年5月国务院批复《玉树地震灾后恢复重建总体规划》，确定用三年时间完成重建并实行对口支援；据国务院有关部门2013年发布情况，玉树灾后恢复重建主要目标任务基本完成。此类灾害推动了山洪与地质灾害监测预警、避险搬迁和病险水库除险加固等工作，2018年机构改革后应急管理部统一承担综合性防灾减灾救灾职责。",figures:["回良玉"],place:"青海省玉树藏族自治州、甘肃省舟曲县及西南五省（区、市）",state:"中华人民共和国",sources:["中国地震台网中心2010年4月14日玉树地震测定速报及国务院抗震救灾总指挥部玉树指挥部通报","国家防汛抗旱总指挥部办公室2010年关于西南旱情与舟曲山洪泥石流灾害的通报","国务院2010年5月批复的《玉树地震灾后恢复重建总体规划》"],tags:["玉树地震","舟曲泥石流","抗旱"]},related:["cn--2008--d01", "cn--1976--d01", "cn--1991--d01"]},
{id:"cn--2011--p01",track:"cn",year:2011,yearApprox:false,dim:"politics",weight:3,title:"十七届六中全会作出文化体制改革决定",summary:"2011年10月15日至18日召开，提出建设社会主义文化强国目标。",detail:{background:"2006年十六届六中全会提出构建社会主义和谐社会，2007年中共十七大把文化建设与经济建设、政治建设、社会建设并列部署，2010年十七届五中全会关于十二五规划的建议提出推动文化产业成为国民经济支柱性产业。",process:"2011年10月15日至18日，中共十七届六中全会在北京举行，通过《中共中央关于深化文化体制改革、推动社会主义文化大发展大繁荣若干重大问题的决定》；决定提出坚持中国特色社会主义文化发展道路、建设社会主义文化强国的目标，并部署完善文化管理体制、推动国有经营性文化单位转企改制、构建公共文化服务体系。",impact:"据文化部（2018年改组为文化和旅游部）与国家统计局后续公布的口径，全国文化及相关产业增加值占国内生产总值比重继续上升；2016年12月25日全国人大常委会通过《公共文化服务保障法》，自2017年3月1日施行；2017年1月中共中央办公厅、国务院办公厅印发《关于实施中华优秀传统文化传承发展工程的意见》，把传承体系建设纳入制度安排。",figures:["胡锦涛","蔡武"],place:"北京",state:"中华人民共和国",sources:["《中共中央关于深化文化体制改革、推动社会主义文化大发展大繁荣若干重大问题的决定》（2011年10月18日通过）及新华社报道","全国人大常委会2016年12月25日通过《中华人民共和国公共文化服务保障法》的公告"],tags:["文化体制改革","文化强国","公共文化服务"]},related:["cn--2006--p02"]},
{id:"cn--2011--d01",track:"cn",year:2011,yearApprox:false,dim:"disaster",weight:4,title:"甬温线发生7·23特别重大铁路交通事故",summary:"2011年7月23日发生，调查报告认定40人遇难、172人受伤。",detail:{background:"2008年后中国高速铁路规模快速扩大，2011年6月30日京沪高铁开通、7月全国铁路实行新的列车运行图。2011年7月23日晚间，浙江温州境内甬温线受雷击影响出现列控设备故障。",process:"2011年7月23日20时30分左右，北京南至福州的D301次列车与杭州南至福州南的D3115次列车在甬温线永嘉至温州南区间发生追尾，部分车辆坠桥。据国务院7·23甬温线特别重大铁路交通事故调查报告（2011年12月公布），事故造成40人遇难、172人受伤，直接经济损失19371.65万元；调查报告认定事故原因为列控设备故障后处置不到位，属责任事故，并提出对相关责任人的处理建议。",impact:"据铁道部2011年8月通报，全国铁路自2011年8月28日起实行新的列车运行图，部分时速350公里线路降速运行，高铁建设进度与安全审查同步收紧。事故暴露的设备准入与调度问题成为此后铁路安全管理与体制改革议题之一，2013年3月国务院机构改革撤销铁道部、实行政企分开，运输企业职责与中国铁路总公司、监管职责与交通运输部及国家铁路局分别划转。",figures:["盛光祖"],place:"浙江省温州市甬温线永嘉至温州南区间",state:"中华人民共和国",sources:["国务院7·23甬温线特别重大铁路交通事故调查报告（2011年12月公布）","新华社2011年7月24日至25日关于事故救援情况的报道","铁道部2011年8月关于全国铁路实行新的列车运行图的通报"],tags:["甬温线","动车组事故","铁路安全"]},related:["cn--2008--s02", "cn--2013--i01", "cn--1975--e01"]},
{id:"cn--2011--s01",track:"cn",year:2011,yearApprox:false,dim:"science",weight:3,title:"天宫一号与神舟八号完成首次交会对接",summary:"2011年9月29日天宫一号发射，11月3日与神舟八号对接。",detail:{background:"空间交会对接是载人航天工程第二步第一阶段的标志性技术。天宫一号为中国首个目标飞行器，神舟八号为无人飞船，两次任务均使用长征二号F运载火箭。",process:"2011年9月29日21时16分，天宫一号目标飞行器在酒泉卫星发射中心发射并进入近地点约200公里的轨道；11月1日神舟八号发射，11月3日凌晨两者完成自动交会对接，形成组合体；11月14日在完成分离后实施第二次交会对接。神舟八号返回舱于11月17日在内蒙古四子王旗着陆场着陆。",impact:"据中国载人航天工程办公室公布，中国由此掌握空间交会对接技术，为2012年6月神舟九号首次载人交会对接、2013年6月神舟十号对接及首次太空授课、2016年10月神舟十一号与天宫二号对接并驻留约30天提供条件；2021年4月29日天和核心舱发射后，空间站阶段多次完成载人飞船交会对接与转位。",figures:["中国载人航天工程办公室","王永志"],place:"酒泉卫星发射中心、内蒙古四子王旗着陆场",state:"中华人民共和国",sources:["中国载人航天工程办公室2011年11月3日关于首次交会对接成功的情况发布及新华社报道","中国载人航天工程办公室2013年6月关于神舟十号任务与太空授课的通报"],tags:["天宫一号","神舟八号","交会对接"]},related:["cn--2008--s01", "cn--1992--s01", "cn--2012--s01"]},
{id:"cn--2011--e01",track:"cn",year:2011,yearApprox:false,dim:"economy",weight:3,title:"城镇常住人口比例首次超过50%",summary:"据国家统计局，2011年末城镇常住人口占总人口比重超过50%。",detail:{background:"1978年末城镇人口比重为17.92%，此后农村劳动力持续向沿海地区和城市转移。据2010年第六次全国人口普查，城镇人口占总人口比重为49.68%。",process:"据国家统计局2012年1月发布的2011年国民经济运行情况，2011年末中国大陆总人口134735万人，其中城镇人口69079万人，占总人口比重（城镇化率）为51.27%，比上年末提高1.32个百分点，为历史上首次超过50%。据国家统计局同期发布的《2011年全国农民工监测调查报告》，全国农民工总量25278万人，其中外出农民工15863万人。",impact:"据国家统计局历年统计公报，城镇化率此后持续上升，2013年末为53.73%，2023年末为66.16%。常住人口城镇化率与户籍人口城镇化率之间长期存在差距，2014年7月国务院印发《关于进一步推进户籍制度改革的意见》，提出取消农业户口与非农业户口性质区分、建立城乡统一的户口登记制度，《居住证暂行条例》自2016年1月1日起施行；2022年3月国家发展改革委印发《2022年新型城镇化和城乡融合发展重点任务》延续农业转移人口市民化政策。",figures:["马建堂"],place:"全国",state:"中华人民共和国",sources:["国家统计局2012年1月发布的2011年国民经济运行情况新闻发布材料","国家统计局2012年4月发布的《2011年全国农民工监测调查报告》","国务院2014年7月印发的《关于进一步推进户籍制度改革的意见》","国家统计局2024年1月公布的2023年城镇化率数据"],tags:["城镇化","农民工","户籍制度改革"]},related:["cn--1978--e01", "cn--2010--i02"]},
{id:"cn--2012--p01",track:"cn",year:2012,yearApprox:false,dim:"politics",weight:5,title:"中国共产党第十八次全国代表大会召开",summary:"2012年11月8日至14日召开，把科学发展观确立为党的指导思想。",detail:{background:"2007年中共十七大把科学发展观写入党章。2012年6月至9月，各省、自治区、直辖市和中央机关等选举单位选出出席十八大的代表。",process:"2012年11月8日至14日在北京举行，胡锦涛作《坚定不移沿着中国特色社会主义道路前进，为全面建成小康社会而奋斗》的报告；大会通过关于十七届中央委员会报告的决议和关于《中国共产党章程（修正案）》的决议，把科学发展观同马克思列宁主义、毛泽东思想、邓小平理论、“三个代表”重要思想一道确立为党的指导思想，并把生态文明建设纳入中国特色社会主义事业总体布局。11月15日十八届一中全会选举习近平为中共中央总书记、中共中央军事委员会主席。",impact:"大会提出国内生产总值和城乡居民人均收入比2010年翻一番等目标；2012年12月4日中央政治局会议审议通过关于改进工作作风、密切联系群众的八项规定，2013年起分批开展党的群众路线教育实践活动，2013年11月十八届三中全会通过《中共中央关于全面深化改革若干重大问题的决定》；2018年3月宪法修正案确立监察委员会的宪法地位，同年3月组建国家监察委员会。",figures:["胡锦涛","习近平"],place:"北京（人民大会堂）",state:"中华人民共和国",sources:["《中国共产党第十八次全国代表大会文件汇编》（人民出版社2012年）","新华社2012年11月15日关于十八届一中全会选举结果的报道","新华社2012年12月4日关于中央政治局审议通过八项规定的报道"],tags:["中共十八大","科学发展观","八项规定"]},related:["cn--2007--p01", "cn--2011--p01"]},
{id:"cn--2012--e01",track:"cn",year:2012,yearApprox:false,dim:"economy",weight:3,title:"GDP增长目标21年来首次下调至7.5%",summary:"2012年3月政府工作报告把预期目标定为7.5%，为1991年以来首次低于8%。",detail:{background:"2011年12月中央经济工作会议确定2012年坚持稳中求进的工作总基调；2012年欧债危机持续、外需疲弱，工业与出口增速逐季回落。",process:"2012年3月5日温家宝在十一届全国人大五次会议作《政府工作报告》，提出当年国内生产总值增长预期目标为7.5%，为1991年以来首次低于8%。为稳定增长，国务院在年中部署稳增长措施，中国人民银行于2012年5月18日、6月5日两次下调存款准备金率，6月8日、7月6日两次下调存贷款基准利率，并集中审批和开工一批基础设施项目。",impact:"据国家统计局2013年1月公布，2012年国内生产总值比上年增长7.7%，为1999年以来首次低于8%。此后年度增长目标连续保持在7.5%左右，调控方式转向区间管理与预期引导：2015年11月中央提出着力加强供给侧结构性改革，2019年政府工作报告把预期目标定为6%—6.5%，2020年因疫情未设定年度增速目标，2021年目标定为6%以上。",figures:["温家宝"],place:"北京",state:"中华人民共和国",sources:["2012年3月5日《政府工作报告》及新华社报道","中国人民银行2012年5月、6月、7月货币政策调整公告","国家统计局2013年1月发布的2012年国民经济运行情况新闻发布材料"],tags:["经济增长目标","稳增长","区间调控"]},related:["cn--2008--e01", "cn--2011--e01"]},
{id:"cn--2012--i01",track:"cn",year:2012,yearApprox:false,dim:"institution",weight:3,title:"刑事诉讼法修正案通过并2013年施行",summary:"2012年3月14日十一届全国人大五次会议通过修改决定。",detail:{background:"1979年刑事诉讼法制定、1996年第一次修改。2010年6月最高人民法院、最高人民检察院等联合发布《关于办理死刑案件审查判断证据若干问题的规定》和《关于办理刑事案件排除非法证据若干问题的规定》，为法律修改提供了操作基础。",process:"2012年3月14日十一届全国人大五次会议通过关于修改刑事诉讼法的决定，自2013年1月1日施行。修改把“尊重和保障人权”写入任务，完善证据制度与非法证据排除规则，规定不得强迫任何人证实自己有罪，规范技术侦查措施的适用与批准程序，扩大法律援助范围，增设未成年人刑事案件诉讼程序、当事人和解的公诉案件诉讼程序、犯罪嫌疑人逃匿或死亡案件违法所得没收程序和依法不负刑事责任的精神病人的强制医疗程序等特别程序。",impact:"据最高人民法院、最高人民检察院此后发布的司法解释，非法证据排除与技术侦查审批进入庭审与侦查操作层面；2017年6月最高人民法院等联合印发《关于办理刑事案件严格排除非法证据若干问题的规定》。2018年3月20日第十三届全国人大一次会议通过《监察法》，同年10月26日全国人大常委会再次修改刑事诉讼法，正式确立认罪认罚从宽制度并增设速裁程序。",figures:["吴邦国"],place:"北京",state:"中华人民共和国",sources:["新华社2012年3月14日关于十一届全国人大五次会议通过刑事诉讼法修改决定的报道","最高人民法院等2017年6月《关于办理刑事案件严格排除非法证据若干问题的规定》","全国人大常委会2018年10月26日关于修改刑事诉讼法的决定"],tags:["刑事诉讼法","非法证据排除","特别程序"]},related:["cn--1979--i01", "cn--1997--i01", "cn--1991--i01"]},
{id:"cn--2012--s01",track:"cn",year:2012,yearApprox:false,dim:"science",weight:3,title:"神舟九号完成首次载人交会对接",summary:"2012年6月16日发射，24日在刘旺手动控制下与天宫一号对接。",detail:{background:"2011年11月天宫一号与神舟八号完成无人自动交会对接后，第二步第一阶段转入载人对接与驻留验证。神舟九号乘组由景海鹏、刘旺、刘洋组成，刘洋为中国首位进入太空的女航天员。",process:"2012年6月16日18时37分，神舟九号由长征二号F运载火箭在酒泉卫星发射中心发射；6月18日完成自动交会对接；6月24日在航天员刘旺手动控制下再次完成交会对接，航天员随后进入天宫一号并开展科学实验与技术验证，完成任务后返回舱在内蒙古四子王旗主着陆场着陆。",impact:"据中国载人航天工程办公室公布，中国成为完整掌握空间交会对接技术的国家之一。2013年6月神舟十号与天宫一号对接，6月20日航天员王亚平进行首次太空授课；2016年10月至11月神舟十一号航天员景海鹏、陈冬在天宫二号驻留约30天；2021年后空间站阶段由神舟十二号起实现航天员乘组轮换驻留。",figures:["景海鹏","刘旺","刘洋"],place:"酒泉卫星发射中心、内蒙古四子王旗主着陆场",state:"中华人民共和国",sources:["中国载人航天工程办公室2012年6月关于神舟九号任务情况的发布及新华社报道","中国载人航天工程办公室2013年6月关于太空授课活动的通报"],tags:["神舟九号","载人交会对接","女航天员"]},related:["cn--2011--s01", "cn--2008--s01", "cn--2003--s01"]},
{id:"cn--2012--s02",track:"cn",year:2012,yearApprox:false,dim:"science",weight:3,title:"蛟龙号载人潜水器完成7062米海试",summary:"2012年6月在马里亚纳海沟创造当时中国载人深潜纪录。",detail:{background:"蛟龙号由国家高技术研究发展计划（863计划）海洋技术领域支持，国内科研院所与企业联合设计集成，2009年起分级海试：2009年完成1000米级、2010年3000米级、2011年5000米级。",process:"2012年6月，蛟龙号在西太平洋马里亚纳海沟试验海区开展7000米级海试，据科技部863计划海洋技术领域公布，最大下潜深度达7062米，并在海底采集生物与岩石样品、布放标志物，创造了当时中国载人深潜的最大深度纪录。",impact:"据科技部公布，中国由此成为具备7000米级载人深潜能力的国家之一，蛟龙号2013年起转入试验性应用航次并在多个海区开展调查。此后国产“深海勇士”号4500米级载人潜水器于2017年完成海试并通过验收，“奋斗者”号于2020年11月在马里亚纳海沟完成万米级坐底，据自然资源部公布最大深度10909米。",figures:["崔维成","叶聪"],place:"西太平洋马里亚纳海沟试验海区",state:"中华人民共和国",sources:["科技部863计划海洋技术领域2012年6月关于蛟龙号7000米级海试结果的公布","自然资源部2020年11月关于“奋斗者”号万米海试结果的通报"],tags:["蛟龙号","载人深潜","深海探测"]},related:["cn--1986--s01", "cn--2020--x01"]},
{id:"cn--2012--m01",track:"cn",year:2012,yearApprox:false,dim:"military",weight:4,title:"辽宁舰入列与歼-15舰载机完成着舰",summary:"2012年9月25日辽宁舰交付入列，11月23日歼-15完成首次着舰。",detail:{background:"辽宁舰由改建的旧船体续建而成，2011年8月10日完成首次海试，此后进行多期科研试验与训练；舰载战斗机歼-15由国内研制，2012年前已完成陆基试验。",process:"2012年9月25日，中国第一艘航空母舰辽宁舰正式交付海军，舷号16。同年11月23日，歼-15舰载战斗机在辽宁舰成功完成阻拦着舰和滑跃起飞试验，据国防部新闻事务局发布的消息，飞行员戴明盟驾驶战机完成首次着舰；11月25日相关影像由媒体公开报道。",impact:"据国防部此后公布的训练信息，2013年起辽宁舰编队多次赴远海组织训练。航母平台建设在此后持续推进：第一艘国产航母山东舰2019年12月17日入列，舷号17；2022年6月17日采用电磁弹射的福建舰下水，舷号18，据国防部公布的口径后续开展海试。",figures:["戴明盟"],place:"大连及黄海、东海试验海区",state:"中华人民共和国",sources:["新华社2012年9月25日关于辽宁舰交付入列的报道","国防部新闻事务局2012年11月关于歼-15舰载机着舰起飞的发布信息","新华社2019年12月17日关于山东舰入列的报道"],tags:["辽宁舰","歼-15","航空母舰"]},related:["cn--1974--s01", "cn--2009--p01"]},
{id:"cn--2012--c01",track:"cn",year:2012,yearApprox:false,dim:"culture",weight:3,title:"莫言获诺贝尔文学奖",summary:"2012年10月获诺贝尔文学奖，其《蛙》2011年获茅盾文学奖。",detail:{background:"诺贝尔文学奖由瑞典学院评选，自1901年起颁发。在此前的获奖者中，2000年获奖的高行健当时已为法国籍；莫言为出生于中国本土并用中文写作而获该奖的作家。",process:"莫言本名管谟业，1955年生于山东高密，1980年代中期以《透明的红萝卜》《红高粱家族》成名，此后出版《酒国》《丰乳肥臀》《生死疲劳》《蛙》等长篇小说。据中国作家协会公告，2011年《蛙》获第八届茅盾文学奖。2012年10月11日瑞典学院宣布将2012年诺贝尔文学奖授予莫言，公布的授奖理由称其作品“将民间故事、历史与当代社会融合在一起”；同年12月7日莫言在瑞典学院发表题为《讲故事的人》的演讲。",impact:"据出版机构与瑞典学院公布的信息，获奖后莫言作品版权输出与国内印数明显增加，其高密东北乡系列叙事被更多译本收入外国文学丛书。据卡罗琳斯卡学院2015年10月公布的授奖理由，中国药学家屠呦呦因发现青蒿素获诺贝尔生理学或医学奖。",figures:["莫言"],place:"山东高密及瑞典斯德哥尔摩",state:"中华人民共和国",sources:["瑞典学院2012年10月11日关于诺贝尔文学奖的公告及新华社报道","中国作家协会关于第八届茅盾文学奖评选结果的公告","卡罗琳斯卡学院2015年10月关于诺贝尔生理学或医学奖的授奖公告"],tags:["莫言","诺贝尔文学奖","茅盾文学奖"]},related:["cn--1982--c01", "cn--2011--p01"]},
{id:"cn--2012--d01",track:"cn",year:2012,yearApprox:false,dim:"disaster",weight:3,title:"北京发生7·21特大暴雨灾害",summary:"2012年7月21日至22日暴雨致城区严重积水，官方通报79人遇难。",detail:{background:"北京城区排水设施标准总体偏低，下凹桥区与河道两岸在强降雨下易积水。2012年7月21日至22日全市出现持续强降雨并伴雷电、大风。",process:"据北京市政府2012年8月通报，此次降雨全市平均降水量达164毫米，最大降水量出现在房山区河北镇；城区多处下凹桥区与道路积水，京港澳高速北京段部分路段车辆被困，首都国际机场航班大面积延误，市区交通一度大范围中断。据同一通报，灾害造成79人遇难。",impact:"灾后北京集中开展下凹桥区排水改造、河道治理与防汛物资储备，并公开气象预警与应急响应衔接机制。在国家层面，国务院2013年10月公布《城镇排水与污水处理条例》，自2014年3月1日施行；2015年起分批开展海绵城市建设试点，2021年国务院办公厅印发《关于加强城市内涝治理的实施意见》，提出到2025年基本形成城市排水防涝工程体系。",figures:["郭金龙"],place:"北京市",state:"中华人民共和国",sources:["北京市政府2012年8月关于“7·21”特大暴雨灾害情况的新闻通气会通报","北京市气象台2012年7月关于降水量的监测发布","国务院办公厅2021年印发的《关于加强城市内涝治理的实施意见》"],tags:["特大暴雨","城市内涝","排水防涝"]},related:["cn--2010--d01", "cn--1991--d01"]},
{id:"cn--2013--p01",track:"cn",year:2013,yearApprox:false,dim:"politics",weight:3,title:"十二届全国人大一次会议完成换届",summary:"2013年3月5日至17日召开，习近平当选国家主席，张德江任委员长。",detail:{background:"2013年2月中共十八届二中全会审议通过《国务院机构改革和职能转变方案》和拟向全国人大推荐的国家机构领导人员人选建议名单，提交十二届全国人大一次会议。",process:"会议3月5日至17日在北京举行。3月14日选举习近平为中华人民共和国主席，同日会议批准国务院机构改革和职能转变方案；3月15日选举张德江为全国人大常委会委员长，并根据国家主席提名决定李克强为国务院总理；随后会议选举国家中央军事委员会主席，决定国务院其他组成人员，选举最高人民法院院长、最高人民检察院检察长。",impact:"此次换届产生的国家机构领导人员任期内，2018年3月十三届全国人大一次会议通过宪法修正案，删除国家主席、副主席连续任职届数的规定，2018年、2023年两届全国人大一次会议按相同程序完成换届。2013年机构改革中组建的国家卫生和计划生育委员会2018年改组为国家卫生健康委员会。",figures:["习近平","李克强","张德江"],place:"北京",state:"中华人民共和国",sources:["新华社2013年3月14日至17日关于十二届全国人大一次会议选举和决定结果的报道","十二届全国人大一次会议2013年3月14日关于批准国务院机构改革和职能转变方案的决定"],tags:["换届","全国人大","国家机构"]},related:["cn--2008--p01", "cn--2013--i01"]},
{id:"cn--2013--i01",track:"cn",year:2013,yearApprox:false,dim:"institution",weight:4,title:"铁道部撤销实行铁路政企分开",summary:"2013年3月批准改革方案，组建国家铁路局并设立中国铁路总公司。",detail:{background:"铁道部长期同时承担行业监管与企业经营职能。2011年7月甬温线事故后，铁路安全管理与体制机制问题受到关注，此后铁道部组织研究政企分开方案。",process:"2013年3月10日，《国务院机构改革和职能转变方案》提请十二届全国人大一次会议审议，3月14日会议批准该方案。方案规定把铁道部拟订铁路发展规划和政策的行政职责划入交通运输部；组建国家铁路局，由交通运输部管理，承担铁道部其他行政职责；组建中国铁路总公司，承担铁道部的企业职责，同时不再保留铁道部。同年3月中国铁路总公司、国家铁路局相继挂牌。",impact:"据交通运输部公布，政企分开后铁路发展规划与政策职责归入交通运输部，安全监管由国家铁路局承担，运输经营由中国铁路总公司负责；2013年8月国务院发布《关于改革铁路投融资体制加快推进铁路建设的意见》，提出推进铁路投融资体制改革、吸引社会资本参与铁路建设。据中国国家铁路集团有限公司公布，2019年6月中国铁路总公司完成公司制改制，更名为中国国家铁路集团有限公司。",figures:["盛光祖"],place:"北京",state:"中华人民共和国",sources:["十二届全国人大一次会议2013年3月14日关于批准国务院机构改革和职能转变方案的决定及新华社受权发布","国务院2013年8月《关于改革铁路投融资体制加快推进铁路建设的意见》","中国国家铁路集团有限公司2019年关于公司制改制的公告"],tags:["铁道部","政企分开","国家铁路局"]},related:["cn--2011--d01", "cn--2008--s02", "cn--1975--e01"]},
{id:"cn--2013--i02",track:"cn",year:2013,yearApprox:false,dim:"institution",weight:3,title:"全国人大常委会决定废止劳动教养制度",summary:"2013年11月中央全会提出废止，12月28日人大常委会通过废止决定。",detail:{background:"劳动教养制度依据1957年经全国人大常委会批准、国务院公布的《关于劳动教养问题的决定》建立，此后有补充规定。2003年孙志刚案后，国务院废止《城市流浪乞讨人员收容遣送办法》并改用救助管理办法，此后劳动教养制度的合法性与适用范围持续受到讨论。",process:"2013年11月9日至12日，中共十八届三中全会通过《中共中央关于全面深化改革若干重大问题的决定》，提出废止劳动教养制度、完善对违法犯罪行为的惩治和矫正法律、健全社区矫正制度。2013年12月28日，十二届全国人大常委会第六次会议通过《关于废止有关劳动教养法律规定的决定》，自公布之日起施行，并规定对正在被依法执行劳动教养的人员解除劳动教养。",impact:"据公安部、司法部通报，废止决定施行后全国劳动教养场所停止收押并陆续转型。轻微违法犯罪与药物依赖治理此后依治安管理处罚法、禁毒法下的强制隔离戒毒制度处理；2019年12月28日全国人大常委会通过《中华人民共和国社区矫正法》，自2020年7月1日施行，把社区矫正的执行与保障纳入法律框架。",figures:["张德江"],place:"北京",state:"中华人民共和国",sources:["新华社2013年11月12日关于《中共中央关于全面深化改革若干重大问题的决定》的报道","新华社2013年12月28日关于十二届全国人大常委会第六次会议通过废止劳动教养法律规定决定的报道","全国人大常委会2019年12月28日通过《中华人民共和国社区矫正法》的公告"],tags:["劳动教养","制度废止","社区矫正"]},related:["cn--2013--p01", "cn--2012--i01"]},
{id:"cn--2013--m01",track:"cn",year:2013,yearApprox:false,dim:"military",weight:3,title:"国防部公布划设东海防空识别区",summary:"2013年11月23日发布航空器识别规则公告及示意图，当日施行。",detail:{background:"防空识别区由一些国家在国内防空需要下先后划设。中国在2013年前未在东海方向公布过此类识别规则；同年日本、韩国围绕该空域的表态与行动增多。",process:"2013年11月23日，中华人民共和国国防部发表声明并发布《中华人民共和国防空识别区航空器识别规则公告》和识别区示意图，划设东海防空识别区，规定进入该空域的航空器须满足识别要求、报告飞行计划并接受识别应答，否则中国武装力量将采取防御性紧急处置措施；公告同时声明识别区不改变有关空域的法律地位，不影响依据国际法享有的飞越自由。声明自公布之日起施行。",impact:"公告发布后，美国、日本等国军方与外交部门表态，美军轰炸机在未通报情况下飞入该空域，中日、中美之间出现交涉。据国防部此后公布的训练信息，中国军队航空兵在该方向组织巡逻与远海训练成为常态；2013年12月韩国扩大其防空识别区，重叠空域的管理成为中韩之间的外交议题。",figures:["常万全"],place:"北京；识别区位于东海空域",state:"中华人民共和国",sources:["国防部2013年11月23日发布的《中华人民共和国防空识别区航空器识别规则公告》及示意图","新华社2013年11月23日关于划设东海防空识别区的报道"],tags:["东海防空识别区","航空器识别","国防部"]},related:["cn--2012--m01", "cn--1988--m01"]},
{id:"cn--2013--e01",track:"cn",year:2013,yearApprox:false,dim:"economy",weight:3,title:"中国上海自由贸易试验区挂牌运行",summary:"2013年8月国务院批准设立，9月29日在上海浦东新区挂牌。",detail:{background:"2013年此前，上海已就设立自由贸易港区进行多年研究。据新华社2013年8月报道，国务院批准设立中国（上海）自由贸易试验区，同年9月国务院印发《中国（上海）自由贸易试验区总体方案》，范围涵盖外高桥保税区、外高桥保税物流园区、洋山保税港区和浦东机场综合保税区等区域。",process:"2013年9月29日，中国（上海）自由贸易试验区管理委员会在上海浦东新区挂牌，试验区正式运行。方案规定试验区试行外商投资准入前国民待遇加负面清单管理模式，推进贸易便利化、投资开放、金融领域开放与事中事后监管改革，并暂停实施部分法律规定的行政审批。2014年7月上海市人大常委会通过《中国（上海）自由贸易试验区条例》，自2014年8月1日施行。",impact:"据商务部公布，自贸区试验此后分批扩展：2015年4月广东、天津、福建自由贸易试验区及上海自贸区扩展区域运行，2017年3月辽宁、浙江、河南、湖北、重庆、四川、陕西自贸区挂牌，2018年4月海南全岛建设自由贸易试验区并于2020年6月印发《海南自由贸易港建设总体方案》，2020年9月北京、湖南、安徽自贸区及浙江自贸区扩展区域获批；2023年11月新疆自贸区挂牌后，全国共设22个自由贸易试验区。负面清单与“先照后证”等做法被复制推广到全国。",figures:["汪洋","韩正"],place:"上海浦东新区",state:"中华人民共和国",sources:["新华社2013年8月关于国务院批准设立中国（上海）自由贸易试验区的报道","国务院2013年印发的《中国（上海）自由贸易试验区总体方案》","商务部2023年关于自由贸易试验区布局与制度创新的公开信息"],tags:["自由贸易试验区","负面清单","制度创新"]},related:["cn--1990--e01", "cn--2001--e01", "cn--2015--e01"]},
{id:"cn--2013--s01",track:"cn",year:2013,yearApprox:false,dim:"science",weight:4,title:"嫦娥三号实现月面软着陆与巡视探测",summary:"2013年12月2日发射，14日软着陆，玉兔号月球车开展巡视。",detail:{background:"嫦娥三号由着陆器和月面巡视器（玉兔号月球车）组成，由长征三号乙运载火箭在西昌卫星发射中心发射。据国家航天局公布的预选着陆区，落区位于月球正面虹湾地区附近。",process:"2013年12月2日1时30分嫦娥三号发射，12月6日实施近月制动进入环月轨道；12月14日21时11分着陆器携带巡视器成功软着陆于月面，12月15日玉兔号月球车驶下落月架，两器互拍的影像传回地面，据国家航天局于12月15日召开月球探测工程发布会公布。",impact:"据国家航天局公布，中国成为继苏联、美国之后第三个实现航天器地外天体软着陆的国家，玉兔号成为我国首个月球巡视器，其在月面工作时间超出设计寿命。此后2019年1月3日嫦娥四号着陆器与玉兔二号经鹊桥中继星支持在月球背面软着陆，2020年12月嫦娥五号完成月球样品自动取样返回。",figures:["孙泽洲","欧阳自远"],place:"西昌卫星发射中心及月球虹湾地区",state:"中华人民共和国",sources:["国家航天局2013年12月14日关于嫦娥三号成功落月的发布及新华社报道","国家航天局2013年12月15日关于两器互拍影像与任务情况的发布会材料"],tags:["嫦娥三号","月面软着陆","玉兔号"]},related:["cn--2010--s01", "cn--2007--s01", "cn--2004--s01"]},
{id:"cn--2014--p01",track:"cn",year:2014,yearApprox:false,dim:"politics",weight:4,title:"中共十八届四中全会部署全面推进依法治国",summary:"2014年10月20日至23日召开，通过全面推进依法治国若干重大问题的决定。",detail:{background:"2012年中共十八大把法治表述为治国方式的重要内容，2013年十八届三中全会部署全面深化改革。四中全会以全面推进依法治国为主题，据新华社说明，这是党的中央全会第一次以法治建设为主题。",process:"2014年10月20日至23日，中共十八届四中全会在北京举行，通过《中共中央关于全面推进依法治国若干重大问题的决定》。决定提出建设中国特色社会主义法治体系、建设社会主义法治国家的总目标，部署加强宪法实施与监督、推行依法行政、保证公正司法、建设法治工作队伍等内容，并提出实行宪法宣誓制度、建立司法责任制、设立最高人民法院巡回法庭与跨行政区划法院等举措。",impact:"2015年7月1日十二届全国人大常委会第十五次会议通过关于实行宪法宣誓制度的决定，自2016年1月1日起施行，2018年2月修订后由全国人大常委会委员长会议组织实施。据全国人大常委会法制工作委员会历年备案审查工作报告，2017年12月起法工委每年向常委会报告备案审查工作情况；2018年3月宪法修正案通过后，全国人大法律委员会更名为全国人大宪法和法律委员会。",figures:["习近平"],place:"北京",state:"中华人民共和国",sources:["《中共中央关于全面推进依法治国若干重大问题的决定》（2014年10月23日通过）及新华社受权发布","全国人大常委会2015年7月1日关于实行宪法宣誓制度的决定","全国人大常委会法制工作委员会历年备案审查工作情况报告"],tags:["依法治国","宪法宣誓","备案审查"]},related:["cn--2012--p01", "cn--1982--i01", "cn--2013--i02"]},
{id:"cn--2014--i01",track:"cn",year:2014,yearApprox:false,dim:"institution",weight:3,title:"行政诉讼法修改自2015年5月施行",summary:"2014年11月1日人大常委会通过修改决定，2015年5月1日起施行。",detail:{background:"1989年通过的行政诉讼法自1990年10月1日施行后，“立案难、审理难、执行难”与地方干预行政审判的问题长期被反映，2013年十八届三中全会提出修改行政诉讼法。",process:"2014年11月1日，十二届全国人大常委会第十一次会议通过关于修改行政诉讼法的决定，自2015年5月1日施行。修改把解决行政争议写入立法目的，扩大受案范围并将部分规范性文件纳入一并审查，规定法院应当保障当事人起诉权利、实行登记立案并一次性告知补正，明确经复议案件的双被告规则、被诉行政机关负责人应当出庭应诉，禁止行政机关干预人民法院受理行政案件，并增加跨行政区划管辖与提级审理等安排。",impact:"据最高人民法院2015年公布的立案登记制实施情况，2015年5月1日后全国法院一审行政案件受理数量明显增长。2014年12月起北京、上海等地设立跨行政区划法院，集中审理以政府部门为被告的案件。2017年6月27日全国人大常委会修改行政诉讼法与民事诉讼法，增加检察机关提起公益诉讼的条款。",figures:["周强"],place:"北京",state:"中华人民共和国",sources:["新华社2014年11月1日关于十二届全国人大常委会第十一次会议通过行政诉讼法修改决定的报道","最高人民法院2015年关于立案登记制实施情况的通报","全国人大常委会2017年6月27日关于修改行政诉讼法、民事诉讼法的决定"],tags:["行政诉讼","立案登记制","跨行政区划管辖"]},related:["cn--1989--i01", "cn--2014--p01"]},
{id:"cn--2014--i02",track:"cn",year:2014,yearApprox:false,dim:"institution",weight:3,title:"设立抗战胜利纪念日与国家公祭日",summary:"2014年2月27日人大常委会通过决定，12月13日举行首次公祭仪式。",detail:{background:"1949年以来，抗日战争胜利纪念日的日期曾有调整；南京大屠杀发生于1937年12月13日之后。据远东国际军事法庭和南京审判战犯军事法庭判决认定，侵华日军在南京屠杀中国军民人数在30万人以上。",process:"2014年2月27日，十二届全国人大常委会第七次会议通过决定，将9月3日确定为中国人民抗日战争胜利纪念日，将12月13日设立为南京大屠杀死难者国家公祭日。2014年12月13日首个南京大屠杀死难者国家公祭仪式在侵华日军南京大屠杀遇难同胞纪念馆举行，此后每年同日举行。2015年9月3日首都举行纪念中国人民抗日战争暨世界反法西斯战争胜利70周年大会与阅兵式。",impact:"据国家档案局与联合国教科文组织2015年10月公布的《世界记忆名录》新增项目，《南京大屠杀档案》列入名录。2015年8月29日十二届全国人大常委会第十六次会议通过关于特赦部分服刑罪犯的决定，为1982年宪法施行以来首次特赦。2019年9月29日国家勋章和国家荣誉称号颁授仪式在人民大会堂举行，据全国人大常委会2019年9月17日的决定授予于敏、申纪兰、孙家栋、李延年、张富清、袁隆平、黄旭华、屠呦呦共和国勋章或国家荣誉称号。",figures:["张德江"],place:"北京及江苏南京",state:"中华人民共和国",sources:["新华社2014年2月27日关于十二届全国人大常委会第七次会议通过两个纪念日和公祭日决定的报道","联合国教科文组织2015年10月《世界记忆名录》新增项目公告","新华社2019年9月29日关于国家勋章和国家荣誉称号颁授仪式的报道"],tags:["国家公祭日","抗战胜利纪念日","特赦"]},related:["cn--2014--p01", "cn--2015--m01"]},
{id:"cn--2014--e01",track:"cn",year:2014,yearApprox:false,dim:"economy",weight:3,title:"中央提出经济发展新常态判断",summary:"2014年5月在河南考察时提出“新常态”，12月中央经济工作会议系统阐述。",detail:{background:"2012年、2013年国内生产总值均增长7.7%，出口增速回落、工业产能利用率和投资回报率下行，宏观调控的思路讨论随之展开。",process:"2014年5月，习近平在河南考察时提出从当前中国经济发展阶段特征出发、适应新常态、保持战略上的平常心态。2014年11月9日，习近平在亚太经合组织工商领导人峰会演讲中从速度、结构、驱动三个方面说明经济增长特点。2014年12月9日至11日中央经济工作会议提出认识新常态、适应新常态、引领新常态，并从消费需求、投资需求、出口和国际收支、生产能力和产业组织方式、生产要素相对优势、市场竞争特点、资源环境约束、经济风险积累与化解、资源配置模式和宏观调控方式等方面阐述趋势性变化。",impact:"据国家统计局2015年2月发布的数据，2014年国内生产总值增长7.4%，为1999年以来最低增速。2015年10月中共十八届五中全会提出创新、协调、绿色、开放、共享五大发展理念，2015年11月中央提出着力加强供给侧结构性改革，2016年去产能、去库存、去杠杆、降成本、补短板成为政策主线，2017年10月中共十九大报告提出我国经济已由高速增长阶段转向高质量发展阶段。",figures:["习近平"],place:"北京及河南等地",state:"中华人民共和国",sources:["新华社2014年5月关于在河南考察的报道","2014年12月9日至11日中央经济工作会议消息及新华社报道","国家统计局2015年2月发布的2014年国民经济运行情况数据"],tags:["新常态","增长速度","宏观调控"]},related:["cn--2012--e01", "cn--2015--p01"]},
{id:"cn--2014--s01",track:"cn",year:2014,yearApprox:false,dim:"science",weight:3,title:"兰新铁路第二双线建成通车",summary:"2014年12月26日通车，连接兰州与乌鲁木齐，正线长约1776公里。",detail:{background:"兰新铁路既有线进出疆运力长期紧张，沿线存在百里风区与高海拔地段。兰新铁路第二双线在此背景下规划建设，线路以桥隧与挡风工程通过大风与山岭地区。",process:"2014年12月26日，兰新铁路第二双线（兰州南至乌鲁木齐）开通运营，正线全长约1776公里，设计时速200公里以上，沿线设西宁、张掖、嘉峪关、哈密、吐鲁番北等车站。据中国铁路总公司公布，该线为一次性建成并开通运营里程较长的高速铁路。",impact:"据中国铁路总公司公布，通车后兰州与乌鲁木齐间旅客旅行时间较普速列车明显缩短，青海首次接入高速铁路网。2017年7月宝鸡至兰州高铁开通后，陆桥方向高铁通道贯通至西北地区，与东部高铁网连成整体；据中国国家铁路集团有限公司2025年1月公布，2024年底全国铁路营业里程16.2万公里，其中高铁4.8万公里。",figures:["盛光祖"],place:"甘肃省、青海省、新疆维吾尔自治区",state:"中华人民共和国",sources:["中国铁路总公司2014年12月关于兰新铁路第二双线开通运营的公告及新华社报道","中国国家铁路集团有限公司2025年1月公布的2024年铁路运输统计数据"],tags:["兰新高铁","陆桥通道","高海拔铁路"]},related:["cn--2008--s02", "cn--2006--s01", "cn--2001--e02"]},
{id:"cn--2014--d01",track:"cn",year:2014,yearApprox:false,dim:"disaster",weight:3,title:"云南鲁甸发生6.5级地震",summary:"2014年8月3日16时30分发生，龙头山镇房屋大量倒塌。",detail:{background:"鲁甸县隶属云南省昭通市，位于滇东北山区，区域断裂构造发育，历史上多次发生中强地震；震中一带民房以土木、砖木结构为主，抗震能力弱。",process:"据中国地震台网测定，2014年8月3日16时30分云南省昭通市鲁甸县发生6.5级地震，震源深度约12公里。据中国地震局发布的烈度图，极震区位于龙头山镇一带，烈度达9度，云南、四川、贵州三省受灾，大量民房与学校、卫生院等建筑倒塌或受损。国务院启动国家自然灾害救助应急响应，民政部、国家减灾委派出工作组，军队与武警部队参与搜救。",impact:"据云南省政府和民政部通报，灾后实行省级领导包县、干部蹲点的工作机制，把民房恢复重建与地质灾害隐患点避让列为首要任务。据中国地震局公布，此次地震使用的烈度速报与烈度图此后成为云南、四川等省部署抗震救灾的常规依据，农村危房改造与抗震设防要求在滇东北地区继续推进。",figures:["中国地震局","云南省人民政府"],place:"云南省昭通市鲁甸县龙头山镇",state:"中华人民共和国",sources:["中国地震台网中心2014年8月3日鲁甸地震测定速报及中国地震局烈度图","民政部、国家减灾委员会办公室2014年8月关于鲁甸地震灾情的通报"],tags:["鲁甸地震","民房倒塌","烈度速报"]},related:["cn--2008--d01", "cn--2010--d01"]},
{id:"cn--2015--p01",track:"cn",year:2015,yearApprox:false,dim:"politics",weight:4,title:"中共十八届五中全会提出五大发展理念",summary:"2015年10月26日至29日召开，通过十三五规划建议并宣布全面两孩。",detail:{background:"2014年12月中央决定开展十三五规划编制工作，2015年文件起草组成立，据新华社报道起草过程中先后召开座谈会听取地方、部门、专家学者和党外人士意见。",process:"2015年10月26日至29日，中共十八届五中全会在北京举行，通过《中共中央关于制定国民经济和社会发展第十三个五年规划的建议》。建议提出创新、协调、绿色、开放、共享五大发展理念，保持经济在合理区间，到2020年国内生产总值和城乡居民人均收入比2010年翻一番，实施脱贫攻坚工程，提出现行标准下农村贫困人口实现脱贫、贫困县全部摘帽，并宣布全面实施一对夫妇可生育两个孩子政策。",impact:"2016年3月十二届全国人大四次会议批准《中华人民共和国国民经济和社会发展第十三个五年规划纲要》；2015年12月27日全国人大常委会修改人口与计划生育法，自2016年1月1日起实施全面两孩政策。生育政策此后继续调整：2021年5月中央政治局会议听取优化生育政策工作汇报，2021年8月20日全国人大常委会修改人口与计划生育法，实施三孩生育政策及配套支持措施。",figures:["习近平"],place:"北京",state:"中华人民共和国",sources:["《中共中央关于制定国民经济和社会发展第十三个五年规划的建议》（2015年10月29日通过）及新华社受权发布","新华社2015年12月27日关于全国人大常委会修改人口与计划生育法的报道","2016年3月十二届全国人大四次会议批准的十三五规划纲要"],tags:["十八届五中全会","五大发展理念","全面两孩"]},related:["cn--2014--e01", "cn--2012--p01"]},
{id:"cn--2015--e01",track:"cn",year:2015,yearApprox:false,dim:"economy",weight:4,title:"一带一路愿景与行动文件经授权发布",summary:"2013年9月与10月先后提出共建倡议，2015年3月发布愿景与行动。",detail:{background:"2013年9月，习近平在哈萨克斯坦纳扎尔巴耶夫大学演讲时提出共同建设丝绸之路经济带的设想；同年10月在印度尼西亚国会演讲提出共建21世纪海上丝绸之路。2014年11月中央财经领导小组会议研究筹建亚洲基础设施投资银行与设立丝路基金。",process:"2015年3月28日，经国务院授权，国家发展和改革委员会、外交部、商务部联合发布《推动共建丝绸之路经济带和21世纪海上丝绸之路的愿景与行动》。文件以政策沟通、设施联通、贸易畅通、资金融通、民心相通为合作重点，并明确相关省区市的定位，其中新疆被定位为丝绸之路经济带核心区、福建被定位为21世纪海上丝绸之路核心区。",impact:"据国家发展和改革委员会公布，2015年后与沿线国家的经贸与基础设施合作项目陆续实施，2017年5月14日至15日首届一带一路国际合作高峰论坛在北京举行，2019年4月和2023年10月分别举行第二届、第三届高峰论坛。据海关总署公布，2013年至2023年中国对一带一路沿线国家进出口总额的年均增速高于外贸整体增速。",figures:["习近平"],place:"北京",state:"中华人民共和国",sources:["新华社2013年9月、10月关于提出共建丝绸之路经济带和21世纪海上丝绸之路的报道","国家发展改革委、外交部、商务部2015年3月28日联合发布的《推动共建丝绸之路经济带和21世纪海上丝绸之路的愿景与行动》","新华社2023年10月关于第三届一带一路国际合作高峰论坛的报道"],tags:["一带一路","愿景与行动","五通"]},related:["cn--2001--e01", "cn--2015--e02", "cn--2014--e01"]},
{id:"cn--2015--e02",track:"cn",year:2015,yearApprox:false,dim:"economy",weight:3,title:"亚洲基础设施投资银行正式成立",summary:"2015年6月57个创始成员国签署协定，12月25日银行正式成立。",detail:{background:"2013年10月习近平在雅加达提出筹建亚洲基础设施投资银行的倡议。2014年10月24日，21个意向创始成员国在北京签署《关于筹建亚洲基础设施投资银行的备忘录》；2015年3月底申请成为意向创始成员国的期限前，英国、法国、德国、意大利等国相继申请加入。",process:"据中国财政部发布，2015年5月意向创始成员国增至57个；2015年6月29日，57个创始成员国代表在北京签署《亚洲基础设施投资银行协定》，新华社同日受权发布协定文本。2015年12月25日亚洲基础设施投资银行正式成立，法定资本金1000亿美元，金立群当选首任行长。",impact:"据亚投行公布的年度信息，其成员数量在2016年至2023年间增至100个以上，投资范围覆盖亚洲及其他地区的发展中成员，项目涉及交通、能源、供水与城市基础设施。银行与亚洲开发银行、世界银行开展联合融资。同期2015年11月30日国际货币基金组织宣布将人民币纳入特别提款权货币篮子，自2016年10月1日生效。",figures:["金立群"],place:"北京",state:"中华人民共和国",sources:["中国财政部2015年6月29日关于创始成员国签署《亚洲基础设施投资银行协定》的公告及新华社报道","新华社2015年12月关于亚投行正式成立的报道","亚洲基础设施投资银行历年年报公布的成员与项目情况"],tags:["亚投行","基础设施投资","多边金融"]},related:["cn--2015--e01", "cn--2001--e01"]},
{id:"cn--2015--m01",track:"cn",year:2015,yearApprox:false,dim:"military",weight:3,title:"抗战胜利70周年阅兵宣布裁军三十万",summary:"2015年9月3日北京举行阅兵式，宣布裁减军队员额30万。",detail:{background:"2014年2月全国人大常委会通过决定，将9月3日确定为中国人民抗日战争胜利纪念日。2015年为中国人民抗日战争暨世界反法西斯战争胜利70周年。",process:"2015年9月3日，纪念中国人民抗日战争暨世界反法西斯战争胜利70周年大会和阅兵仪式在北京举行。据新华社报道，部分国家军队派出方队或代表参加阅兵，受阅装备为国产现役主战装备。习近平在仪式上宣布中国将裁减军队员额30万。",impact:"据新华社2017年报道，宣布的裁减军队员额30万到2017年底基本完成，军队总员额由250万减至200万以下。同期领导指挥体制改革推进：2015年12月31日成立陆军领导机构，第二炮兵部队更名为火箭军并组建战略支援部队；2016年2月1日东部、南部、西部、北部、中部五大战区成立，原七大军区调整撤销。",figures:["习近平"],place:"北京",state:"中华人民共和国",sources:["新华社2015年9月3日关于纪念中国人民抗日战争暨世界反法西斯战争胜利70周年大会及阅兵式的报道","新华社2016年2月关于战区成立大会的报道","新华社2017年关于深化国防和军队改革进展的报道"],tags:["抗战胜利70周年","阅兵","裁军30万"]},related:["cn--2014--i02", "cn--1985--p01", "cn--2009--p01"]},
{id:"cn--2015--s01",track:"cn",year:2015,yearApprox:false,dim:"science",weight:3,title:"屠呦呦获诺贝尔生理学或医学奖",summary:"2015年10月因发现青蒿素获奖，为中国本土科学家首次获该奖。",detail:{background:"20世纪60年代，抗疟药物研究被列入国家科研项目，中医研究院中药研究所承担相关任务，屠呦呦任课题组组长。她在东晋葛洪《肘后备急方》关于青蒿治疟的记载中获得低温提取的线索。",process:"屠呦呦1930年生于浙江宁波，1950年代毕业于北京医学院药学系后在中医研究院工作。据中国中医科学院公布，其课题组1972年分离得到青蒿素结晶，其后确认抗疟疗效并应用于临床。2011年9月屠呦呦获拉斯克临床医学研究奖；2015年10月5日卡罗琳斯卡学院宣布将2015年诺贝尔生理学或医学奖授予屠呦呦、威廉·坎贝尔与大村智，屠呦呦的授奖理由为有关疟疾新疗法的发现。",impact:"据世界卫生组织与国家卫生健康部门公布，以青蒿素为基础的联合疗法成为全球疟疾治疗的一线方案。中国本土疟疾病例此后持续下降，世界卫生组织2021年6月宣布中国获得消除疟疾认证。据科技部公布，屠呦呦获2016年度国家最高科学技术奖；2019年9月全国人大常委会决定授予她共和国勋章。",figures:["屠呦呦"],place:"浙江宁波及北京",state:"中华人民共和国",sources:["卡罗琳斯卡学院2015年10月5日关于诺贝尔生理学或医学奖的授奖公告","新华社2015年10月6日关于屠呦呦获奖的报道","世界卫生组织2021年6月关于中国消除疟疾认证的公开信息"],tags:["青蒿素","诺贝尔奖","疟疾治疗"]},related:["cn--1986--s01", "cn--2012--c01"]},
{id:"cn--2015--d01",track:"cn",year:2015,yearApprox:false,dim:"disaster",weight:3,title:"天津港发生8·12特别重大火灾爆炸事故",summary:"2015年8月12日危险品仓库起火爆炸，调查组认定责任事故。",detail:{background:"天津港瑞海国际物流有限公司的危险品集装箱堆场与仓库位于滨海新区，邻近居住与公共设施。调查报告认定该企业长期存在超量储存、违规堆放硝酸铵等危险货物的情形。",process:"2015年8月12日22时51分仓库起火，23时34分左右发生两次剧烈爆炸，消防与民警到场处置。据国务院调查组2016年11月公布的调查报告，事故造成165人遇难、8人失踪，其中包含消防救援人员与民警；报告认定这是一起特别重大生产安全责任事故，指出企业违法经营、相关地方党委政府和部门存在监管失职渎职，并移交司法机关处理一批责任人员。",impact:"事故后全国开展危险化学品与危险货物运输、仓储安全专项整治。据天津市政府公布，受损住宅、学校等设施完成修复与加固，周边居民实施安置。制度层面，2016年12月中共中央、国务院印发《关于推进安全生产领域改革发展的意见》，提出党政同责、一岗双责与企业全员安全生产责任制；《安全生产法》2021年6月10日再次修改，加重对主要负责人与地方监管责任的追究。",figures:["国务院事故调查组","天津市人民政府"],place:"天津市滨海新区天津港",state:"中华人民共和国",sources:["国务院天津港瑞海公司危险品仓库特别重大火灾爆炸事故调查组2016年11月公布的调查报告及新华社报道","中共中央、国务院2016年12月印发的《关于推进安全生产领域改革发展的意见》","全国人大常委会2021年6月10日关于修改安全生产法的决定"],tags:["天津港","火灾爆炸","安全生产"]},related:["cn--2010--d01", "cn--2012--d01"]},
{id:"cn--2016--i01",track:"cn",year:2016,yearApprox:false,dim:"institution",weight:4,title:"国家监察体制改革试点在北京山西浙江启动",summary:"2016年12月25日人大常委会授权在三省市试点，组建监察委员会。",detail:{background:"2016年10月，据新华社报道，中共中央办公厅印发《关于在北京市、山西省、浙江省开展国家监察体制改革试点方案》，决定在三省市各级组建监察委员会，整合行政监察、预防腐败和检察机关查处贪污贿赂、失职渎职及侵犯公民人身权利、民主权利等职务犯罪职能。",process:"2016年12月25日，十二届全国人大常委会第二十五次会议通过《关于在北京市、山西省、浙江省开展国家监察体制改革试点工作的决定》，自2017年1月1日起施行。决定规定在试点地区省市县三级设立监察委员会，由本级人民代表大会产生，对本级人大及其常委会和上一级监察委员会负责；监察委员会按管理权限履行监督、调查、处置职责，可采取谈话、询、留置等调查措施；试点地区检察机关相关职务犯罪侦查职能转隶至监察委员会，并暂时调整适用行政监察法等法律规定。据该决定的说明，留置措施取代了此前党的纪律审查中使用的“两规”措施。",impact:"2017年1月，北京市、山西省、浙江省各级监察委员会相继选举产生并完成组建，与同级党的纪律检查机关合署办公。据中央纪委国家监委机关公布的信息，2018年2月全国省、市、县三级监察委员会全部组建完成。2018年3月11日十三届全国人大一次会议通过宪法修正案，在第三章国家机构中增写监察委员会一节；3月20日会议通过《中华人民共和国监察法》，试点做法被上升为法律制度。",figures:["北京市监察委员会","山西省监察委员会","浙江省监察委员会"],place:"北京、山西、浙江",state:"中华人民共和国",sources:["新华社2016年10月关于中共中央办公厅印发国家监察体制改革试点方案的报道","全国人大常委会2016年12月25日《关于在北京市、山西省、浙江省开展国家监察体制改革试点工作的决定》","新华社2018年3月20日关于十三届全国人大一次会议通过监察法的报道"],tags:["国家监察体制改革","监察委员会","留置"]},related:["cn--2014--p01", "cn--1998--i02", "cn--2012--p01"]},
{id:"cn--2016--i02",track:"cn",year:2016,yearApprox:false,dim:"institution",weight:3,title:"中华人民共和国慈善法获通过并施行",summary:"2016年3月16日全国人大通过，9月1日施行，系慈善领域首部法律。",detail:{background:"2011年“郭美美事件”后，慈善组织公信力与监管问题持续受到关注。2014年国务院印发《关于促进慈善事业健康发展的指导意见》。慈善法草案经2015年10月十二届全国人大常委会第十七次会议初次审议、同年12月二次审议后，常委会决定提请2016年3月召开的十二届全国人大四次会议审议。",process:"2016年3月16日，十二届全国人大四次会议通过《中华人民共和国慈善法》，自2016年9月1日起施行。该法规定慈善组织面向社会公众开展公开募捐应当取得公开募捐资格，依法登记满二年的慈善组织可以申请该资格；明确个人不得面向社会公众发起募捐，为帮助特定对象的求助人可以通过具有公开募捐资格的慈善组织发布募款信息；规定慈善信托的设立与备案、慈善财产的用途与信息公开要求，要求慈善组织逐年公开年度工作报告和财务会计报告，并禁止私分、挪用、截留或者侵占慈善财产。据民政部2016年8月公告，该部公布首批共13家互联网公开募捐信息平台。",impact:"据民政部公布，该法施行后慈善组织的登记认定、公开募捐资格与信息公开按统一规则管理。2023年12月29日十四届全国人大常委会第七次会议对慈善法作出修订，自2024年9月起施行，增设应急慈善条款，并细化网络募捐规范与监管措施。",figures:["民政部"],place:"北京",state:"中华人民共和国",sources:["新华社2016年3月16日关于十二届全国人大四次会议通过慈善法的报道","民政部2016年8月关于首批互联网公开募捐信息平台名单的公告","新华社2023年12月29日关于十四届全国人大常委会第七次会议修订慈善法的报道"],tags:["慈善法","公开募捐","慈善信托"]},related:["cn--2016--i01", "cn--2014--p01"]},
{id:"cn--2016--e01",track:"cn",year:2016,yearApprox:false,dim:"economy",weight:3,title:"供给侧结构性改革启动钢铁煤炭去产能",summary:"2016年国务院发文压减钢铁煤炭过剩产能，年度任务超额完成。",detail:{background:"2015年11月，据新华社报道，中央财经领导小组第十一次会议提出供给侧结构性改革；同年12月中央经济工作会议把去产能、去库存、去杠杆、降成本、补短板列为2016年经济工作重点任务。钢铁、煤炭等行业产能过剩和企业亏损问题在此前数年已集中显现。",process:"2016年2月，国务院发布《关于煤炭行业化解过剩产能实现脱困发展的意见》，提出从当年起用3至5年时间再压减煤炭产能5亿吨左右、淘汰其他煤炭产能5亿吨左右；同年5月国务院发布《关于钢铁行业化解过剩产能实现脱困发展的意见》，提出用5年时间压减粗钢产能1亿至1.5亿吨，并严禁新增产能、依法依规淘汰落后和“僵尸企业”。同年国务院办公厅印发《关于促进建材工业稳增长调结构增效益的指导意见》，把玻璃、水泥等纳入压减范围。据国家发展改革委2017年1月新闻发布会通报，2016年全国退出煤炭产能2.9亿吨、压减粗钢产能4500万吨以上，超额完成年度任务。",impact:"据工业和信息化部2017年通报，2017年6月底违规建设使用的“地条钢”产能被全面取缔出清。去产能与环保、安全执法叠加后，煤炭、钢铁价格与企业利润在2016至2017年回升；2018年后政策转向巩固去产能成果与兼并重组。2020年9月中国提出碳达峰、碳中和目标后，粗钢产量纳入产量压减安排，据国家统计局发布的数据，2021年粗钢产量比上年下降。",figures:["国务院","国家发展改革委"],place:"河北、山西、内蒙古等产能集中地区",state:"中华人民共和国",sources:["国务院2016年2月《关于煤炭行业化解过剩产能实现脱困发展的意见》","国务院2016年5月《关于钢铁行业化解过剩产能实现脱困发展的意见》","国家发展改革委2017年1月关于钢铁煤炭行业化解过剩产能工作进展的新闻发布会记录"],tags:["供给侧结构性改革","去产能","三去一降一补"]},related:["cn--1998--e02", "cn--2014--e01", "cn--2015--p01"]},
{id:"cn--2016--e02",track:"cn",year:2016,yearApprox:false,dim:"economy",weight:3,title:"人民币加入SDR货币篮子并正式生效",summary:"2015年IMF审查决定纳入人民币，2016年10月1日生效，权重10.92%。",detail:{background:"特别提款权是国际货币基金组织创设的记账单位与储备资产补充，其货币篮子约每五年审查一次。据IMF介绍，篮子货币须满足两项标准：代表货物和服务出口规模最大的经济体，且在主要国际贸易支付中被广泛使用；上一轮2010年审查未纳入人民币。",process:"2015年10月30日，国际货币基金组织总裁拉加德宣布，IMF在完成2015年SDR定值审查后决定将人民币纳入SDR货币篮子；同年11月30日拉加德在美国华盛顿就该决定公开说明。据IMF公布的新权重，篮子为美元41.73%、欧元30.93%、人民币10.92%、日元8.33%、英镑8.09%，自2016年10月1日起生效。",impact:"据中国外汇交易中心2015年12月发布的信息，该中心自当月起编制并发布参考特别提款权货币篮子的人民币汇率指数。IMF于2022年7月完成下一轮审查，据其公告人民币权重由10.92%上调至12.28%，自2022年8月1日起生效。据中国人民银行历年《人民币国际化报告》及市场机构的月度统计，入篮后人民币在跨境收付、融资与官方储备中的使用总体扩大，同时占比随汇率与资本流动波动。",figures:["周小川","拉加德"],place:"美国华盛顿",state:"中华人民共和国",sources:["国际货币基金组织2015年11月关于SDR定值审查及纳入人民币的公告","国际货币基金组织2022年7月关于完成SDR定值审查的公告","中国人民银行历年《人民币国际化报告》"],tags:["SDR","人民币国际化","货币篮子"]},related:["cn--2001--e01", "cn--2005--e01", "cn--1994--e02"]},
{id:"cn--2016--s01",track:"cn",year:2016,yearApprox:false,dim:"science",weight:3,title:"天宫二号与神舟十一号完成交会对接",summary:"2016年10月19日两器对接，两名航天员在轨驻留30天。",detail:{background:"天宫二号空间实验室由长征二号F运载火箭在酒泉卫星发射中心发射，是中国首个目标飞行器和空间实验室天宫一号的改进型；神舟十一号为载人飞船任务，按计划与天宫二号自动交会对接并开展中期驻留。",process:"2016年9月15日天宫二号发射入轨，并在轨与后续飞船、地面应用系统联试；10月17日神舟十一号载人飞船发射，航天员景海鹏、陈冬进入飞船，10月19日两器完成自动交会对接，航天员随后进入天宫二号工作。两名航天员在组合体中驻留约30天，在轨开展空间应用与航天医学试验，其中包括空间冷原子钟等装置；2016年11月18日神舟十一号返回舱在内蒙古中部预定区域成功着陆。",impact:"据中国载人航天工程办公室公布，此次任务是中国载人航天工程空间实验室阶段的收官之战，验证了中期驻留、环控生保与在轨维护等关键技术。2017年4月天舟一号货运飞船与天宫二号对接，同年6月完成首次推进剂在轨补加试验；2019年7月天宫二号受控离轨再入大气层，其搭载的空间应用系统数据转入后续空间站任务使用。",figures:["景海鹏","陈冬"],place:"酒泉卫星发射中心及内蒙古中部着陆场",state:"中华人民共和国",sources:["中国载人航天工程办公室2016年9月至11月关于天宫二号与神舟十一号任务情况的发布","新华社2016年11月18日关于神舟十一号载人飞船返回着陆的报道","中国载人航天工程办公室2017年6月关于天舟一号推进剂在轨补加试验结果的发布"],tags:["天宫二号","神舟十一号","空间实验室"]},related:["cn--2011--s01", "cn--2012--s01", "cn--2003--s01"]},
{id:"cn--2016--s02",track:"cn",year:2016,yearApprox:false,dim:"science",weight:4,title:"500米口径球面射电望远镜在贵州落成启用",summary:"2016年9月25日启用，反射面约25万平方米，2017年发现新脉冲星。",detail:{background:"该项目利用贵州平塘的喀斯特天然洼地建设，1994年由天文学家南仁东提出设想并主持选址与预研究，此后长期开展工程攻关；2011年3月正式开工，由中国科学院国家天文台承建。",process:"2016年9月25日，500米口径球面射电望远镜（FAST）在贵州落成启用。据中国科学院介绍，其反射面总面积约25万平方米，由约4450个反射面单元组成，采用主动反射面形态与轻型绳索馈源支撑结构，口径居世界单口径射电望远镜之首，主要用于中性氢观测、脉冲星搜索、星际分子研究与快速射电暴等观测方向。",impact:"2017年10月，中国科学院国家天文台公布FAST发现两颗新脉冲星，这是该设备首次发现新脉冲星。2021年3月31日起FAST正式面向全球天文学家开放运行并接受观测申请。工程首席科学家兼总工程师南仁东于2017年9月15日因病逝世，2019年9月被授予“人民科学家”国家荣誉称号。据国家天文台此后公布，FAST在多频段发现大批新脉冲星并参与快速射电暴起源研究。",figures:["南仁东"],place:"贵州平塘",state:"中华人民共和国",sources:["中国科学院2016年9月25日关于500米口径球面射电望远镜落成启用的发布及新华社报道","中国科学院国家天文台2017年10月关于FAST发现新脉冲星的发布","国家天文台2021年3月关于FAST面向全球开放运行的公告"],tags:["射电望远镜","脉冲星","大科学装置"]},related:["cn--1995--s01", "cn--2013--s01"]},
{id:"cn--2016--c01",track:"cn",year:2016,yearApprox:false,dim:"culture",weight:3,title:"二十四节气列入人类非遗代表作名录",summary:"2016年11月30日联合国教科文组织常会通过审议，中国申报入选。",detail:{background:"二十四节气按太阳在黄道上的位置划分，反映时令、气候与物候变化，用于指导农事和日常生活；其名称完整见于西汉《淮南子·天文训》，汉武帝时期制定的历法将节气订入历书。中国于2004年加入联合国教科文组织《保护非物质文化遗产公约》。",process:"2016年11月30日，联合国教科文组织保护非物质文化遗产政府间委员会第十一届常会在埃塞俄比亚亚的斯亚贝巴审议并通过，将中国申报的“二十四节气——中国人通过观察太阳周年运动而形成的时间知识体系及其实践”列入人类非物质文化遗产代表作名录。申报文本由相关农业、天文与非遗保护机构联合编制，据申报材料，河南、内蒙古等地的节气民俗与农事实践是其中的传承实例。",impact:"列入名录后，节气相关知识体系的记录、传承与展示被纳入非遗保护与农业文化遗产保护工作；2017年1月，中共中央办公厅、国务院办公厅印发《关于实施中华优秀传统文化传承发展工程的意见》，把传统节日与民俗的保护传播列入重点任务，该意见同时提出实施中国传统节日振兴工程。据文化和旅游部组建后公布的非物质文化遗产保护工作信息，节气类民俗与农事实践被纳入传统节日宣传普及与非遗传播活动的范围。",figures:["联合国教科文组织保护非物质文化遗产政府间委员会"],place:"北京及法国巴黎",state:"中华人民共和国",sources:["联合国教科文组织2016年11月30日关于新增人类非物质文化遗产代表作名录项目的公告及新华社报道","联合国教科文组织保护非物质文化遗产公约缔约国大会相关会议文件","中共中央办公厅、国务院办公厅2017年1月印发的《关于实施中华优秀传统文化传承发展工程的意见》"],tags:["二十四节气","非物质文化遗产","时间知识体系"]},related:["cn--2001--c01", "cn--2006--c01"]},
{id:"cn--2017--p01",track:"cn",year:2017,yearApprox:false,dim:"politics",weight:5,title:"中国共产党第十九次全国代表大会召开",summary:"2017年10月18日至24日召开，习近平新时代中国特色社会主义思想写入党章。",detail:{background:"2012年中共十八大提出两个一百年奋斗目标，2017年召开十九大。据新华社2017年9月发布的党内统计公报，截至2016年12月31日中国共产党党员总数为8944.7万名。",process:"2017年10月18日至24日，中国共产党第十九次全国代表大会在北京举行。大会通过关于十八届中央委员会报告的决议，作出中国特色社会主义进入新时代、我国社会主要矛盾已经转化为人民日益增长的美好生活需要和不平衡不充分的发展之间的重大判断，并提出从2020年到2035年基本实现社会主义现代化、从2035年到本世纪中叶把我国建成富强民主文明和谐美丽的社会主义现代化强国的两步安排。10月24日大会通过《中国共产党章程（修正案）》，把习近平新时代中国特色社会主义思想确立为党的指导思想并同马克思列宁主义、毛泽东思想、邓小平理论、“三个代表”重要思想、科学发展观一道作为行动指南。10月25日十九届一中全会选举习近平为中央委员会总书记和中央军事委员会主席，选举产生由7人组成的中央政治局常务委员会；同日十九届中央纪委一次全会选举赵乐际为中央纪律检查委员会书记。",impact:"2018年3月，十三届全国人大一次会议选举习近平为中华人民共和国主席、栗战书为全国人大常委会委员长，根据国家主席提名决定李克强为国务院总理；会议通过第五个宪法修正案，把科学发展观和习近平新时代中国特色社会主义思想写入宪法序言，增设监察委员会一节，并删除国家主席、副主席连续任职不得超过两届的规定。深化党和国家机构改革按2018年2月十九届三中全会审议通过的方案推进。2022年10月二十大提出以中国式现代化全面推进中华民族伟大复兴，并确认2020年完成脱贫攻坚、全面建成小康社会。",figures:["习近平","李克强","栗战书","赵乐际"],place:"北京",state:"中华人民共和国",sources:["新华社2017年10月18日至24日关于中国共产党第十九次全国代表大会的报道","《中国共产党章程（修正案）》（2017年10月24日通过）及新华社受权发布","新华社2017年9月关于中国共产党党内统计情况的公报"],tags:["中共十九大","习近平新时代中国特色社会主义思想","两步走"]},related:["cn--2012--p01", "cn--2007--p01", "cn--1997--p02"]},
{id:"cn--2017--i01",track:"cn",year:2017,yearApprox:false,dim:"institution",weight:4,title:"民法总则通过并自2017年10月施行",summary:"2017年3月15日全国人大通过，是民法典编纂的首步成果。",detail:{background:"2014年中共十八届四中全会提出编纂民法典。据全国人大常委会法制工作委员会的介绍，编纂工作采取“两步走”思路：第一步制定作为民法典总则编的民法总则，第二步整合修订各分编后与总则合并为一部民法典。民法总则草案于2016年6月经全国人大常委会初次审议，同年12月再次审议后决定提请2017年3月的大会审议。",process:"2017年3月15日，十二届全国人大五次会议通过《中华人民共和国民法总则》，自2017年10月1日起施行。该法共11章206条，规定民事活动的基本原则，将法人分为营利法人、非营利法人与特别法人，把限制民事行为能力未成年人的年龄下限由十周岁下调至八周岁，明确胎儿在继承、接受赠予等情形中的利益保护，将一般诉讼时效期间由二年延长为三年，规定个人信息受法律保护以及法律对数据、网络虚拟财产的保护，并设立因自愿实施紧急救助行为造成受助人损害的免责条款。",impact:"该法施行后，民事基本规则与2017年前分散的民事单行法并行适用。2020年5月28日十三届全国人大三次会议通过《中华人民共和国民法典》，自2021年1月1日起施行，共7编1260条，同时废止婚姻法、继承法、民法通则、收养法、担保法、合同法、物权法、侵权责任法与民法总则9部法律，是新中国成立以来第一部以“法典”命名的法律。",figures:["张德江"],place:"北京",state:"中华人民共和国",sources:["新华社2017年3月15日关于十二届全国人大五次会议通过民法总则的报道及法律文本","全国人大常委会法制工作委员会2016年6月关于民法总则草案说明的公开报道","新华社2020年5月28日关于十三届全国人大三次会议通过民法典的报道"],tags:["民法总则","民法典","诉讼时效"]},related:["cn--2014--p01", "cn--2007--i01", "cn--2020--i01"]},
{id:"cn--2017--i02",track:"cn",year:2017,yearApprox:false,dim:"institution",weight:3,title:"网络安全法自2017年6月1日施行",summary:"2016年11月7日人大常委会通过，确立网络运营者与关键设施义务。",detail:{background:"此前网络与信息安全领域的规则主要由《全国人民代表大会常务委员会关于维护互联网安全的决定》、2011年《全国人大常委会关于加强网络信息保护的决定》及行政法规、部门规章构成。2014年2月中央网络安全和信息化领导小组成立，2018年3月改为中央网络安全和信息化委员会；2015年底全国人大常委会对网络安全法草案进行初次审议。",process:"2016年11月7日，十二届全国人大常委会第二十四次会议通过《中华人民共和国网络安全法》，自2017年6月1日起施行。该法规定网络运营者收集使用个人信息应遵循合法、正当、必要原则并经被收集者同意，实行网络安全等级保护制度，用户在办理网络接入、信息发布等服务时需提供真实身份信息；对关键信息基础设施实行重点保护，其运营者在中国境内收集的个人信息和重要数据应当在境内存储，因业务需要向境外提供的按国家规定进行安全评估；并禁止设立用于实施诈骗、传授犯罪方法、制作或销售违禁物品等活动的网络平台和通信群组。",impact:"该法施行前后配套规则陆续出台：2017年5月国家网信办等部门印发《网络产品和服务安全审查办法（试行）》，与法律同日施行；此后又出台网络信息内容生态治理、算法推荐管理等规定。2021年6月10日全国人大常委会通过数据安全法（自2021年9月1日施行），同年8月20日通过个人信息保护法（自2021年11月1日施行）；国家网信办2022年7月公布《数据出境安全评估办法》，自2022年9月1日施行，与网络安全法共同构成数据与网络领域的基础制度框架。",figures:["全国人大常委会"],place:"北京",state:"中华人民共和国",sources:["新华社2016年11月7日关于十二届全国人大常委会第二十四次会议通过网络安全法的报道及法律文本","国家网信办等部门2017年5月发布的《网络产品和服务安全审查办法（试行）》","新华社2021年8月20日关于十三届全国人大常委会第三十一次会议通过个人信息保护法的报道"],tags:["网络安全法","关键信息基础设施","个人信息保护"]},related:["cn--2000--i02", "cn--1994--s01"]},
{id:"cn--2017--e01",track:"cn",year:2017,yearApprox:false,dim:"economy",weight:3,title:"第五次全国金融工作会议决定设立金融委",summary:"2017年7月14日至15日召开，会后设立国务院金融稳定发展委员会。",detail:{background:"全国金融工作会议此前分别于1997年、2002年、2007年、2012年召开四次。2016年12月的中央经济工作会议提出把防控金融风险放到更加重要的位置，着力防控资产泡沫。",process:"2017年7月14日至15日，第五次全国金融工作会议在北京举行。会议提出服务实体经济、防控金融风险、深化金融改革三项任务，并决定设立国务院金融稳定发展委员会，强化人民银行宏观审慎管理和系统性风险防范职责；会议同时要求把发展直接融资放在重要位置，推动金融机构完善治理、专注主业，并把国有企业去杠杆作为重点。2017年11月，据新华社报道，国务院正式批复设立国务院金融稳定发展委员会，办公室设在中国人民银行。",impact:"2018年3月十三届全国人大一次会议批准国务院机构改革方案，组建中国银行保险监督管理委员会，不再保留银监会、保监会，并将银行业、保险业重要法律法规草案的制定职责划入人民银行。据国家统计局2018年1月发布的初步核算数据，2017年国内生产总值迈上80万亿元台阶，按可比价格计算比上年增长6.9%，为2012年以来年度增速首次回升。2018年4月人民银行、银保监会、证监会与外汇局联合发布关于规范金融机构资产管理业务的指导意见；2023年3月《党和国家机构改革方案》决定组建国家金融监督管理总局、不再保留银保监会，并设立中央金融委员会与中央金融工作委员会。",figures:["国务院金融稳定发展委员会"],place:"北京",state:"中华人民共和国",sources:["新华社2017年7月15日关于全国金融工作会议在北京举行的报道","新华社2017年11月关于国务院批复设立国务院金融稳定发展委员会的报道","国家统计局2018年1月发布的2017年国民经济运行情况数据"],tags:["全国金融工作会议","金融监管","防范金融风险"]},related:["cn--1997--e01", "cn--2012--e01", "cn--2016--e01"]},
{id:"cn--2017--s01",track:"cn",year:2017,yearApprox:false,dim:"science",weight:3,title:"国产大型客机C919首飞成功",summary:"2017年5月5日在上海浦东国际机场完成首次飞行。",detail:{background:"2006年1月国务院发布《国家中长期科学和技术发展规划纲要（2006—2020年）》，把大型飞机列入16个科技重大专项；2008年5月中国商用飞机有限责任公司在上海成立。据中国商飞介绍，C919为窄体干线客机，座级158至168座、航程4075至5555公里；2015年11月2日首架机总装下线。",process:"2017年5月5日，C919大型客机101架机从上海浦东国际机场起飞，完成预定首次飞行科目后安全降落，首飞成功。据中国商飞公布，首飞后交付多架试飞机，在上海、西安等地开展气象、颤振、极限载荷与结冰等试飞科目，同时全国多家企业和科研机构参与机体结构、航电与动力系统的研制和配套。",impact:"据中国民用航空局2021年11月发布的消息，C919获得型号合格证；据中国东方航空股份有限公司公布，2022年12月首架C919交付，2023年5月完成商业首航。此前另一款支线客机ARJ21已按中国商飞2016年6月公布的信息投入商业运营。此后国产大飞机进入批产交付与运营维护阶段，其发动机、航电等系统的国产化与供应链安排成为行业持续关注的议题。",figures:["C919首飞机组","中国商用飞机有限责任公司"],place:"上海浦东国际机场",state:"中华人民共和国",sources:["中国商用飞机有限责任公司2017年5月5日关于C919大型客机首飞成功的发布及新华社报道","中国民用航空局2021年11月关于颁发C919型号合格证的公告","中国东方航空股份有限公司2022年12月关于首架C919交付机接收的公告"],tags:["C919","大型客机","首飞"]},related:["cn--2006--p01", "cn--1995--s01"]},
{id:"cn--2017--m01",track:"cn",year:2017,yearApprox:false,dim:"military",weight:3,title:"庆祝建军90周年阅兵在朱日和举行",summary:"2017年7月30日在朱日和训练基地举行，按作战单元编组方队。",detail:{background:"1927年8月1日的南昌起义被作为中国工农红军诞生日，8月1日为中国人民解放军建军节。2015年9月3日纪念抗战胜利70周年阅兵后，裁减军队员额30万和领导指挥体制改革同步推进，2016年1月中央军委机关由原四总部调整组建为15个职能部门，同年2月1日五大战区成立。",process:"2017年7月30日，庆祝中国人民解放军建军90周年阅兵在朱日和训练基地举行。据新华社报道，此次阅兵是人民军队首次以庆祝建军节为主题的集中阅兵，受阅部队按作战单元编组为45个方（梯）队，地面装备580余台（套）、各型飞机120余架，多数为国产现役主战装备；演练背景下的沙场阅兵不设红毯与观礼台，受阅部队着装与装备按实战化要求配置。",impact:"据新华社2017年报道，此次阅兵在深化国防和军队改革进程中举行，受阅部队编成体现改革后的新体制。2017年8月1日中国人民解放军建军90周年大会在北京举行。此后军队编制体制与装备序列继续调整：2019年10月1日庆祝中华人民共和国成立70周年阅兵在北京举行，受阅装备均为国产现役主战装备并包括新型洲际弹道导弹、无人作战装备等方队；2022年党的二十大报告提出到2027年实现建军一百年奋斗目标。",figures:["习近平"],place:"内蒙古朱日和训练基地",state:"中华人民共和国",sources:["新华社2017年7月30日关于庆祝中国人民解放军建军90周年阅兵在朱日和训练基地举行的报道","新华社2017年8月1日关于纪念中国人民解放军建军90周年大会的报道","新华社2019年10月1日关于庆祝中华人民共和国成立70周年阅兵式的报道"],tags:["朱日和阅兵","建军90周年","实战化训练"]},related:["cn--2015--m01", "cn--2012--m01", "cn--2009--p01"]},
{id:"cn--2018--p01",track:"cn",year:2018,yearApprox:false,dim:"politics",weight:4,title:"2018年宪法修正案通过",summary:"3月11日全国人大通过第五次修正，增设监察委员会一节。",detail:{background:"2017年10月中共十九大把习近平新时代中国特色社会主义思想确立为党的指导思想。2018年1月18日至19日，中共十九届二中全会审议通过《中共中央关于修改宪法部分内容的建议》，并决定向全国人大提出宪法修改议案。",process:"2018年3月11日，十三届全国人大一次会议通过《中华人民共和国宪法修正案》，为1982年宪法的第五次修正。修正案把科学发展观与习近平新时代中国特色社会主义思想写入宪法序言，增写中国共产党领导是中国特色社会主义最本质的特征，将健全社会主义法制表述改为健全社会主义法治，在第三章国家机构中增写监察委员会一节，确立监察机关由人民代表大会产生、依法独立行使监察权的宪法依据，并删除宪法第七十九条中国家主席、副主席连续任职不得超过两届的规定；同时调整设区的市地方立法、全国人大宪法和法律委员会等内容。",impact:"2018年3月20日十三届全国人大一次会议通过《中华人民共和国监察法》，3月23日国家监察委员会挂牌，与中央纪委合署办公。2018年3月17日会议选举和决定任命的国家机构领导人员随后进行宪法宣誓，宪法宣誓制度在全国人大会议程序中常态化。2018年、2023年两届全国人大一次会议按修改后的宪法规定完成国家机构换届。",figures:["王晨"],place:"北京",state:"中华人民共和国",sources:["十三届全国人大一次会议2018年3月11日通过的《中华人民共和国宪法修正案》及新华社受权发布","新华社2018年1月19日关于中共十九届二中全会审议通过修改宪法建议的报道","新华社2018年3月23日关于国家监察委员会挂牌的报道"],tags:["2018年宪法修正案","监察委员会","国家主席"]},related:["cn--2016--i01", "cn--1982--i01", "cn--2004--i01"]},
{id:"cn--2018--i01",track:"cn",year:2018,yearApprox:false,dim:"institution",weight:3,title:"深化党和国家机构改革方案获批",summary:"2018年3月全国人大批准，国务院组成部门大幅调整重组。",detail:{background:"2018年2月26日至28日，中共十九届三中全会审议通过《中共中央关于深化党和国家机构改革的决定》和《深化党和国家机构改革方案》，同意把方案的部分内容按法定程序提交十三届全国人大一次会议审议。",process:"2018年3月17日，十三届全国人大一次会议批准国务院机构改革方案。方案组建自然资源部、生态环境部、农业农村部、文化和旅游部、国家卫生健康委员会、退役军人事务部、应急管理部，重新组建科学技术部，组建国家市场监督管理总局和中国银行保险监督管理委员会，不再保留国土资源部、环境保护部、农业部、文化部、国家旅游局、国家卫生和计划生育委员会、银监会、保监会等机构。会议同时选举产生国家监察委员会，组建国家、省、市、县四级监察机关体系。",impact:"据中共中央印发的《深化党和国家机构改革方案》，本轮改革除国务院机构外还涉及党中央机构、全国性法定机构与跨军地机构调整。税务系统同期完成国税地税征管体制改革，2018年6月起省级和省级以下国税地税机构合并，并自2019年1月1日起将各项社会保险费交由税务部门统一征收。2023年3月《党和国家机构改革方案》在此基础上进一步组建国家金融监督管理总局、国家数据局，重新组建科学技术部，并在中央层面设立中央金融委员会与中央社会工作部。",figures:["杨晓超"],place:"北京",state:"中华人民共和国",sources:["十三届全国人大一次会议2018年3月17日关于批准国务院机构改革方案的决定","中共中央2018年2月印发的《深化党和国家机构改革方案》及新华社受权发布","中共中央办公厅、国务院办公厅2018年7月印发的《国税地税征管体制改革方案》"],tags:["党和国家机构改革","国务院机构","监察委员会"]},related:["cn--2018--p01", "cn--1998--i02", "cn--2013--i01"]},
{id:"cn--2018--e01",track:"cn",year:2018,yearApprox:false,dim:"economy",weight:3,title:"中美经贸摩擦升级双方互加关税",summary:"2018年7月6日美方首批关税生效，中方同日对等反制。",detail:{background:"2017年8月美国贸易代表办公室依据《1974年贸易法》第301条对中国启动调查。据新华社2018年3月报道，美方于2018年3月22日签署总统备忘录，以该调查结论为依据拟对中国输美商品采取加征关税等措施，同年4月美方公布拟加征关税的商品清单。",process:"2018年6月15日美方公布对500亿美元中国商品加征25%关税的清单，其中340亿美元于7月6日生效。据国务院关税税则委员会2018年6月公告及7月6日发布的消息，中方对原产于美国的农产品、汽车、水产品等约545个税目、340亿美元商品加征25%关税，同日生效。2018年9月24日美方对2000亿美元中国输美商品加征10%关税生效，中方对约600亿美元美国商品加征5%至10%关税；同年12月1日两国领导人会晤后双方同意停止加征新的关税，并启动经贸磋商。",impact:"磋商进程此后反复：据新华社2019年5月报道，美方于2019年5月10日将2000亿美元中国商品的加征税率提高至25%；2020年1月15日中美在华盛顿签署第一阶段经贸协议。据海关总署2019年1月发布，2018年我国货物贸易进出口总额30.51万亿元人民币，创历史新高。关税与出口管制叠加后，部分外向型制造业产能向东南亚转移，2022年10月美国商务部进一步出台针对先进计算与半导体制造设备的对华出口管制措施。",figures:["国务院关税税则委员会","商务部"],place:"北京与华盛顿",state:"中华人民共和国",sources:["国务院关税税则委员会2018年6月、7月关于对原产于美国的部分进口商品加征关税的公告","新华社2018年9月、12月关于中美经贸摩擦与双方会晤情况的报道","海关总署2019年1月发布的2018年货物进出口统计数据"],tags:["中美经贸摩擦","关税","301调查"]},related:["cn--2001--e01", "cn--1999--e01", "cn--2015--e01"]},
{id:"cn--2018--e02",track:"cn",year:2018,yearApprox:false,dim:"economy",weight:3,title:"个人所得税法修改并增设专项附加扣除",summary:"2018年8月31日通过修改，起征点提高至每月5000元。",detail:{background:"个人所得税法自1980年施行后经历多次修改，工资薪金所得的费用扣除标准于2011年4月提高至每月3500元。2018年6月十三届全国人大常委会第七次会议初次审议个人所得税法修正案草案，同年8月再次审议。",process:"2018年8月31日，十三届全国人大常委会第五次会议通过关于修改个人所得税法的决定，将工资薪金、劳务报酬、稿酬与特许权使用费4项所得合并为综合所得，按纳税年度合并计算并适用3%至45%的超额累进税率，基本减除费用标准提高至每年6万元（每月5000元），并增加专项附加扣除、反避税条款与纳税人识别号制度。2018年12月国务院印发《个人所得税专项附加扣除暂行办法》，自2019年1月1日起施行，明确子女教育、继续教育、大病医疗、住房贷款利息、住房租金、赡养老人6项专项附加扣除的适用范围与定额标准。",impact:"2022年3月，据新华社报道，国务院决定设立3岁以下婴幼儿照护个人所得税专项附加扣除，自2022年1月1日起按每个子女每月1000元标准定额扣除。2023年8月国务院印发通知，将子女照护、子女教育与赡养老人3项专项附加扣除标准分别提高至每个子女每月2000元、2000元和每月3000元。据国家税务总局历年税收收入数据，2019年起个人所得税收入增速明显回落，综合所得年度汇算清缴自2020年3月首次开展。",figures:["国家税务总局"],place:"北京",state:"中华人民共和国",sources:["全国人大常委会2018年8月31日关于修改个人所得税法的决定及新华社报道","国务院2018年12月印发的《个人所得税专项附加扣除暂行办法》","新华社2022年3月、2023年8月关于专项附加扣除设立与提高标准的报道"],tags:["个人所得税","综合所得","专项附加扣除"]},related:["cn--1994--e01", "cn--2010--i01"]},
{id:"cn--2018--s01",track:"cn",year:2018,yearApprox:false,dim:"science",weight:3,title:"港珠澳大桥建成通车",summary:"2018年10月23日开通，全长约55公里的桥岛隧集群。",detail:{background:"港珠澳大桥连接香港、珠海与澳门，主体工程2009年12月正式开工，由桥梁、人工岛与海底沉管隧道组成，跨越珠江口伶仃洋海域，并需在近机场航道与深水航道处以隧道通过。",process:"2018年10月23日，港珠澳大桥开通仪式在广东珠海举行，大桥正式开通。据交通运输部与项目主体单位的公开介绍，大桥总长约55公里，海底隧道采用33节钢壳混凝土预制沉管对接安装，人工岛由外海快速筑岛技术建成；同期广深港高铁香港段已于2018年9月23日投入运营，大湾区跨境交通通道进一步加密。",impact:"据广东省政府与新华社2018年10月的介绍，通车后珠海至香港口岸的车程缩短至约45分钟。2023年6月，据广东省公安等部门发布的通告，港珠澳大桥珠海公路口岸实施“港车北上”政策，自2023年7月1日起允许符合条件的香港机动车经该口岸入境广东省。大桥与2024年6月通车的深中通道等工程共同构成珠江口东西两岸的跨海通道网络。",figures:["林鸣"],place:"广东珠海、澳门及香港",state:"中华人民共和国",sources:["新华社2018年10月23日关于港珠澳大桥开通仪式的报道","交通运输部与港珠澳大桥管理局关于主体工程与沉管隧道的公开介绍","广东省公安等部门2023年6月关于“澳车北上”“港车北上”政策实施安排的通告"],tags:["港珠澳大桥","跨海通道","粤港澳大湾区"]},related:["cn--2008--s02", "cn--1990--e01"]},
{id:"cn--2019--p01",track:"cn",year:2019,yearApprox:false,dim:"politics",weight:4,title:"中共十九届四中全会召开",summary:"2019年10月28日至31日召开，部署国家治理体系与治理能力现代化。",detail:{background:"2013年十八届三中全会提出完善和发展中国特色社会主义制度、推进国家治理体系和治理能力现代化的改革总目标。2019年为中华人民共和国成立70周年。",process:"2019年10月28日至31日，中共十九届四中全会在北京举行，通过《中共中央关于坚持和完善中国特色社会主义制度、推进国家治理体系和治理能力现代化若干重大问题的决定》。全会总结13个方面的显著优势，提出坚持和完善党的领导制度体系、人民当家作主制度体系、中国特色社会主义法治体系、社会主义基本经济制度、繁荣发展社会主义先进文化的制度、统筹城乡的民生保障制度、生态文明制度体系、党对人民军队的绝对领导制度、“一国两制”制度体系、独立自主的和平外交政策等13个方面的重点任务，并明确在2021年、2035年和本世纪中叶三个时间节点上的制度建设目标。",impact:"据决定把社会主义基本经济制度的内涵由所有制扩展为所有制、分配制度与社会主义市场经济体制并列，2020年5月中共中央、国务院印发《关于新时代加快完善社会主义市场经济体制的意见》。人大与政府组织制度此后相应调整：2021年3月十三届全国人大四次会议通过关于修改全国人大组织法的决定，增设总监票人制度并把“全过程民主”写入法律。2023年3月《党和国家机构改革方案》把机构改革纳入国家治理体系调整的同一框架。",figures:["习近平"],place:"北京",state:"中华人民共和国",sources:["《中共中央关于坚持和完善中国特色社会主义制度、推进国家治理体系和治理能力现代化若干重大问题的决定》（2019年10月31日通过）及新华社受权发布","中共中央、国务院2020年5月印发的《关于新时代加快完善社会主义市场经济体制的意见》","新华社2021年3月11日关于十三届全国人大四次会议通过修改全国人大组织法决定的报道"],tags:["十九届四中全会","国家治理体系","治理能力现代化"]},related:["cn--2014--p01", "cn--2017--p01", "cn--2013--p01"]},
{id:"cn--2019--i01",track:"cn",year:2019,yearApprox:false,dim:"institution",weight:3,title:"外商投资法通过并自2020年施行",summary:"2019年3月15日通过，取代外资三法并确立准入前国民待遇加负面清单。",detail:{background:"中国外商投资领域此前由中外合资经营企业法（1979年）、外资企业法（1986年）与中外合作经营企业法（1988年）三部法律规范，即“外资三法”，并随历次修正。2018年12月全国人大常委会对外商投资法草案进行初次审议，2019年1月再次审议后决定提请2019年3月的大会审议。",process:"2019年3月15日，十三届全国人大二次会议通过《中华人民共和国外商投资法》，自2020年1月1日起施行，外资三法同时废止。该法规定国家对外商投资实行准入前国民待遇加负面清单管理制度，负面清单以外的领域按照内外资一致的原则实施管理；确立外商投资信息报告制度与外商投资安全审查制度；明确国家保护外国投资者和外商投资企业的投资、收益汇出与知识产权保护，行政机关及其工作人员不得以行政审批等为条件强制转让技术，并建立外商投资企业投诉工作机制。",impact:"据商务部2020年1月发布，2019年全国新设外商投资企业超过8万家，实际使用外资9415亿元人民币、同比增长5.8%。2021年1月18日《外商投资安全审查办法》施行，工作机制办公室设在国家发展改革委。2024年11月商务部与国家发展改革委发布2024年版全国外商投资准入负面清单，删除全部制造业领域限制条目；据同年发布的数据，负面清单条目自2017年的93条缩减至29条。",figures:["栗战书"],place:"北京",state:"中华人民共和国",sources:["新华社2019年3月15日关于十三届全国人大二次会议通过外商投资法的报道及法律文本","商务部2020年1月关于2019年吸收外资情况的发布","商务部、国家发展改革委2024年11月发布的《外商投资准入特别管理措施（负面清单）（2024年版）》"],tags:["外商投资法","负面清单","准入前国民待遇"]},related:["cn--2001--e01", "cn--2013--e01", "cn--2018--e01"]},
{id:"cn--2019--s01",track:"cn",year:2019,yearApprox:false,dim:"science",weight:4,title:"嫦娥四号实现月球背面软着陆",summary:"2019年1月3日着陆器与玉兔二号在冯·卡门撞击坑着陆。",detail:{background:"2013年嫦娥三号完成月面软着陆后，中国探月工程二期继续推进月背探测。因月球背面与地球无法直接通信，任务需先发射中继星。玉兔二号巡视器与着陆器组成的嫦娥四号探测器由长征三号乙运载火箭发射。",process:"2018年5月21日，鹊桥中继星由长征四号丙运载火箭在西昌卫星发射中心发射，进入地月拉格朗日L2点halo轨道，为月背与地面提供通信链路。2018年12月8日嫦娥四号发射，2019年1月3日着陆器携带玉兔二号巡视器成功软着陆于月球背面南极—艾特肯盆地的冯·卡门撞击坑，并通过中继星传回月背近距离影像，随后两器分离开展巡视探测。",impact:"据国家航天局公布，这是人类航天器首次在月球背面软着陆并在月面开展巡视探测，玉兔二号此后多次度过月夜并持续工作。此后2020年12月嫦娥五号完成月球样品自动取样返回，2024年6月嫦娥六号返回器携带采自月球背面南极—艾特肯盆地的样品着陆，实现人类首次月背采样返回。",figures:["孙泽洲"],place:"西昌卫星发射中心及月球背面",state:"中华人民共和国",sources:["国家航天局2019年1月3日关于嫦娥四号成功落月的发布及新华社报道","新华社2018年5月21日关于鹊桥中继星发射的报道","国家航天局2024年6月关于嫦娥六号任务返回的发布"],tags:["嫦娥四号","月球背面","玉兔二号"]},related:["cn--2013--s01", "cn--2010--s01", "cn--2004--s01"]},
{id:"cn--2019--c01",track:"cn",year:2019,yearApprox:false,dim:"culture",weight:3,title:"良渚古城遗址列入世界遗产名录",summary:"2019年7月第43届世界遗产大会通过审议，列入名录。",detail:{background:"良渚古城遗址位于浙江省杭州市余杭区，年代约为公元前3300年至公元前2300年，由城址、外围水利系统、分等级墓地与祭坛等遗存组成。据浙江省文物考古研究所2007年公布的考古成果，良渚古城总面积约300万平方米，其外围水利系统为中国已知早期大型水利工程。",process:"2019年7月6日，在阿塞拜疆巴库举行的联合国教科文组织世界遗产委员会第43届会议审议通过，将中国申报的“良渚古城遗址”列入《世界遗产名录》。据国家文物局发布，该遗址作为新石器时代晚期实证早期城市文明的项目被列入，同日良渚古城遗址公园对公众开放。",impact:"据国家文物局与浙江省此后公布的保护安排，杭州设立良渚古城遗址管理机构并颁布地方性保护法规，遗址缓冲地带内的建设与挖掘受到限制。2020年11月中央政治局第二十三次集体学习就考古工作举行会议，此后“考古中国”重大项目把长江下游早期文明研究列入其中；中华文明探源工程的多期成果把良渚、陶寺、石峁等遗址作为考察早期国家形成的关键材料。",figures:["刘斌"],place:"浙江杭州",state:"中华人民共和国",sources:["联合国教科文组织世界遗产中心2019年7月6日关于第43届世界遗产大会新增项目的公告","国家文物局2019年7月关于良渚古城遗址列入《世界遗产名录》的发布","浙江省文物考古研究所关于良渚古城考古工作的公开报告"],tags:["良渚古城","世界遗产","中华文明探源"]},related:["cn--2001--c01", "cn--2006--c01"]},
{id:"cn--2019--d01",track:"cn",year:2019,yearApprox:false,dim:"disaster",weight:3,title:"江苏响水发生3·21特别重大爆炸事故",summary:"2019年3月21日化工厂爆炸，调查组认定78人遇难。",detail:{background:"响水天嘉宜化工有限公司位于江苏省盐城市生态化工科技产业园，长期累积大量硝化类危险废物。据国务院事故调查组2019年11月公布的调查报告，该企业多次因安全问题被行政处罚，旧固废库内硝化废料因积热自燃引发爆炸。",process:"2019年3月21日14时48分许，天嘉宜公司发生特别重大爆炸事故，爆炸波及园区内其他企业并造成周边建筑受损。据上述调查报告，事故造成78人死亡、76人重伤，640人住院治疗，直接经济损失19.86亿元；报告认定这是一起特别重大生产安全责任事故，指出企业、地方党委政府和有关部门存在违法违规审批、监管缺失等问题，并移送一批责任人员。",impact:"事故后江苏开展化工产业安全环保整治提升，关闭沿长江、运河重点区域的化工企业并集中建设化工园区。2020年3月，中共中央办公厅、国务院办公厅印发《关于进一步加强危险化学品安全生产工作的意见》，对危险化学品企业的安全生产责任落实与风险隐患排查整治提出进一步要求。2021年6月10日全国人大常委会修改《安全生产法》，自2021年9月1日施行，确立全员安全生产责任制和“管行业必须管安全、管业务必须管安全、管生产经营必须管安全”的原则，并加重对主要负责人与地方监管责任的处罚。",figures:["国务院事故调查组"],place:"江苏盐城",state:"中华人民共和国",sources:["国务院江苏响水天嘉宜化工有限公司“3·21”特别重大爆炸事故调查组2019年11月公布的调查报告及新华社报道","中共中央办公厅、国务院办公厅2020年3月印发的《关于进一步加强危险化学品安全生产工作的意见》","全国人大常委会2021年6月10日关于修改安全生产法的决定"],tags:["响水爆炸","危险化学品","安全生产"]},related:["cn--2015--d01", "cn--2012--d01"]},
{id:"cn--2020--p01",track:"cn",year:2020,yearApprox:false,dim:"politics",weight:4,title:"现行标准下农村贫困人口全部脱贫",summary:"2020年11月贫困县全部摘帽，2021年2月大会宣布脱贫攻坚胜利。",detail:{background:"2013年11月在湖南湘西考察时提出“精准扶贫”概念；2015年10月中共十八届五中全会与同年11月《中共中央 国务院关于打赢脱贫攻坚战的决定》提出，到2020年现行标准下农村贫困人口实现脱贫、贫困县全部摘帽、解决区域性整体贫困。",process:"2020年11月23日，贵州省宣布最后9个贫困县退出贫困县序列。据国务院扶贫办公布的名单，其确定的832个贫困县在这一天全部脱贫摘帽。2021年2月25日，全国脱贫攻坚总结表彰大会在北京举行，据大会公布，现行标准下9899万农村贫困人口全部脱贫，12.8万个贫困村全部出清，区域性整体贫困得到解决，并完成脱贫攻坚先进个人与先进集体表彰，授予一批人员“全国脱贫攻坚楷模”荣誉称号。",impact:"2021年2月25日国家乡村振兴局挂牌，承接原国务院扶贫办的职能。2021年3月《中共中央 国务院关于实现巩固拓展脱贫攻坚成果同乡村振兴有效衔接的意见》提出设立5年过渡期，过渡期内保持主要帮扶政策总体稳定，并建立防止返贫动态监测和帮扶机制。据国家统计局公布，2021年、2022年脱贫县农村居民人均可支配收入实际增速高于全国农村平均水平。2021年4月国务院新闻办公室发表《人类减贫的中国实践》白皮书。",figures:["国务院扶贫办","国家乡村振兴局"],place:"北京及全国脱贫地区",state:"中华人民共和国",sources:["新华社2021年2月25日关于全国脱贫攻坚总结表彰大会的报道","国务院新闻办公室2021年4月发表的《人类减贫的中国实践》白皮书","《中共中央 国务院关于实现巩固拓展脱贫攻坚成果同乡村振兴有效衔接的意见》（2021年3月发布）"],tags:["脱贫攻坚","精准扶贫","贫困县摘帽"]},related:["cn--2015--p01", "cn--2020--e01", "cn--2013--p01"]},
{id:"cn--2020--i01",track:"cn",year:2020,yearApprox:false,dim:"institution",weight:4,title:"中华人民共和国民法典通过",summary:"2020年5月28日全国人大通过，2021年1月1日施行，共7编1260条。",detail:{background:"新中国成立后曾于1954年、1962年、1979年和2001年四次启动民法制定与法典起草工作，均未完成。2014年中共十八届四中全会提出编纂民法典，2017年3月十二届全国人大五次会议先通过作为总则编的民法总则，其后整合各分编。",process:"2020年5月28日，十三届全国人大三次会议通过《中华人民共和国民法典》，自2021年1月1日起施行，共7编1260条，依次为总则、物权、合同、人格权、婚姻家庭、继承、侵权责任七编及附则，同时废止婚姻法、继承法、民法通则、收养法、担保法、合同法、物权法、侵权责任法与民法总则9部法律。据该法文本，人格权独立成编，规定个人信息保护、性骚扰防治与隐私权范围；物权编新增居住权制度并完善业主共有部分与公共维修资金的规则；合同编禁止高利放贷、新增物业服务合同与保理合同；婚姻家庭编规定自婚姻登记机关收到离婚登记申请之日起30日的冷静期；侵权责任编细化高空抛物情形下的责任与自助行为规则。",impact:"据最高人民法院2021年1月发布，为配套民法典施行，最高法对1980年至2020年制定的司法解释进行全面清理，废止一批司法解释并于2021年1月1日同步发布首批民法典配套司法解释。此后担保制度、物权、人格权与婚姻家庭等领域的司法解释陆续修订。2022年起最高人民法院按年度发布民法典施行情况与典型案件，据其工作报告，民法典确立的规则在居住权登记、个人信息保护与高空抛物追责等案件中进入司法适用。",figures:["沈跃跃"],place:"北京",state:"中华人民共和国",sources:["新华社2020年5月28日关于十三届全国人大三次会议通过民法典的报道及法律文本","最高人民法院2021年1月关于民法典配套司法解释与司法解释全面清理情况的发布","全国人大常委会法制工作委员会2020年5月关于民法典草案的说明"],tags:["民法典","人格权编","居住权"]},related:["cn--2017--i01", "cn--2007--i01", "cn--2001--i01"]},
{id:"cn--2020--s01",track:"cn",year:2020,yearApprox:false,dim:"science",weight:3,title:"北斗三号全球卫星导航系统建成开通",summary:"2020年7月31日建成开通，向全球提供定位导航授时服务。",detail:{background:"中国北斗卫星导航系统按北斗一号试验系统、北斗二号区域系统与北斗三号全球系统分步建设。2012年12月北斗二号正式向亚太地区提供导航服务；北斗三号由中圆地球轨道、倾斜地球同步轨道与地球静止轨道三种轨道卫星构成混合星座。",process:"2020年6月23日，第55颗北斗导航卫星即北斗三号最后一颗全球组网卫星由长征三号乙运载火箭在西昌卫星发射中心发射入轨，星座部署完成。2020年7月31日，北斗三号全球卫星导航系统建成暨开通仪式在北京举行，据新华社，开通运行的北斗三号系统由30颗卫星组成，面向全球提供服务。",impact:"据中国卫星导航系统管理办公室公布的性能说明，北斗三号系统提供定位导航授时、全球短报文通信、区域短报文通信、国际搜救、星基增强、地基增强与精密单点定位共7类服务。据中国卫星导航定位协会《2021中国卫星导航与位置服务产业发展白皮书》，2020年我国卫星导航产业总体产值为4033亿元，交通运输、渔业船舶、防灾减灾与测绘等领域为其主要应用方向。",figures:["孙家栋","谢军"],place:"西昌卫星发射中心及北京",state:"中华人民共和国",sources:["新华社2020年6月23日、7月31日关于北斗三号全球卫星导航系统建成开通的报道","中国卫星导航系统管理办公室关于北斗系统服务性能的公开说明","中国卫星导航定位协会《2021中国卫星导航与位置服务产业发展白皮书》"],tags:["北斗三号","卫星导航","全球组网"]},related:["cn--2000--s01", "cn--2013--s01"]},
{id:"cn--2020--x01",track:"cn",year:2020,yearApprox:false,dim:"explore",weight:3,title:"奋斗者号载人潜水器坐底马里亚纳海沟",summary:"2020年11月10日坐底10909米，创中国载人深潜纪录。",detail:{background:"2012年蛟龙号完成7062米级海试后，我国启动万米级载人潜水器研制，将其列入国家重点研发计划，由中国船舶集团有限公司第七〇二研究所牵头设计与集成，载员舱等关键部件在国内完成制造与试验。",process:"2020年11月10日，奋斗者号载人潜水器在西太平洋马里亚纳海沟海域成功坐底，坐底深度10909米，搭载3名潜航员并在海底开展作业与采样，据中国科学院与第七〇二研究所公布的航次信息，该潜器在同航次中多次完成万米级下潜，并完成载人舱与浮力材料的深海工况验证。",impact:"据中国船舶集团第七〇二研究所与中国科学院公布，该潜水器的钛合金载人舱、高性能固体浮力材料、深水通信与布放回收系统等关键部件实现自主研制，与4500米级深海勇士号、7000米级蛟龙号形成梯次深潜装备体系。此后奋斗者号常态化赴西太平洋深渊海域执行科考任务，据中国科学院深海科学与工程研究所发布，其搭载的着陆器与载人舱获取的深渊生物、沉积物与水样样本被用于深渊环境与生物研究。",figures:["叶聪"],place:"西太平洋马里亚纳海沟",state:"中华人民共和国",sources:["中国科学院与新华社2020年11月关于奋斗者号载人潜水器成功坐底万米的发布","中国船舶集团有限公司第七〇二研究所关于全海深载人潜水器研制情况的公开介绍","中国科学院深海科学与工程研究所关于深渊科考航次成果的发布"],tags:["奋斗者号","载人深潜","马里亚纳海沟"]},related:["cn--2012--s02", "cn--2005--x01"]},
{id:"cn--2020--d01",track:"cn",year:2020,yearApprox:false,dim:"disaster",weight:5,title:"新冠肺炎疫情暴发与武汉保卫战",summary:"2020年1月23日武汉关闭离汉通道，4.2万余名医务人员驰援。",detail:{background:"2019年12月湖北省武汉市报告多例不明原因肺炎病例，2020年1月病原被确认为一种新型冠状病毒。2020年1月20日经国务院批准，国家卫生健康委员会发布1号公告，将新型冠状病毒感染的肺炎纳入传染病防治法规定的乙类传染病并采取甲类传染病的预防、控制措施，并列入海关法规定的出入境检疫传染病。",process:"2020年1月23日武汉市宣布暂时关闭全市离汉通道，机场、铁路客运场所停止运营，城市公交与地铁停运。此后全国31个省区市启动重大突发公共卫生事件一级响应，各地组织医疗队赴湖北。据国务院新闻办公室2020年3月发布的《抗击新冠肺炎疫情的中国行动》白皮书，截至2020年5月31日24时，31个省区市和新疆生产建设兵团报告确诊病例84565例，治愈出院78288例，病亡4634例；全国先后派出数百支医疗队、4.2万余名医务人员支援湖北。2020年2月火神山医院、雷神山医院交付使用并陆续收治患者，4月8日武汉解除离汉离鄂通道管控措施。",impact:"2020年5月召开的十三届全国人大三次会议因疫情推迟，会议通过的《政府工作报告》提出“六稳”“六保”任务。法律制度层面，2020年10月17日十三届全国人大常委会第二十二次会议通过《中华人民共和国生物安全法》，自2021年4月15日起施行；疫苗方面，2020年12月我国启动重点人群新冠病毒疫苗接种，多款疫苗此后陆续获附条件批准上市。此后疫情防控持续两年，2022年12月起防控措施进一步优化调整。",figures:["国家卫生健康委员会"],place:"湖北武汉及全国",state:"中华人民共和国",sources:["国务院新闻办公室2020年3月发表的《抗击新冠肺炎疫情的中国行动》白皮书","国家卫生健康委员会2020年1月20日关于将新型冠状病毒感染的肺炎纳入法定传染病管理的1号公告","新华社2020年4月8日关于武汉解除离汉离鄂通道管控的报道"],tags:["新冠疫情","武汉","突发公共卫生事件"]},related:["cn--2003--d01", "cn--2003--i01", "cn--2020--e01", "world--2020--d01"]},
{id:"cn--2020--e01",track:"cn",year:2020,yearApprox:false,dim:"economy",weight:3,title:"2020年经济总量突破100万亿元",summary:"据国家统计局数据，2020年国内生产总值增长2.3%。",detail:{background:"疫情冲击下2020年一季度国内生产总值同比下降6.8%，为1992年公布该季度指标以来首次季度负增长。2020年5月22日《政府工作报告》提出宏观政策规模，并明确当年不再设定全年经济增速具体目标，改为强调稳保就业、民生与防范风险。",process:"据2020年《政府工作报告》，2020年赤字率按3.6%以上安排、新增地方政府专项债务限额3.75万亿元、发行1万亿元抗疫特别国债，并提出预计全年为企业新增减负超过2.5万亿元。据国家统计局2021年1月发布的初步核算数据，2020年国内生产总值1013567亿元，按可比价格计算比上年增长2.3%；全年粮食产量66949万吨；据海关总署2021年1月发布，2020年货物贸易进出口总值32.16万亿元人民币、同比增长1.9%，其中出口增长4.0%。",impact:"据国家统计局2022年1月发布，2021年国内生产总值1143670亿元、同比增长8.1%，两年平均增长5.1%。2020年宏观政策安排此后延续：新增财政直达资金机制自2020年建立并在其后两年继续使用；据人力资源和社会保障部2021年发布，2020年全国实现城镇新增就业1186万人，完成当年报告目标。2020年经济总量跨越100万亿元后，2021年、2022年继续上升。",figures:["国家统计局","海关总署"],place:"北京",state:"中华人民共和国",sources:["国家统计局2021年1月发布的2020年国民经济运行情况数据","2020年《政府工作报告》（2020年5月22日）及新华社受权发布","海关总署2021年1月发布的2020年货物进出口统计数据"],tags:["2020年经济数据","抗疫特别国债","六稳六保"]},related:["cn--2020--p01", "cn--2020--d01", "cn--2008--e01"]},
{id:"cn--2021--p01",track:"cn",year:2021,yearApprox:false,dim:"politics",weight:4,title:"庆祝中国共产党成立100周年大会举行",summary:"2021年7月1日在北京举行，大会宣告实现第一个百年奋斗目标。",detail:{background:"中共把1921年7月党的一大召开作为建党历史起点，并以7月1日为建党纪念日。2017年中共十九大提出的两个一百年奋斗目标中，第一个百年目标为到中国共产党成立100年时全面建成小康社会。2020年11月，云南省、贵州省等贫困省份宣布贫困县全部摘帽，2020年11月23日832个贫困县全部脱贫。",process:"2021年7月1日，庆祝中国共产党成立100周年大会在北京天安门广场举行，各界代表出席大会。据新华社报道，习近平在会上代表党和人民宣告，经过全党全国各族人民持续奋斗，实现了第一个百年奋斗目标，在中华大地上全面建成了小康社会，历史性地解决了绝对贫困问题，并提出以中国式现代化全面推进中华民族伟大复兴、在新征程上夺取新的更大胜利等表述。2021年6月29日，七一勋章颁授仪式在北京人民大会堂举行，据中共中央批准发布的名单，一批党员获授七一勋章，另有全国优秀共产党员、全国先进基层党组织同期表彰。",impact:"大会提出的下一阶段目标为到中华人民共和国成立100年时建成社会主义现代化强国。这一时间框架与此后文件衔接：2021年3月十三届全国人大四次会议批准的《中华人民共和国国民经济和社会发展第十四个五年规划和2035年远景目标纲要》列出2035年远景指标；2022年10月中共二十大报告以中国式现代化概括推进中华民族伟大复兴的路径，并重申2035年基本实现社会主义现代化的目标。2021年起，全面建成小康社会成为官方统计与政策表述中的既有基准点。",figures:["习近平"],place:"北京天安门广场",state:"中华人民共和国",sources:["新华社2021年7月1日关于庆祝中国共产党成立100周年大会的报道","《在庆祝中国共产党成立100周年大会上的讲话》（2021年7月1日）","中共中央2021年6月29日关于颁授七一勋章和表彰全国优秀共产党员、全国先进基层党组织的发布"],tags:["建党百年","第一个百年目标","七一勋章"]},related:["cn--2020--p01", "cn--2017--p01", "cn--2012--p01"]},
{id:"cn--2021--i01",track:"cn",year:2021,yearApprox:false,dim:"institution",weight:3,title:"人口与计划生育法修改实施三孩生育政策",summary:"2021年8月20日修法，允许一对夫妻生育三个子女并取消社会抚养费。",detail:{background:"2013年12月启动单独二孩，2015年10月中共十八届五中全会提出全面两孩并于同年12月修改《人口与计划生育法》后，出生人口在2016年达1786万人、2017年为1723万人，此后连续下降，据国家统计局数据2020年降至1200万人。2021年5月11日国务院第七次全国人口普查领导小组发布主要数据，全国人口共141178万人，其中0至14岁人口占17.95%，60岁及以上人口占18.70%。",process:"2021年5月31日，中共中央政治局会议听取优化生育政策促进人口长期均衡发展有关工作汇报，决定实施一对夫妻可以生育三个子女政策及配套支持措施。2021年6月26日，《中共中央 国务院关于优化生育政策促进人口长期均衡发展的决定》公布，提出三孩生育政策及配套支持措施，明确取消社会抚养费等制约措施、清理和废止相关处罚规定。2021年8月20日，十三届全国人大常委会第三十次会议通过修改《中华人民共和国人口与计划生育法》的决定，自公布之日起施行，规定国家提倡适龄婚育、优生优育，一对夫妻可以生育三个子女，并把入户、入学、入职等与个人生育情况脱钩。",impact:"修法后社会抚养费制度退出，各省在2021年至2022年陆续修订地方人口与计划生育条例并废止相关处罚规定。2022年3月，据国务院发布，设立3岁以下婴幼儿照护个人所得税专项附加扣除；2022年8月，国家卫生健康委等17部门印发《关于进一步完善和落实积极生育支持措施的指导意见》，把托育服务、住房与税收支持列为重点。人口指标方面，据国家统计局2023年1月发布，2022年全年出生人口956万人、死亡人口1041万人，年末全国人口141175万人，比上年末减少85万人，为1962年以来人口总量首次出现负增长。",figures:["全国人大常委会","国家统计局"],place:"北京",state:"中华人民共和国",sources:["新华社2021年8月20日关于十三届全国人大常委会第三十次会议通过修改人口与计划生育法决定的报道及法律文本","《中共中央 国务院关于优化生育政策促进人口长期均衡发展的决定》（2021年6月26日公布）","国务院第七次全国人口普查领导小组、国家统计局2021年5月11日发布的第七次全国人口普查主要数据"],tags:["三孩生育政策","第七次人口普查","社会抚养费"]},related:["cn--2015--p01", "cn--2011--e01"]},
{id:"cn--2021--e01",track:"cn",year:2021,yearApprox:false,dim:"economy",weight:3,title:"北京证券交易所开市运行",summary:"2021年9月2日宣布设立、11月15日开市，首批81家上市公司。",detail:{background:"全国中小企业股份转让系统（新三板）2013年12月扩大至全国后，2019年10月中国证监会启动全面深化新三板改革，2020年7月27日精选层首批企业挂牌。2020年3月新修订的《证券法》施行，股票发行注册制改革在科创板、创业板先行试点后逐步推开。",process:"2021年9月2日，在2021年中国国际服务贸易交易会全球服务贸易峰会上宣布，继续支持中小企业创新发展，深化新三板改革，设立北京证券交易所，打造服务创新型中小企业主阵地。据中国证监会2021年10月30日发布的《北京证券交易所向不特定合格投资者公开发行股票注册管理办法》等部门规章与业务规则，北交所上市公司来源于在新三板创新层连续挂牌满12个月的企业，实行注册制，设置连续竞价交易与30%涨跌幅等安排。2021年11月15日，北京证券交易所正式开市，首批81家上市公司。",impact:"北交所设立后，新三板基础层、创新层与北交所形成层层递进的市场结构，与沪深交易所错位发展。2023年2月17日，据中国证监会发布，全面实行股票发行注册制的制度规则落地，同年4月沪深交易所首批注册制企业完成上市。据北京证券交易所公开月报，北交所上市公司数量自开市起逐年增加，公司行业分布以制造业与信息传输、软件和技术服务类为主，其中多数为注册资本规模较小的创新型中小企业。",figures:["中国证监会"],place:"北京",state:"中华人民共和国",sources:["新华社2021年9月2日关于设立北京证券交易所的报道","中国证监会2021年10月30日发布的北交所公开发行股票注册管理等部门规章及业务规则","中国证监会2023年2月关于全面实行股票发行注册制制度规则发布的公告"],tags:["北京证券交易所","新三板","创新型中小企业"]},related:["cn--1990--e02", "cn--1990--e03", "cn--2017--e01"]},
{id:"cn--2021--s01",track:"cn",year:2021,yearApprox:false,dim:"science",weight:4,title:"天问一号着陆火星并开展巡视探测",summary:"2021年5月15日着陆乌托邦平原，祝融号5月22日到达火星表面。",detail:{background:"2016年1月中国火星探测工程立项论证；2020年4月24日，国家航天局在当年中国航天日启动仪式上把行星探测工程命名为天问系列。2020年7月23日，天问一号由长征五号运载火箭在文昌航天发射场发射，2021年2月10日实施近火制动进入环火轨道，此后开展为期约3个月的火星表面成像与着陆区选择。",process:"2021年5月15日，天问一号着陆巡视器与环绕器分离，进入火星大气并经历减速、悬停与避障后，当日软着陆于火星乌托邦平原南部预选着陆区，环绕器传回着陆区影像。2021年5月22日，祝融号火星车安全驶离着陆平台到达火星表面，开始巡视探测，着陆点与祝融号、环绕器构成着巡组合体协同工作。据国家航天局2021年8月发布，祝融号火星车累计行驶达1000米，环绕器在中继通信轨道获取火星表面与内部结构探测数据，两者均工作正常。",impact:"据国家航天局发布，天问一号一次任务实现环绕、着陆、巡视，是中国首次自主火星探测，也是人类首次通过一次任务完成火星绕、着、巡。此后中国行星探测工程规划小行星探测与取样返回、火星采样返回及木星系探测等任务，天问二号于2025年5月发射执行小行星伴飞与取样任务。据中国科学院国家天文台2022年11月在国际学术期刊发表的研究，利用天问一号环绕器次表层探测雷达数据，在乌托邦平原南部地下发现多层倾斜反射结构，相关成果以公开数据为基础开展讨论。",figures:["张荣桥"],place:"文昌航天发射场及火星乌托邦平原",state:"中华人民共和国",sources:["国家航天局2021年5月15日关于天问一号成功着陆火星的发布及新华社报道","国家航天局2021年8月关于祝融号火星车行驶里程与环绕器探测情况的发布","新华社2020年7月23日关于天问一号发射入轨的报道"],tags:["天问一号","祝融号","火星探测"]},related:["cn--2019--s01", "cn--2007--s01", "cn--2003--s01"]},
{id:"cn--2021--c01",track:"cn",year:2021,yearApprox:false,dim:"culture",weight:3,title:"三星堆遗址祭祀区考古公布新发现",summary:"2021年3月通报新确认6座祭祀坑，采用多学科考古发掘方式。",detail:{background:"三星堆遗址位于四川省广汉市，1929年被发现，1986年发掘一、二号祭祀坑，出土青铜大立人像、青铜神树、纵目面具与金杖等文物。2019年11月起，四川省文物考古研究院联合国内多家科研单位对遗址祭祀区开展新的主动性发掘，并纳入国家文物局考古中国重大项目。",process:"2021年3月20日，考古中国重大项目工作进展会在北京通报三星堆遗址祭祀区考古进展，宣布在原有祭祀坑分布区旁新发现并确认编号为三至八号的6座祭祀坑，已提取青铜大面具、金面具、象牙等一批编号文物。据四川省文物考古研究院的通报，本轮发掘在祭祀坑上方搭建恒温恒湿考古舱，配置三维建模、超景深显微记录、纺织品与残留物取样、有机质检测等工序，发掘过程同步开展实验室分析。2022年6月13日，四川省文物考古研究院再次通报，本轮发掘出土大批编号文物，其中青铜器、金器与象牙制品占多数，并把祭祀坑的年代判定为商代晚期。",impact:"三星堆的材料被纳入中华文明早期与区域交流的讨论框架：中华文明探源工程及其后续阶段把三星堆与良渚、陶寺、石峁等遗址共同作为考察早期文明互动的关键材料，据国家文物局发布，考古中国项目把长江上游古代文明研究列入其中。保护与展陈安排同步推进，据四川省文物局与三星堆博物馆2023年发布，三星堆博物馆新馆在该年建成并向公众开放，遗址的保护范围与建设控制要求按公布规划执行。",figures:["四川省文物考古研究院"],place:"四川广汉",state:"中华人民共和国",sources:["考古中国重大项目工作进展会2021年3月20日关于三星堆遗址祭祀区新发现的通报","四川省文物考古研究院2022年6月关于三星堆祭祀区发掘成果的发布","国家文物局关于考古中国重大项目与中华文明探源工程进展的公开发布"],tags:["三星堆","祭祀坑","考古中国"]},related:["cn--2019--c01", "cn--2006--c01"]},
{id:"cn--2021--d01",track:"cn",year:2021,yearApprox:false,dim:"disaster",weight:3,title:"河南发生郑州“7·20”特大暴雨灾害",summary:"2021年7月河南极端强降雨，国务院调查组认定398人死亡失踪。",detail:{background:"2021年7月17日至23日，河南省遭遇极端强降雨，累计雨量大、持续时间长、点强面广，暴雨中心位于郑州、新乡等地。据国务院灾害调查组2022年1月发布的《河南郑州“7·20”特大暴雨灾害调查报告》，此次灾害由极端暴雨引发城市内涝、河流洪水、山洪滑坡等多种灾害叠加。",process:"据上述调查报告，2021年7月20日16时至17时郑州本站降雨量达201.9毫米，超过我国大陆小时雨强纪录；强降雨造成京广北路隧道、地铁5号线等多处人员被困，出现重大人员伤亡。报告认定灾害造成河南省因灾死亡失踪398人，其中郑州市380人，全省直接经济损失1200.6亿元，并认定这是一起特大自然灾害叠加责任问题的灾害，指出郑州市及有关区、部门和领导干部存在风险认识不到位、应急响应与处置不及时、信息发布与统计报送不实等问题，对失职失责的公职人员依法依纪追责问责。灾害期间，国家层面调派消防救援、解放军和武警部队等专业力量参与抢险。",impact:"预警与响应的联动成为灾后制度调整的重点：据中国气象局与应急管理部2022年以来的公开要求，各地建立面向基层责任人的红色预警叫应机制，并把极端天气纳入交通停运、停工停课等临时应对措施。城市防洪与地铁防灾改造在郑州等地推进。据应急管理部2022年1月发布的2021年全国自然灾害情况，2021年各种自然灾害共造成全国6093.6万人次受灾、直接经济损失3340.2亿元，其中洪涝与地质灾害损失占比最高。",figures:["国务院灾害调查组"],place:"河南郑州",state:"中华人民共和国",sources:["国务院灾害调查组2022年1月发布的《河南郑州“7·20”特大暴雨灾害调查报告》","新华社2021年7月21日至23日关于河南防汛抢险救援的报道","应急管理部2022年1月发布的2021年全国自然灾害灾情情况"],tags:["郑州7·20暴雨","极端降雨","灾害调查"]},related:["cn--2012--d01", "cn--1998--d01", "cn--2010--d01"]},
{id:"cn--2022--p01",track:"cn",year:2022,yearApprox:false,dim:"politics",weight:5,title:"中国共产党第二十次全国代表大会召开",summary:"2022年10月16日至22日在北京举行，选举产生二十届中央领导机构。",detail:{background:"2021年11月8日至11日，中共十九届六中全会通过《中共中央关于党的百年奋斗重大成就和历史经验的决议》，对建党百年来的重大成就与历史经验作出总结。2022年8月30日中共中央政治局会议决定，十九届中央委员会向二十大的报告和《中国共产党章程（修正案）》稿在党内一定范围征求意见后提请大会审议。",process:"2022年10月16日至22日，中国共产党第二十次全国代表大会在北京举行。大会审查并批准十九届中央委员会所作报告，报告题为《高举中国特色社会主义伟大旗帜，为全面建设社会主义现代化国家而团结奋斗》；通过《中国共产党章程（修正案）》及相关决议。2022年10月22日，大会选举产生第二十届中央委员会和中央纪律检查委员会。2022年10月23日，二十届一中全会选举中央政治局、中央政治局常务委员会和中央委员会总书记，决定中央军事委员会组成人员，并批准中央书记处成员。",impact:"二十大报告提出以中国式现代化全面推进中华民族伟大复兴，列出到2035年基本实现社会主义现代化的总体要求，其中包括人均国内生产总值达到中等发达国家水平等表述。国家机构与党内制度安排此后衔接：2023年3月十四届全国人大一次会议完成换届并通过《党和国家机构改革方案》，2023年4月《中央全面深化改革委员会工作规则》等文件按新的机构框架施行。2024年7月，中共二十届三中全会审议通过《中共中央关于进一步全面深化改革、推进中国式现代化的决定》，把建立高水平社会主义市场经济体制等列为重点。",figures:["习近平"],place:"北京",state:"中华人民共和国",sources:["新华社2022年10月22日、23日关于中共二十大闭幕及二十届一中全会选举结果的报道","《高举中国特色社会主义伟大旗帜，为全面建设社会主义现代化国家而团结奋斗》（2022年10月16日）及新华社受权播发全文","中国共产党第二十次全国代表大会关于《中国共产党章程（修正案）》的决议（2022年10月22日通过）"],tags:["中共二十大","中国式现代化","党章修正案"]},related:["cn--2017--p01", "cn--2021--p01", "cn--2012--p01"]},
{id:"cn--2022--d01",track:"cn",year:2022,yearApprox:false,dim:"disaster",weight:4,title:"新冠疫情防控措施进一步优化调整",summary:"2022年12月7日发布新十条，2023年1月8日起实施乙类乙管。",detail:{background:"自2020年1月20日起，我国对新型冠状病毒感染的肺炎采取乙类传染病甲类预防、控制措施。2022年3月至5月，吉林、上海等地发生规模性疫情；2022年11月，广州、重庆、北京等地疫情快速上升，老年人群疫苗接种与医疗资源准备成为政策调整中的重点议题。",process:"2022年11月11日，国务院联防联控机制综合组发布《关于进一步优化新冠肺炎疫情防控措施 科学精准做好防控工作的通知》，对隔离期限、风险区划定与层层加码问题作出调整要求。2022年12月7日，联防联控机制综合组发布《关于进一步优化落实新冠肺炎疫情防控措施的通知》，提出对高风险区快封快解、不再开展全员核酸筛查、符合条件的无症状感染者与轻型病例可居家隔离治疗、加快推进老年人新冠病毒疫苗接种等10项措施。2022年12月26日，国家卫生健康委员会发布公告，将新型冠状病毒肺炎更名为新型冠状病毒感染，自2023年1月8日起解除对其采取的甲类传染病预防、控制措施。",impact:"调整后，全国发热门诊就诊量与药品需求在2022年12月下旬至2023年1月出现高峰后回落，新冠病毒感染纳入乙类乙管常态监测，国家卫生健康委员会按季度发布监测与诊疗情况。2023年2月16日，据新华社播发的中共中央政治局常务委员会会议通报，我国疫情防控取得重大决定性胜利，进入乙类乙管常态化防控阶段。2023年5月5日，世界卫生组织宣布新冠疫情不再构成国际关注的突发公共卫生事件。",figures:["国家卫生健康委员会"],place:"北京及全国",state:"中华人民共和国",sources:["国务院联防联控机制综合组2022年11月11日、12月7日发布的优化新冠肺炎疫情防控措施通知","国家卫生健康委员会2022年12月26日关于新型冠状病毒感染更名及实施乙类乙管的公告","世界卫生组织2023年5月5日关于新冠疫情不再构成国际关注的突发公共卫生事件的声明"],tags:["新十条","乙类乙管","疫情防控调整"]},related:["cn--2020--d01", "cn--2003--d01", "cn--2022--e01"]},
{id:"cn--2022--e01",track:"cn",year:2022,yearApprox:false,dim:"economy",weight:3,title:"2022年经济总量突破120万亿元",summary:"据国家统计局数据，2022年国内生产总值121万亿元、增长3.0%。",detail:{background:"2022年二季度，因疫情多点散发及外部需求、供应链波动，经济下行压力明显加大。2022年4月29日中共中央政治局会议分析研究当前经济形势和经济工作；同年5月25日国务院召开全国稳住经济大盘电视电话会议部署稳经济政策。",process:"2022年5月，国务院印发《扎实稳住经济的一揽子政策措施》，提出财政、货币金融、稳投资促消费、保粮食能源安全、保产业链供应链稳定、保基本民生6个方面33项措施；同年8月、9月国务院常务会议接续推出稳经济接续政策。据国家统计局2023年1月17日发布，2022年国内生产总值1210207亿元，按不变价格计算比上年增长3.0%；居民消费价格比上年上涨2.0%；全年粮食产量68653万吨。据海关总署2023年1月发布，2022年货物贸易进出口总值42.07万亿元人民币、同比增长7.7%，其中出口增长10.5%。据人力资源和社会保障部2023年发布，2022年全国城镇新增就业1206万人。",impact:"据国家统计局2023年2月发布的《2022年国民经济和社会发展统计公报》，2022年人均国内生产总值85692元。人口指标出现转折，2022年末全国人口141175万人，比上年末减少85万人，全年出生人口956万人、死亡人口1041万人，为1962年以来人口总量首次负增长。据国家统计局2024年1月发布，2023年国内生产总值1260582亿元、按不变价格计算比上年增长5.2%。",figures:["国家统计局","海关总署"],place:"北京",state:"中华人民共和国",sources:["国家统计局2023年1月17日发布的2022年国民经济运行情况及2023年2月《2022年国民经济和社会发展统计公报》","海关总署2023年1月发布的2022年货物进出口统计数据","国务院2022年5月印发的《扎实稳住经济的一揽子政策措施》"],tags:["2022年经济数据","稳经济一揽子政策","人口负增长"]},related:["cn--2020--e01", "cn--2021--i01", "cn--2022--d01"]},
{id:"cn--2022--s01",track:"cn",year:2022,yearApprox:false,dim:"science",weight:3,title:"中国空间站基本构型在轨组装完成",summary:"2022年问天、梦天实验舱转位，11月两个乘组首次在轨轮换。",detail:{background:"中国载人航天工程按三步走战略推进：先发射载人飞船，再突破航天员出舱与空间交会对接技术并发射空间实验室，第三步建造空间站。2021年4月29日天和核心舱由长征五号B遥二运载火箭在文昌航天发射场发射入轨，同年6月神舟十二号、10月神舟十三号乘组先后进驻，完成关键技术验证阶段任务。",process:"2022年为空间站建造阶段：5月10日天舟四号货运飞船发射，6月5日神舟十四号乘组进驻核心舱；7月24日问天实验舱由长征五号B遥三运载火箭发射，次日完成转位；10月31日梦天实验舱由长征五号B遥四运载火箭发射，11月1日顺利完成转位，空间站三舱T字基本构型在轨组装完成。2022年11月12日天舟五号货运飞船发射；11月29日神舟十五号乘组发射，11月30日与神舟十四号乘组在轨交接，这是中国空间站首次实现两个航天员乘组同时在轨轮换，在轨驻留航天员增至6人。",impact:"据中国载人航天工程办公室发布，空间站建造阶段任务于2022年12月收官。2023年5月神舟十六号乘组进驻后，工程转入应用与发展阶段，据该办公室发布，面向国内外征集的科学实验项目陆续上舱实施并公布阶段成果，神舟、天舟按批次轮换成为常态。此后2023年10月神舟十七号乘组执行任务并完成舱外维修作业，空间站进入长期有人驻留运行阶段。",figures:["中国载人航天工程办公室"],place:"文昌航天发射场及中国空间站",state:"中华人民共和国",sources:["中国载人航天工程办公室2022年7月、11月关于问天实验舱与梦天实验舱发射转位及乘组轮换的发布","新华社2022年11月30日关于神舟十四号与神舟十五号航天员乘组在轨交接的报道","中国载人航天工程办公室关于空间站应用与发展阶段任务安排的公开发布"],tags:["中国空间站","问天实验舱","梦天实验舱"]},related:["cn--2011--s01", "cn--2016--s01", "cn--2003--s01"]},
{id:"cn--2022--c01",track:"cn",year:2022,yearApprox:false,dim:"culture",weight:3,title:"第二十四届冬季奥运会在北京举行",summary:"2022年2月4日至20日办赛，北京成为首个双奥之城。",detail:{background:"2015年7月31日，国际奥委会第128次全会在马来西亚吉隆坡投票确定北京与张家口为2022年冬奥会举办地，北京由此成为既举办过夏季奥运会又举办冬季奥运会的城市。申办时中方提出带动三亿人参与冰雪运动的目标。赛前国家速滑馆、首都体育馆等北京赛区场馆与张家口赛区场馆在2021年完成测试赛。",process:"第24届冬季奥林匹克运动会于2022年2月4日至20日在北京、张家口两个赛区举行，设7个大项、15个分项、109个小项，据国际奥委会与新华社统计，来自91个国家和地区代表团的运动员参赛。开闭幕式在国家体育场举行，闭幕式上进行奥林匹克会旗交接，下一届冬奥会主办城市为意大利米兰—科尔蒂纳丹佩佐。据国际奥委会奖牌榜，中国体育代表团获9金4银2铜列金牌榜第三位，并实现参加全部7个大项、15个分项比赛。第13届冬季残疾人奥林匹克运动会于2022年3月4日至13日在同一赛区举行，中国代表团列金牌榜和奖牌榜首位。",impact:"据国家体育总局2022年发布的带动三亿人参与冰雪运动调查成果，全国冰雪运动参与人数达3.46亿人。区域与场馆安排延续：2022年1月，国家发展改革委等部门印发《京张体育文化旅游带建设规划》，把冬奥赛区纳入区域协同发展框架；据北京市与河北省此后发布，北京赛区竞赛场馆对社会开放，张家口崇礼雪场接待人次在2022至2023雪季回升。",figures:["北京冬奥组委"],place:"北京、张家口",state:"中华人民共和国",sources:["国际奥委会关于2022年北京冬奥会参赛规模与奖牌榜的发布及新华社报道","国家体育总局2022年发布的带动三亿人参与冰雪运动调查成果","国家发展改革委等部门2022年1月印发的《京张体育文化旅游带建设规划》"],tags:["北京冬奥会","冰雪运动","赛后利用"]},related:["cn--2008--c01", "cn--2004--c01"]},
{id:"cn--2022--m01",track:"cn",year:2022,yearApprox:false,dim:"military",weight:3,title:"首艘国产弹射型航母福建舰下水",summary:"2022年6月17日在上海命名下水，舷号18，满载排水量8万余吨。",detail:{background:"2012年9月25日辽宁舰入列，2019年12月17日完全自主建造的首艘国产航母山东舰在海南三亚入列，两舰均采用滑跃起飞方式。第三艘航母在建造中把飞行甲板改为平直通长形式，并配置电磁弹射与阻拦装置。",process:"2022年6月17日，完全自主设计建造的首艘弹射型航空母舰在江南造船厂举行命名下水仪式。据新华社报道，该舰命名为中国人民解放军海军福建舰，舷号18，采用平直通长飞行甲板，配置电磁弹射和阻拦装置，满载排水量8万余吨。下水后福建舰按计划开展系泊试验与内舾装，其后转入海上试验阶段。",impact:"福建舰下水使人民海军进入同时拥有三艘航空母舰的阶段，舰载机起飞方式由滑跃扩展到电磁弹射。据国防部发布，2024年5月起福建舰先后完成多次海上试验；2025年11月5日，据新华社报道，福建舰在海南三亚某军港交付海军，入列后人民海军拥有三艘航空母舰，舰载战斗机与预警机完成弹射起飞与阻拦着舰训练。",figures:["中国船舶集团有限公司"],place:"上海",state:"中华人民共和国",sources:["新华社2022年6月17日关于福建舰命名下水的报道","国防部2024年以来关于福建舰海上试验情况的例行发布","新华社2025年11月5日关于福建舰交付海军的报道"],tags:["福建舰","电磁弹射","航空母舰"]},related:["cn--2012--m01", "cn--2015--m01"]},
];
